    "title": "正太與小豬：武僧的養成之路",
    "genre": "說明文",
    "authors": "課文 ：曾世杰 學習單：陳允捷",
    "strategy_name": "推論策略-找出故事道理",
    "spotlight_raw_text": "閱讀聚光燈\n找出故事道理\n　　你喜歡看故事嗎？相信很多人的答案都是肯定的。故事到底有什麼魔力讓人想要一看再看呢？原來，看故事能讓讀者身歷其境，對主角產生認同感，因而更能體驗到作者想傳達的道理，因此更具說服力，也更容易被記住。\n　　然而，要理解作者在故事裡想傳達的核心理念，不能只有讀者個人的主觀看法，還需要從文本中找到足夠的支持證據。舉例來說：\n　　例一：正太與小豬的第十一段\n原來啊，豬本來小小的，很輕，但牠每天都長大一點點，這一點點的變化，抱的時候根本感覺不出來。每天加重一點點，加重一點點，根本感覺不出來有多難。在滴水穿石、循序漸進的努力之後，正太的筋骨肌肉慢慢適應這漸進的挑戰，過了一千多天，男孩變成身材魁梧󠇠、帥氣挺拔的男人，他跑得快、跳得高，能舉起寺裡最重的石臼，一般的匪徒強盜再也不是正太的對手了。\n　　從上面的文字來看，故事強調了循序漸進的努力所帶來的成長與蛻變。因此，我們可以合理推測，作者希望傳達「滴水穿石，只要持續努力，就有可能成功」的理念。\n　　例二：龜兔賽跑\n有一天，烏龜和兔子在聊天，不知不覺說到誰跑得比較快，於是兔子便邀約烏龜比賽跑步。一開始，兔子大幅領先烏龜，但不久後，兔子便開始輕敵，認為即使小睡一下，烏龜仍追趕不上牠，便到路邊睡覺。結果烏龜後來趕上，等到兔子醒了時，烏龜已經到達終點了。\n\n下面有兩個人的說法，你覺得誰的說法比較合理呢？（請打勾）\n❶小明說：「作者想要表達驕傲會讓人失敗的道理。因為兔子輕敵、驕傲自滿，才導致失敗。」\n□❷大華說：「作者想要表達驕傲會讓人失敗的道理。因為兔子天性懶惰愛睡覺，才導致失敗。」\n　　你答對了，小明的說法比較能被大家接受，因為他是從文章裡面找出支持的理由：「兔子是因為輕敵，認為即使小睡一下，烏龜也追不上牠。」而大華說：「兔子天性懶惰愛睡覺」，文章中根本沒有提到，這是大華自己講的，不是作者想傳達給讀者的道理。所以，要了解作者想用故事想傳達什麼道理，可以從文章中找支持理由。\n　　那麼，找到支持的理由後，如何用簡單的句子表達作者想傳達的道理呢？可以用兩個問題幫助你思考：\n　　❶文章有沒有強調某種品德？（例如：堅持、勇敢、勤奮）\n　　❷主角的經歷讓我們學到什麼道理？（例如：努力就有回報、勇敢挑戰才能成長）\n　　讓我們用例子說明：\n　　村子裡有四個兄弟，經常為小事爭吵，彼此不團結。一天，父親拿來一捆竹筷，讓每個孩子試著折斷它。他們用盡全力，但無法折斷。接著，父親拆開筷子，讓他們一根一根折，結果輕鬆就折斷了。\n　　父親說：「你們就像這捆筷子，團結在一起，就無比強大；若各自為戰，就容易被擊敗。」兄弟們恍然大悟，從此學會合作，村子也因此變得更繁榮。\n❶文章強調了什麼品德（請打Ｖ）？【團結合作  □勤奮努力　】\n❷主角的經歷讓我們學到什麼？（請打Ｖ）\n【團結力量大　　□要聽老人家的話】\n現在就讓我們練習看看吧！\n◎",
    "story_text": "大約在兩百年前，日本 奈良有一個叫正太的男孩，在市集裡幫媽媽賣菜。有兩個腰間掛著長刀的惡霸，經常來這裡欺負農民，跟小攤子收保護費。交不出錢來，就翻人家的菜攤，農民們都敢怒不敢言。有一天，來了一個僧人，身材瘦削󠇡的他，居然敢為農民們打抱不平。兩惡霸不但惡言相向，講沒兩句，居然動起手來。但這位僧人是「興福寺」裡的武僧，工夫了󠇡得，他以一敵二，兩三下就把帶著武器的惡霸打得抱頭鼠竄。旁觀的正太又是害怕，又是佩服，心想：「有一天，我也要去以武術聞名的興福寺學武功」。 正太十四歲時終於進到興福寺，剃度成為小和尚。可是負責教他的師父並沒有教他武功，只是給他一頭小豬，比貓還要小，囑咐他說：「這是你的小豬，養在菜園後面的豬圈󠇡。每天三餐之後，你要把這隻小豬從菜園抱到廚房，餵牠吃廚餘。吃飽了，你再把牠抱回豬圈，這樣明白了嗎？」 正太說：「明白了。」 但他心裡不高興，私下嘀咕著說：「不教我武功就算了，還要叫我養豬？要從平地的豬圈走到半山腰的廚房？」可是他也沒辦法，誰教他是全寺最菜的人呢，只好照做了。 從此，每天三次，正太要去豬圈抱小豬，走到廚房要經過200級的階梯，再跨過20道很高的門檻，等豬吃飽了，他再抱著豬走回去。 「還好，豬這麼小。」正太看著這隻不到一斤重的小豬，心裡想著。 經過了萬紫千紅的春天，暑氣蒸人的夏天，金風送爽的秋天，寒氣逼人的冬天。正太每天抱著豬上上下下。一天又一天，一年又一年，小豬慢慢長大，小豬變中豬，中豬變大豬了。 三年以後，這頭豬已經80公斤了，正太還抱得動這隻豬嗎？ 這時正太也長大了，他變得非常強壯，每天抱著這80公斤的大豬，上下200級階梯，來回20道門檻，一點都不成問題。 這麼重的豬，他怎麼抱得動呢？ 原來啊，豬本來小小的，很輕，但牠每天都長大一點點，這一點點的變化，抱的時候根本感覺不出來。每天加重一點點，加重一點點，根本感覺不出來有多難。在滴水穿石、循序漸進的努力之後，正太的筋骨肌肉慢慢適應這漸進的挑戰，過了一千多天，男孩變成身材魁梧、帥氣挺拔的男人，他跑得快、跳得高，能舉起寺裡最重的石臼，一般的匪徒強盜再也不是正太的對手了。",
    "spotlight_answers": [],
