    "title": "最美的畫面",
    "genre": "說明文",
    "authors": "課文 ：林玫伶 學習單：張明珠",
    "strategy_name": "推論策略-找出文章主旨",
    "spotlight_raw_text": "閱讀聚光燈\n　　「主旨」是作者在寫作時，想要傳達給讀者的主要想法或訊息。我們在閱讀時，如果可以找出文章主旨，就能快速掌握文章要傳達的重點。\n　　我們可以利用底下的三種線索找出主旨。\n線索一：從文章題目找主旨\n文章題目經常會明示或暗示文章的主旨，我們可以想想作者為何訂下這樣的題目，再比對內容，了解作者的想法。\n例如：＜昆蟲的保命妙招＞\n→文章主旨是：　　昆蟲有許多保護自己的方法　　　。\n\n線索二：從文章的開頭或結尾找主旨 \n有些文章在開頭或結尾段提示了文章的主旨。\n例如：＜小孩與糖果＞──本文選自伊索寓言\n　　一個小孩把手伸進裝滿糖果的瓶子中，他想盡可能地抓上一大把。但是當他想要伸出手來時，手卻被瓶口卡住了。他一個糖果也不願意放，因此手緊緊卡住，拔不出來，急得哭了起來。一個路人對他說：「你還是知足點兒吧，只要少拿一半，你的手就不會卡在瓶口了。」人還是要知足，貪多可能危害自己啊。\n→文章主旨是：告訴讀者　人要知足，不可貪心       　。\n\n線索三：從段落大意或關鍵語句找主旨\n有時作者會在文章的某個段落，用關鍵句明示或暗示出想表達的觀點。\n\n例如：＜ＯＯ的重要＞ ──本文修改自國立編譯館\n　　小明放學回家，告訴媽媽：「老師說，學校的春季旅行在四月二日上午出發。參加的同學，要準時到校，在操場上集合。」\n　　媽媽問小明說：「老師說幾點要到學校集合？」\n　　小明想了想說：「好像是八點，差不多跟平常一樣時間到校就好了，沒什麼關係吧。」\n　　媽媽說：「不能說『好像是』，也不能『差不多』!守時是很重要的事。不能遲到，讓大家等你一個人。你明天到學校，一定要再問老師。」\n　　小明說：「我知道了，我明天會再問老師。我也一定會守時，請媽媽放心。」\n1.請先將媽媽的話，用螢光筆畫起來。\n2.從媽媽的話推論「本文主旨」是說明：　守時的重要　　 　。\n◎",
    "story_text": "每個星期天上午，媽媽會帶我搭區間車從瑞穗回富里阿祖家。有時遇到乘客眾多、沒有座位時，媽媽會要我做一件事：用眼睛觀察車廂上的人們在做些什麼！ 因為這項「觀察遊戲」，讓索然無味的火車行程趣味橫生。媽媽提醒，觀察時眼神不可直視或盯著他人看，避免讓人不自在；遇到新奇的事更不能露出吃驚或嘲笑的表情，保持自然和尊重是最關鍵的。我發現，車廂上的人除了睡覺、聊天、吃零食以外，最常見的就是滑手機，不論坐著站著都能滑，好像集體催眠儀式，一進車廂就拿出手機，然後頭也不抬的開始滑，進入網路的世界。但有一次，我發現有個與眾不同的大姊姊，她居然從包包裡拿出書本來閱讀，淺藍色的封面，不知道是什麼書名。她很專心，翻書的樣子很好看，和周圍都在滑手機的人比起來，簡直就像整個車廂裡唯一的主角。 從此，我的「觀察遊戲」就成了「尋找讀書人」。不限車廂，也包括車站、餐館，雖然滑手機者還是遙遙領先，但「讀書人」也偶有所見。瞧！有位背著旅行背包的叔叔在路邊的候車亭等車，他老神在在的拿出一本書看，帥極了。瞧！放學時刻有個小男孩蹲靠在圍牆邊看故事書，大人在一旁嘻嘻哈哈聊天，他完全樂在書中，不為所動。瞧！有位阿姨在便利超商邊喝咖啡邊看書，拿在手上的似乎是一本小說，她閱讀時專注而優雅，真是漂亮啊！我也好想變成這樣。 我問媽媽，為什麼讀書和滑手機會給人這麼不一樣的感覺呢？媽媽說：「我看到一個人在專心閱讀時，也覺得這是一幅令人賞心悅目的畫面，也許是書本只有單純的文字訊息，閱讀過程讓人慢下來、主動思考；而手機裡有太多誘惑性的刺激，為了獲得快感不停滑動，往往只是被動的接收訊息，因此才會帶給旁人不同的感受吧！」 現在，我出門也會在背包裡放一本書，一有空檔就拿出來讀，我猜，現在我也成了別人眼中最美的畫面啦！",
    "spotlight_answers": [],
