    "title": "大自然的氣象小幫手",
    "genre": "說明文",
    "authors": "課文 ：曾世杰 學習單：陳允捷",
    "strategy_name": "摘要策略-列舉結構：找重要細節",
    "spotlight_raw_text": "閱讀聚光燈\n摘要策略──找重要細節(8)天空的雲層很低，(  E  )隨手就能觸碰到。\n\n    這是一篇說明文，主要說明「大自然有許多線索可以幫助人們預測天氣」，作者舉了一些例子，來支持這個觀點。閱讀這樣的文章，你只要抓住這篇文章主要想表達什麼？文章舉了哪些例子來支撐？這些例子有沒有重要的細節？你就抓到文章的重點囉！\n    接下來，我們先來練習找到文章舉了哪些例子？請勾選你覺得比較清楚的答案？\n第三段： □1.蜘蛛      2.蜘蛛結網  \n第五段： □1.蟋蟀      2.蟋蟀叫聲\n第六段： □1.毛小孩    2.毛小孩的行為\n第七段： □1.天空      2.日暈和月暈\n　　你發現了嗎？其實這四段，1和2的答案都可以，但2更具體、清楚喔！\n　　找到例子後，接下來把重要的細節找出來，你就可以抓到文章的重點囉！要怎麼找到重要的細節呢？你要扣住主題，來判斷重要細節。這一課主要是講「推測天氣」，所以我們要把和「推測天氣」有關的重要描述找出來。\n　我們先用「第三段──蜘蛛結網」試試看：\n❶找重要細節：如何從「蜘蛛結網」推測具體天氣？（4選2）\n□1.蜘蛛的絲纖細到幾乎隱形，又怕風、又怕雨。\n□2.如果即將下雨，它們察覺空氣中的濕度，就不會浪費力氣結一張會被雨打壞的大網。\n3.當你看到蜘蛛在結網時，代表空氣是乾的，天氣會穩定，可能還會放晴。\n4.如果你發現蜘蛛網縮得很小，甚至整張網都不見了，也許就是快要下雨的信號。\n❷精簡：請將勾選出的答案，歸納成一句話\n□蜘蛛的網非常脆弱，要小心保護。\n蜘蛛結大網代表天氣晴，縮小或消失則是要下雨。\n□蜘蛛覓食方式會因濕度不同而改變。\n◎",
    "story_text": "明天學校要去露營，你早早就把背包收好了，也查過天氣預報。但你還是忍不住走到陽台，抬頭看看天空，希望明天是個大晴天。就在這時，你發現陽台的角落有一隻蜘蛛正忙著結一個大網。你皺起眉頭，拿起掃把想把牠揮掉。 且慢！你也許不知道，蜘蛛雖小，但牠的結網卻是一個天晴或下雨的好指標哦。 蜘蛛的絲纖細到幾乎隱形，又怕風、又怕雨。如果即將下雨，它們察覺到空氣中的濕度，就不會浪費力氣結一張會被雨打壞的大網。所以，當你看到蜘蛛在結網時，代表空氣是乾的，天氣會穩定，可能還會放晴。相反的，如果你發現蜘蛛網縮得很小，甚至整張網都不見了，也許就是快要下雨的信號。 很有趣吧，其實，大自然裡到處都是線索，告訴人們再來的天氣變化呢。只要你能明察秋毫，留心身邊的事物，也許就能像氣象局那樣預報天氣呢。 有位農夫宣稱，他可以從蟋蟀叫聲的頻率，判斷現在的氣溫大概幾度。經過研究，科學家的確發現氣溫越高，蟋蟀叫得越快。如果錄下草叢裡蟋蟀的叫聲，看看15秒可以叫幾聲，把這個數字加5，再除以2，大概就是現在的氣溫。例如，蟋蟀15秒鐘內叫了45聲，45加5，再除2，等於25。現在的氣溫大概是25度。 除了蜘蛛、蟋蟀之外，你家的毛小孩也會偷偷告訴你天氣的祕密。下雨前，空氣中的濕氣提高，氣壓降低。這種變化改變了狗狗和貓咪毛髮乾爽度，會讓它們坐立難安，它們可能會一直在屋子裡走來走去、搖尾巴、發出低鳴；貓咪則可能變得特別愛躲藏，或身體有不定時的抽搐。那就是快下雨的徵兆！ 除了動物，天空本身也會說話。「日暈三更雨，月暈午時風」，所謂「暈ㄩㄣˋ」就是圍繞著太陽或月亮的光環。這句諺語指出，看到日暈表示夜裡會下雨，看到月暈白天就會起風。因為高空有一層很薄的冰晶雲，把光折射開來，我們才會看到日暈或月暈，這種雲常常是鋒面來臨的前兆，也就是說，看到日暈或月暈，再過半天，很可能就會起風或下雨。此外，我們偶爾會覺得今天的星星或遠山好像變近了，歷歷在目。有文學細胞的人就會寫下「今夜星辰分明，遠山如洗，彷󠇡彿天地間的距離被悄悄拉近」的美麗文句，這通常預示著冷空氣來臨，空氣潔淨，天氣即將轉晴或變涼。 當然，這些自然的線索不是百分之百準確，但連中央氣象局的預報也不是絶對正確啊，它們就像是大自然的小提示。所以，當你擔心明天會不會下雨時，除了查手機上的天氣預報，也可以看看蜘蛛有沒有結網、毛小孩是不是焦躁不安，或是月亮是不是戴了光圈。說不定，大自然早就偷偷告訴你答案了！",
    "spotlight_answers": [],
    "paragraphs": [
      "明天學校要去露營，你早早就把背包收好了，也查過天氣預報。但你還是忍不住走到陽台，抬頭看看天空，希望明天是個大晴天。就在這時，你發現陽台的角落有一隻蜘蛛正忙著結一個大網。你皺起眉頭，拿起掃把想把牠揮掉。 且慢！你也許不知道，蜘蛛雖小，但牠的結網卻是一個天晴或下雨的好指標哦。 蜘蛛的絲纖細到幾乎隱形，又怕風、又怕雨。如果即將下雨，它們察覺到空氣中的濕度，就不會浪費力氣結一張會被雨打壞的大網。所以，當你看到蜘蛛在結網時，代表空氣是乾的，天氣會穩定，可能還會放晴。相反的，如果你發現蜘蛛網縮得很小，甚至整張網都不見了，也許就是快要下雨的信號。 很有趣吧，其實，大自然裡到處都是線索，告訴人們再來的天氣變化呢。只要你能明察秋毫，留心身邊的事物，也許就能像氣象局那樣預報天氣呢。 有位農夫宣稱，他可以從蟋蟀叫聲的頻率，判斷現在的氣溫大概幾度。經過研究，科學家的確發現氣溫越高，蟋蟀叫得越快。如果錄下草叢裡蟋蟀的叫聲，看看15秒可以叫幾聲，把這個數字加5，再除以2，大概就是現在的氣溫。例如，蟋蟀15秒鐘內叫了45聲，45加5，再除2，等於25。現在的氣溫大概是25度。 除了蜘蛛、蟋蟀之外，你家的毛小孩也會偷偷告訴你天氣的祕密。下雨前，空氣中的濕氣提高，氣壓降低。這種變化改變了狗狗和貓咪毛髮乾爽度，會讓它們坐立難安，它們可能會一直在屋子裡走來走去、搖尾巴、發出低鳴；貓咪則可能變得特別愛躲藏，或身體有不定時的抽搐。那就是快下雨的徵兆！ 除了動物，天空本身也會說話。「日暈三更雨，月暈午時風」，所謂「暈ㄩㄣˋ」就是圍繞著太陽或月亮的光環。這句諺語指出，看到日暈表示夜裡會下雨，看到月暈白天就會起風。因為高空有一層很薄的冰晶雲，把光折射開來，我們才會看到日暈或月暈，這種雲常常是鋒面來臨的前兆，也就是說，看到日暈或月暈，再過半天，很可能就會起風或下雨。此外，我們偶爾會覺得今天的星星或遠山好像變近了，歷歷在目。有文學細胞的人就會寫下「今夜星辰分明，遠山如洗，彷󠇡彿天地間的距離被悄悄拉近」的美麗文句，這通常預示著冷空氣來臨，空氣潔淨，天氣即將轉晴或變涼。 當然，這些自然的線索不是百分之百準確，但連中央氣象局的預報也不是絶對正確啊，它們就像是大自然的小提示。所以，當你擔心明天會不會下雨時，除了查手機上的天氣預報，也可以看看蜘蛛有沒有結網、毛小孩是不是焦躁不安，或是月亮是不是戴了光圈。說不定，大自然早就偷偷告訴你答案了！"
    ],
