    "spotlight_raw_text": "閱讀聚光燈\n推論策略—推論情緒和感受\n　　請試著讀底下的文字，再回答一個問題：\n　　「晚間新聞正播報明天的天氣預報，爺爺坐在電視前的沙發上，早就進入夢鄉。」\n問題：爺爺有聽到明天的天氣預報嗎？【有聽到　　沒有聽到】\n在回答這個簡單的問題時，你已經在做推論了。\n你看，「爺爺睡著了，所以沒有聽到天氣預報」根本就沒有寫出來，但你是怎麼知道的？這就是「推論」的過程，最近的流行語叫做「腦補」哦。\n閱讀高手的特色之一，就是超級會推論文章沒有寫出來的細節！\n這篇故事，描述了公車上發生的爭執，文中角色的情緒起伏很大，但故事並沒有直接以文字說明角色的情緒或感受。\n我們可以透過「理解現場情境」與「觀察角色言行」的策略來推敲他們內心的情緒與感受，這樣做還能幫助我們進一步體會故事想傳達的深層意義。\n接下來，我們就來練習推論文中重要角色──「大媽」的情緒和感受。\n一、推論情緒和感受有方法\n　(一)理解現場情境\n小祕訣：推論角色的心情，要先了解角色遇到了什麼情況。試著站在角色的角度想一想：他正在經歷什麼事？可能會有怎樣的感受？\n❶ 找情境：故事一開始，大媽上公車後看到什麼？（請在□打勾）\n一位年輕的女生坐在博愛座，而車上其他人都站著。\n□女生主動起身讓位，大媽馬上坐到了博愛座。\n❷ 推情緒：面對這種情況，你猜大媽的心情是什麼？為什麼？（請在□打勾）\n生氣，因為她認為年輕人不該坐博愛座。\n□驚喜，因為有人馬上讓座給她。\n　（二）觀察角色言行\n小祕訣：角色「說的話、動作、表情、語氣」常常偷偷告訴我們他們的情緒哦！仔細觀察這些線索，就能更準確推測他們的感受。\n段5：大媽眉毛一挑：「我都沒得坐，小孩子裝個病，就有博愛座？真了不起！」\n❶ 情境：生氣\n❷ 找動作：她「眉毛一挑」，這個動作通常表示什麼？（請打勾，可複選）\n   驚訝　　□不高興　　□想笑　　輕視\n❸ 推想法：你覺得「真了不起」的意思是什麼？\n□她年紀小，生病居然膽敢去坐博愛座，勇氣值得稱讚。\n□她在稱讚，司機先生明察秋毫、願意助人，值得稱讚。\n她在諷刺小孩子居然敢坐博愛座，用反話說她很糟糕。\n什麼是「說反話」？\n　　當一個人有情緒時，卻說出和當時情緒相反的話語，很可能就是在「說反話」。　\n1.很生氣卻說出「讚美」的話\n　你犯了嚴重錯誤，夥伴說：「你真的很天才ㄟ!」\n2.或很失望卻說出「感謝」的話\n　導師被你們氣壞了，說：「感謝老天讓我教到你們這班！」 372745-152082500\n　　　　在本課中出現好幾次「說反話」的例子：\n1.段5：大媽明明不高興，卻說國中女生「真了不起！」\n2.段8：明明看大媽不順眼，乘客卻用哪4個字稱讚她? \n　　　　　　【　　　真了不起　　　　　　】\n3.在段5和段8之間還有一句6個字的反話，請你找到，寫在下面。【　　好有正義感呀　　　　　　】\n◎你發現了嗎，文章中沒有明白寫出來的內心的情緒與感受，我們可以透過「理解現場情境」（站在人物的角度）與「觀察角色言行」的策略來推敲喔。\n二、從故事發展，推論「大媽」的情緒或感受變化\n事件\n關鍵線索\n「大媽」的情緒或感受\n1.大媽一上車，看見年輕女生坐在博愛座\n板起臉、嚷道「誰家小孩這麼沒教養...」\n生氣、不滿\n□驚訝、不解           \n2.聽到司機解釋女生身體不舒服\n眉毛一挑，說：「小孩子裝個病...，真了不起！」\n□稱讚女生厲害\n不服氣、語氣諷刺\n3.阿姨出聲挺女生\n提高音量：「唷，好有正義感呀...」\n覺得被針對、更生氣\n□真心佩服阿姨講得很好      \n4.聽到有人出聲批評她\n更大聲回嗆：「….，我說個話也不行了嗎？」\n□覺得開心，有人注意到           被批評，火氣更大了\n5.司機廣播警告\n「我要去投訴你...」\n□想冷靜坐下來             憤怒不甘\n6.老奶奶說女生真的生病了，願意讓座\n臉紅、連忙擺手說：「…我馬上到站了。」\n尷尬、丟臉、自覺理虧\n□還在生氣、不想理會\n7.車子一停\n提著大包小包一溜煙下車\n慚愧或丟臉、急著離開現場\n□假裝什麼也沒發生\n三、推論主旨或目的\n　　從大媽的說話、語氣、動作，我們可以看到，大媽從誤會「生氣」，被提醒理解後，態度轉變為「 慚愧」的過程。最後，讓我們來想想，透過大媽的轉變，這個故事想要告訴我們什麼？（請在□打勾，複選）\n人會因為理解而改變態度　　　□發脾氣是解決問題的最好方法。\n善意可以化解衝突、消除誤會　□不用了解情況，吃虧時就應該生氣\n四、換你試試看，推論其他角色的情緒或感受\n　1. 段六：女生都快哭出來了，勉強要站起來。女生當時最可能的情緒是什麼？【　　　害怕、委屈　　　　　　】\n  2. 段八：人群聲音：「幹嘛呀，都幾歲了，還這樣講話？真了不起！」講這句話的人，最可能的情緒是什麼？【　　忿忿不平／不屑　　】\n\n◎",
    "story_text": "下班時刻，262路公車上有點擠。一位國中女生從前門上車，站在司機旁，搖搖晃晃的，臉色慘白，好像隨時會昏倒的樣子。 司機發現後，對她說：「你不舒服就去坐博愛座！」女生點了個頭表示感謝，走到唯一空著的博愛座坐下。 隔了兩站，一位大媽提著大包小包上車，她一看到博愛座上的女生，立刻板起臉，嚷道：「誰家小孩這麼沒教養，連博愛座都敢坐，全車都站著，你憑什麼坐著？」 司機聽到連忙解釋：「這位同學身體不舒服，是我讓她去坐的。」 大媽眉毛一挑：「我都沒得坐，小孩子裝個病，就有博愛座？真了不起！」 女生都快哭出來了，勉強要站起來。旁邊一位阿姨，伸手按在她肩膀上，一邊搖頭一邊以眼神示意，要女學生不必起身，柔聲說道：「博愛座是給需要的人坐的」。 大媽不甘示弱，提高音量：「唷，好有正義感呀。公車上互不相識，你怎麼知道誰有需要？她有需要，我就沒需要？」乘客開始側目、低聲議論。 「幹嘛呀，都幾歲了，還這樣講話？真了不起！」人群裡突然有人路見不平，大聲的說，公車裡漸漸有了火藥味。 大媽更大聲回道：「現在是怎麼了，我説個話也不行了嗎？」 這時廣播裡傳出司機的聲音：「這位小姐，請控制自己的音量，任何人若再干擾到其他乘客，我都會請他下車。」 大媽尖聲嚷了起來：「干擾？干擾什麼？你這話是說我嗎？我要去投訴你這個不講理、不守規矩的…。」 眼看局面就要不可收拾，國中女生隔壁一位頭髮斑白的老奶奶再也看不下去了，她伸出滿是皺紋的手，摸了摸女生的額頭，轉頭看著大媽說：「這位太太，年輕人真的生病了，你怎麼還強逼人家讓座？你需要座位，我讓位給你好了。」她一邊說一邊顫顫巍巍的站了起來。 大媽尷尬了，臉一下子漲得通紅，連忙擺手說：「您坐，您坐，我馬上到站了。」車子一停，大媽提著大包小包一溜煙的下了車。老奶奶再緩緩坐下時，全車爆出一陣掌聲。 這時司機的廣播傳來：「謝謝阿嬤，謝謝大家，今天真是個美好的一天。」",
