    "title": "黃絲帶",
    "genre": "記敘文",
    "authors": "課文 ：曾世杰 學習單：陳淑麗",
    "strategy_name": "推論策略-推論情緒和感受",
    "spotlight_raw_text": "閱讀聚光燈\n推論策略—推論情緒和感受\n　　前面兩課我們已經學過怎麼透過「觀察角色言行」的策略，來推敲人物內心的情緒與感受。我們繼續來練習推論文章中角色的情緒和感受，並從這些情緒的變化，進一步瞭解作者想要告訴我們的事。\n一、從故事發展，推論「男人」的情緒或感受\n    這個故事最重要的角色是──「男人」，我們先從故事發展找出主要事件，接著從關鍵線索中，寫出你對男人情緒或感受的推論。（答案合理即可）\n(參考詞彙：平靜、難過、思念、愧疚、後悔、焦急、感動、釋懷、喜悅)\n事件\n關鍵線索\n「男人」的情緒或感受\n1.火車初遇學生\n看著學生嬉鬧，露出微笑。\n平靜\n2.聽學生唱〈故鄉〉\n跟著哼唱，哽咽，視線模糊，臉埋手裡，肩膀抽動。\n難過、思念\n3.談坐牢過去\n哽咽說：「我真是對不起老婆。」\n愧疚、後悔\n4.火車接近三民站\n\n緊張\n5.看見滿樹黃絲帶\n一邊哭一邊笑說：「我要回家了。」\n釋懷、喜悅\n二、從情緒變化，推論返鄉之旅對男人的意義\n　　「男人」情緒或感受的變化是什麼？請推論這趟返鄉之旅對男人的意義是什麼？（請選出你認同的想法，在□打勾，可複選）\n□在旅途中情緒起起伏伏，最終落淚，顯示他仍然無法放下過去的傷痛。　　　\n從回憶過去的後悔到看見黃絲帶的激動，表示長久壓抑的愧疚得到釋放和原諒。\n□雖一度難過與緊張，但最後哭一哭就好了，這趟旅程只是情緒的發洩。\n從一開始的平靜到被勾起回憶，讓他一路懷疑自己是否已經準備好要回家。\n三、從故事發展，推論「學生」的情緒或感受\n    接著我們來推論學生的情緒或感受。（答案合理即可）\n（參考詞彙：尷尬、輕鬆、開心、關心、同情、緊張、激動）\n事件\n關鍵線索\n「學生」的情緒或感受\n1.上車時\n嘻笑吵鬧、互相調侃、唱歌聊天\n 輕鬆、開心\n2.發現男人落淚\n小心翼翼的走近男人，鼓起勇氣問：「大哥，你還好嗎？」\n 關心\n3.聽完男人的故事\n眼眶泛紅，拍男人的手說：「別擔心，…」\n 同情\n4.火車接近三民站\n圍在窗邊，心中忐忑不安\n 緊張\n5.看見黃絲帶\n歡呼鼓掌，高喊「祝福你！」\n 開心、激動\n四、從「學生」情緒變化，推論角色的學習\n　　學生們從「輕鬆嘻笑」到「熱烈祝福」，這段情緒變化反映了什麼樣的心理歷程？請選出一項你最認同的描述（請選出你認同的想法，在□打勾，可複選）\n學生原本只想開心玩樂，卻被男人的故事感動，變得真心想關心他。\n□學生一開始沒有很在意，但聽完男人的故事後，變得更關心他，也更尊重他。\n□學生本來只是出於禮貌安慰他，但看到黃絲帶後，真的感受到希望和溫暖。\n學生一開始很吵鬧，但最後一起為男人鼓掌祝福，說明他們學會了關心別人、支持別人。\n◎",
    "story_text": "從臺北開往臺東的自強號。車廂裡只有十幾個高中生，和一位理著平頭，看來三十歲出頭的男人。 看來是學校社團的校外活動，學生們穿著「熱血青春」的T恤，他們玩牌，笑著、鬧著、尖叫著、互相嘲弄著。一個男生盯著手上的牌，誇張的說：「哇嗚，宇宙無敵的大好牌，你們末日到了！」綁馬尾的女生立刻調侃：「牌好是一回事，智商也要跟得上才行啊。」眾人爆笑成一團。一旁的男人也露出微笑。 一會兒，一位男生走到男人的座位旁，又歉疚又靦腆的說：「對不起，不知道有沒有吵到您？」男人搖搖頭。男生繼續說：「不好意思，同學們想要唱歌，也許有些大聲，不知道可不可以？想要徵求您的同意。」 「你們唱，沒關係。」男人點點頭，簡短回答。另一頭的學生們歡呼起來。 吉他及歌聲開始飄揚，男人看著窗外飛馳而過的青山與稻田，輕輕的跟著哼唱。然後，這首歌出現了： 在這靜靜的黑夜裡 故鄉故鄉我想起她 在這悠悠的小河畔 故鄉故鄉我想起她 男人一邊聽，一邊跟著哼著唱著，他的聲音哽咽了，他的視線模糊了，最後，他低頭，將臉埋在大手裡，肩膀輕輕抽動。 學生的歌聲低了下來。剛才那位男生小心翼翼的走近男人，鼓起勇氣問：「大哥，你還好嗎？」 男人坐正，拭去眼淚，說：「沒事。」 男生說：「我們唱故鄉的時候，您先是跟著唱，然後就難過起來，您是要回家嗎？」男人停了一下，答道：「是要回家。但已經不知道是不是有家可回了。」他慢慢的說起了自己的故事。 「我很年輕就認識了我美麗善良的妻子，但要結婚時，岳父極力反對，說我沒有錢，沒有學歷，沒有未來。但她還是嫁給我了，我們很快就有了孩子。但岳父的輕蔑與譏諷，我一輩子記得。」他激動起來，彷彿岳父就站在眼前：「我就要賺很多錢，讓你刮目相看！讓老婆小孩有好的生活！」 「可是，為了要賺快錢，我禁不起誘惑，加入一個詐騙團體，後來被抓了，判了18個月。」他哽咽起來：「我真是對不起老婆，岳父的預言都是對的。18個月過去了，上星期我寫了信給她，向她認錯，信裡面寫，我想回家，但不知道她會不會原諒我。」 「我說，我的車會經過三民站附近一棵我們常常約見面的大榕樹，如果妳願意讓我回家，就請在樹枝上綁一條黃絲帶。我若看見黃絲帶，就在玉里下車，回到你身邊。」「但是……」，他眼眶泛紅：「如果我沒有看見黃絲帶，我就不下車，繼續往臺東走。是我對不起你。」 高中生的眼眶也泛紅了，拍拍他的手：「別擔心，也許她早就在等你回家呢。我們都為你祈禱哦。」然後他回到座位，同學們圍過來，大家都知道了男人的處境跟期盼。 火車經過三民站，再過一座橋，就到那棵大榕樹了。年輕人們心中忐忑不安，都湊到窗邊，睜大眼睛。 「哇！」車上爆出歡呼聲，接著是一陣熱烈的掌聲。 那棵大榕樹上，掛著滿樹的黃絲帶，它們在風中翻動，像太陽一樣閃耀著！ 男人站了起來，一邊笑一邊哭：「我要回家了，真的要回家了，謝謝大家。」熱淚盈眶的學生們掌聲更加熱烈，齊聲大喊：「祝福你，祝福你們一家人！」 正是黃昏時刻，夕陽正把回家的路染成黃金般燦爛的幸福顏色。",
