    "spotlight_raw_text": "閱讀聚光燈\n拆詞釋義\n　　在「L1兵來將擋，水來土掩」中，我們學習到了拆詞釋義的方法，使用這個方法的前提是：1.我不知道這個詞的意思; 2.但我知道組成這個詞的字或詞的意思。這種方法可以幫助我們用字義推論出語詞的意思，現在我們來複習一下「拆詞釋義」的步驟。\n❶將目標語詞拆解成較小的單位（字或詞）。\n❷想想看（拆解後的）字或詞的意思。\n❸把這些字詞的意思合併起來，推論目標語詞的完整詞義。\n❹放回句子唸一唸，判斷是否合理。\n❺檢核句子是否合理；如果不合理，可能這個詞不適合這個策略，請嘗試其它的方法（例如上下文推詞義、查字典）。\n例如：「引領」\n❶拆語詞：「引」和「領」。\n❷找個別詞義：引引導；領帶領。\n❸合併(並推論)完整的詞義：引領引導帶領。\n❹放回句子唸一唸：\n讓我們一起看看這些植物老師如何引領科學家走上創新之路！　　　　　　　　　　　　　　　　　　\n　　　　　　　　　　　　　　引導帶領\n　❺檢核：合理，進行下一個任務　　\n　　　　　  ⃞不合理，嘗試其他方法\n現在就讓我們一起練習看看吧！\n1.基礎題：請先圈出目標語詞的個別詞義，再把組成的意思寫下來。\n(1)這種向陽性讓科學家發明了一種能自動調整角度的仿生太陽能板。\n38136172619\n方向\n面向\n向\n太陽\n夕陽\n陽\n特性\n個性\n性\n組合\n面向太陽的特性0\n方向\n面向\n向\n太陽\n夕陽\n陽\n特性\n個性\n性\n組合\n面向太陽的特性\n\n2.進階題：請先寫出目標語詞的個別詞義，再把組成的意思寫下來。\n(1)這些從大自然中獲取靈感，並應用在人類科技的學問，叫做仿生學。\n31469630843\n組合\n模仿生物的科學\n仿\n模仿\n生\n生物\n學\n科學00\n組合\n模仿生物的科學\n仿\n模仿\n生\n生物\n學\n科學\n\n3.挑戰題：請先寫出組成目標語詞的個別字義或詞義，然後推論出語詞的意思。\n(1)探測器可以快速探索廣闊無垠的火星地表。（把「廣闊」當一個詞，不要再拆）注意：拆詞釋義也可能拆成比較小的詞彙，不一定是單一個字。\n❶拆語詞  ❷找個別詞義 \n462602111760\n廣闊\n廣大遼闊\n無\n沒有\n垠\n邊界00\n廣闊\n廣大遼闊\n無\n沒有\n垠\n邊界\n\n❸合併(並推論)完整的詞義：\n47501371993\n廣大遼闊沒有邊界　　　　　00\n廣大遼闊沒有邊界　　　　　\n\n❹放回句子唸一唸     \n❺檢核： ⃞合理       \n ⃞不合理，嘗試其他方法\n(2)沙馬雷可以探索危機四伏的災難現場。（把「危機」當一個詞，不要再拆）注意：拆詞釋義也可能拆成比較小的詞彙，不一定是單一個字。\n403761398006\n危機\n危險的情況\n伏\n埋伏、潛伏\n四\n四處、四周00\n危機\n危險的情況\n伏\n埋伏、潛伏\n四\n四處、四周❶拆語詞  ❷找個別詞義\n\n❸合併(並推論)完整的詞義：\n4032257004\n形容環境四處潛藏危險。\n可能的危險在四周埋伏　　　0\n形容環境四處潛藏危險。\n可能的危險在四周埋伏　　　\n\n❹放回句子唸一唸\n❺檢核： ⃞合理       \n ⃞不合理，嘗試其他方法\n2946400596900",
    "story_text": "你知道嗎？植物在地球上已經存在了約五億年，經過漫長的演化，發展出各式各樣、驚人的適應能力。它們的生存智慧，為科學家帶來無限的啟發，讓我們一起看看這些「植物老師」如何引領科學家走上創新之路！ 會飛的小種子 當楓樹的種子從樹上飄落時，會像小直升機一樣旋轉降落。這種特別的飛行方式讓它們能夠被風帶到更遠的地方，找到適合生長的新家。科學家受到楓樹種子的啟發，設計了一款名叫沙馬雷（Samarai，是日本武士的意思）的飛行機器人！ 沙馬雷和一般的無人機不一樣，它只有一片翅膀，因此構造簡單，體積更小，更省電，而且沒電時，它會盤旋而下，比較不會摔壞！它和一般無人機一樣，可以垂直起降，在狹窄的空間靈活飛行。內建攝影機時，可以幫助人類進行搜救、環境監測，甚至探索危機四伏、險象環生的災難現場。 跟著太陽轉的花 早晨，向日葵的花朵面向東方，到了下午則轉向西方，整天彷彿在追逐太陽！這種「向陽性」讓科學家發明了一種能自動調整角度的仿生太陽能板，讓太陽能發電變得更有效率！ 一般的太陽能板角度是固定的，當太陽移動後，吸收陽光的效率就會降低。但這種仿生設計模仿向日葵的特性，讓太陽能板可以「跟 著太陽轉」，整天都能吸收到最多陽光，發電量大幅提升。這項技術 已經在多個國家被應用，為地球提供更多乾淨能源！ 滾來滾去的草球 西部電影裡，常看到有些乾草球在荒涼大地上滾來滾去，那就是風滾草！風滾草其實是某些植物成熟或枯死後，枯乾的莖與葉形成一團30到100公分的大草球，強風吹起時，草球就會在原野上翻滾和轉動，藉此散播種子。在某些地方，過多的風滾草會影響農田，甚至引發火災，是個大麻煩。 但這種「滾來滾去」的方式，讓科學家發想出探索火星的新方法！美國太空總署（NASA）發現，他們設計的火星探測車在惡劣的地形上移動速度很慢，而根據風滾草設計的探測器可以靠火星上的強風滾動，快速探索廣闊無垠的火星地表。奧地利研究團隊甚至設計了一種直徑五公尺的探測器，內部裝滿科學儀器，希望未來能讓它滾遍火星北極區，幫助人類更了解這顆紅色星球！ 科學家從動物、植物獲取靈感，模仿它們的特性，設計出有用的科技產品，這個學問叫做仿生學。植物看似不動，但它們經過億萬年的演化，擁有許多聰明的生存技巧，為人類帶來無限啟發。下次，當你看到身邊的花草樹木，不妨仔細觀察，說不定也會從植物身上激發出好點子呢！",
    "spotlight_answers": [],
