    "title": "災難預言準不準？",
    "genre": "說明文",
    "authors": "課文 ：林玫伶 學習單：張明珠",
    "strategy_name": "拆詞釋義、從上下文推測詞義",
    "spotlight_raw_text": "閱讀聚光燈\n拆詞釋義、從上下文推測詞義\n　　閱讀文章時，如果遇到不懂的詞語，可以想一想：\n如果我知道詞裡的字義用「拆詞釋義」，把熟悉的字義組合起來，推想詞的意思。\n如果我不知道詞裡的字義用「上下文推詞義」，觀察前後句線索，猜測詞的意思。\n162687029845000    這兩種方法都可以使用，重點在於：你對詞裡的字是否熟悉，再決定要用哪一種。\n\n拆詞釋義：\n以",
    "story_text": "一名叫龍樹諒的日本漫畫家，因1999年出版的漫畫《我所看見的未來》而受到關注。她在作品中描繪了自己夢境中出現的災難場景，竟與2011年3月11日的日本東北大地震高度雷同，因此引發了熱議。不久後，人們又注意到她漫畫中另一個夢境：一場大地震將引發巨大海嘯，襲擊日本及亞洲周邊地區，包括臺灣，發生時間就在2025年7月5日。 這項預言在社群媒體上廣泛流傳，讓許多人感到不安，大量的外國旅客甚至取消或延期前往日本，有些日本民眾也表示會選擇這天與家人團聚，準備應對可能來臨的大災難。7月5日，預言中的世界末日到了，全日本屏󠇡息以待，等待災難的到來。所幸，這場預言最終沒有成真，7月5日是另一個平靜的週末。 災難預言不是什麼新鮮事，幾百年前、甚至更早的古代就已經有了！ 16世紀，法國預言家諾查丹瑪斯寫下許多神祕的詩，很多人相信他預言了戰爭、地震，甚至現代的科技革命。他的詩模模糊糊，有人根據其中一首預測1999年世界會完蛋，結果大家還是活得好好的！另外，中美洲有一個已經滅亡三百多年的瑪雅帝國，這個古文明以天文、數學和曆法聞名。根據流傳下來的瑪雅曆法，有人預測世界會在2012年的12月21日結束，屆時地球將面臨火山爆發、地震、海嘯等大災難，但到了那天，地球照樣轉動。這些有名的預言聽來玄妙，但大多數只是鬧劇一場，證明預言不過是人類想像力的延伸。 然而，相信災難預言的人還真不少，為什麼呢？首先，預言通常含糊其辭，比如「天空會降下火光」，這句話可以套用到火山爆發、戰爭，甚至煙火秀，讓人覺得「預言好像應驗了」。再來，人類天生愛聽故事，災難預言就像恐怖片，越害怕就越想聽、越想看。加上網路盛行後，有人把預言炒得繪聲繪影，點閱率一飆，信的人就更多了。 心理學研究提供了一些線索，幫助我們理解為什麼人們容易相信災難預言。首先是「倖存者 偏誤」，意思是，我們傾向只注意那些看似應驗的預言，而忽略大量沒有應驗的預測。例如，某人預測「某年會有大地震」，如果地震真的發生，大家會說「他好準」！但他可能還預測了許多從未發生的災害，這些不準的預言卻被遺忘。其次是「確認偏誤」，指的是我們會特別尋找符合自己信念的證據。例如，聽到「某地將發生災難」，只要那個地方有任何異常，比如暴風雨或停電，我們就以為預言成真。心理學家還發現，人類對不確定性感到不安，當未來充滿未知時，災難預言反而像一盞指引的燈，哪怕不準確，也讓人暫時感到安心。 大多數災難預言缺乏科學根據，僅靠模糊語言吸引注意，我們無須過度恐慌。當然，災難預言並非全無價值，它們有時能喚起人們對重要議題的關注。例如，2012年的瑪雅預言曾激發全球對氣候變遷與資源保護的討論；2025年7月5日大地震預言也讓人們重新重視地震防災準備。事實上，真正能夠保護我們的，是平時就要具備風險意識與防災能力，多留意專業機構的資訊，比聽信末日的傳言要可靠得多了。",
    "spotlight_answers": [],
    "paragraphs": [
      "一名叫龍樹諒的日本漫畫家，因1999年出版的漫畫《我所看見的未來》而受到關注。她在作品中描繪了自己夢境中出現的災難場景，竟與2011年3月11日的日本東北大地震高度雷同，因此引發了熱議。不久後，人們又注意到她漫畫中另一個夢境：一場大地震將引發巨大海嘯，襲擊日本及亞洲周邊地區，包括臺灣，發生時間就在2025年7月5日。 這項預言在社群媒體上廣泛流傳，讓許多人感到不安，大量的外國旅客甚至取消或延期前往日本，有些日本民眾也表示會選擇這天與家人團聚，準備應對可能來臨的大災難。7月5日，預言中的世界末日到了，全日本屏󠇡息以待，等待災難的到來。所幸，這場預言最終沒有成真，7月5日是另一個平靜的週末。 災難預言不是什麼新鮮事，幾百年前、甚至更早的古代就已經有了！ 16世紀，法國預言家諾查丹瑪斯寫下許多神祕的詩，很多人相信他預言了戰爭、地震，甚至現代的科技革命。他的詩模模糊糊，有人根據其中一首預測1999年世界會完蛋，結果大家還是活得好好的！另外，中美洲有一個已經滅亡三百多年的瑪雅帝國，這個古文明以天文、數學和曆法聞名。根據流傳下來的瑪雅曆法，有人預測世界會在2012年的12月21日結束，屆時地球將面臨火山爆發、地震、海嘯等大災難，但到了那天，地球照樣轉動。這些有名的預言聽來玄妙，但大多數只是鬧劇一場，證明預言不過是人類想像力的延伸。 然而，相信災難預言的人還真不少，為什麼呢？首先，預言通常含糊其辭，比如「天空會降下火光」，這句話可以套用到火山爆發、戰爭，甚至煙火秀，讓人覺得「預言好像應驗了」。再來，人類天生愛聽故事，災難預言就像恐怖片，越害怕就越想聽、越想看。加上網路盛行後，有人把預言炒得繪聲繪影，點閱率一飆，信的人就更多了。 心理學研究提供了一些線索，幫助我們理解為什麼人們容易相信災難預言。首先是「倖存者 偏誤」，意思是，我們傾向只注意那些看似應驗的預言，而忽略大量沒有應驗的預測。例如，某人預測「某年會有大地震」，如果地震真的發生，大家會說「他好準」！但他可能還預測了許多從未發生的災害，這些不準的預言卻被遺忘。其次是「確認偏誤」，指的是我們會特別尋找符合自己信念的證據。例如，聽到「某地將發生災難」，只要那個地方有任何異常，比如暴風雨或停電，我們就以為預言成真。心理學家還發現，人類對不確定性感到不安，當未來充滿未知時，災難預言反而像一盞指引的燈，哪怕不準確，也讓人暫時感到安心。 大多數災難預言缺乏科學根據，僅靠模糊語言吸引注意，我們無須過度恐慌。當然，災難預言並非全無價值，它們有時能喚起人們對重要議題的關注。例如，2012年的瑪雅預言曾激發全球對氣候變遷與資源保護的討論；2025年7月5日大地震預言也讓人們重新重視地震防災準備。事實上，真正能夠保護我們的，是平時就要具備風險意識與防災能力，多留意專業機構的資訊，比聽信末日的傳言要可靠得多了。"
    ],
