        "預言例子",
        "1.日本漫畫中的夢境\n(1)漫畫內的夢境災難場景和後來2011年東日本大地震高度雷同。\n(2)2025年7月5日會發生大地震和海嘯，引發社會恐慌。\n2.法國\n  16世紀預言家諾查丹瑪斯詩句預言1999年世界末日。\n3.瑪雅帝國\n瑪雅曆法被解讀為2012年12月21日世界末日。\n上述三則災難預言，均【 未發生 】。"
