    "spotlight_raw_text": "閱讀聚光燈\n觀點找支持理由\n　　　本課課文主要描述周思齊在職棒時的歷程，不僅凸顯了周思齊的人格特質，也傳達了作者的觀點。底下再次複習什麼是觀點和支持理由：\n觀    點：就是對事情的看法、意見。\n支持理由：可以說服別人接受觀點的「證據（事實）」\n7556506477000\n\n   接著讓我們再次回到文章，找出觀點及搭配的支持理由吧！\n◎",
    "story_text": "還記得那個努力練球、不怕認輸但很不服輸的周思齊嗎？ 他念高中時，學校只重視比賽成績，英文畢業考居然只考26個英文字母的大、小寫。不過，周思齊並沒有放棄學習，反而選擇到重視學業的輔仁大學就讀。他從基礎開始慢慢學起，到最後不但能看原文書，還學會和運動有關的科學知識，同時也繼續打他最愛的棒球。 大學畢業，周思齊進入職棒，但一直到第三年才當上先發球員。而原本以為終於有機會大展身手，沒想到卻遇到了棒球生涯的極大考驗。他的球隊被黑道掌控，以威脅、利誘的方式要他們打假球。 那時球員平均月薪不到十萬，對方卻拿出五、六百萬做為打假球的簽約金，並強調後續還有更多獎金。也恐嚇球員知道他們的身家資料及家裡地址等，甚至桌上一邊放錢、一邊放槍，要球員做出選擇。每次出外比賽，住進飯店後，周思齊總是膽戰心驚，有好幾次為了不讓黑道找到，只好和隊友躲在衣櫃，或冒著摔下去的危險待在狹小的陽台，假裝不在房間。有一次被大哥找去，他還假裝接電話趁機逃跑，一路跑到黑漆漆的山路樹叢旁躲著，等待機會攔車回去。這一整年，他都活在各種未知的恐懼中，但他沒有妥協，也不願違背自己的良心，不願辜負他最愛的棒球和支持他的球迷。 後來假球案爆發，全隊有2位教練和12位球員遭到起訴，只有他、總教練和內野手搭檔三人沒有打假球的嫌疑。隔年，他換了球隊，卻又再次陷入打假球風暴，不過他仍然堅守信念、沒有退讓。在獲得最佳外野手時，他曾說：「當時外在條件不能選擇也很難控制，但我一直告訴自己要堅持自己，不管環境如何，每場比賽我都是全力以赴。」 熬過了那段黑暗時光，2021年，他和中信兄弟終於拿下了等了十年的總冠軍。中華職棒成立35年來，球員的平均職業運動生涯只有4.8年，能夠打20年的不到5人，而周思齊就是其中之一。他的好品格、好人緣與好實力受到大家的肯定。除了打好球外，周思齊也創辦了球芽基金會，幫助偏鄉地區的孩子打棒球，並強調閱讀與學習的重要。同時他自己也考上師大臺灣史研究所，希望研究臺灣的棒球歷史與文化。 翻開他的自傳，一雙手的照片清楚呈現在眼前，又大又厚的手掌上，有一層層的厚繭、反覆脫皮的痕跡及大大小小的疤痕，手骨甚至有點變形，這些都是他堅持與努力的痕跡。也許天分可以讓我們一開始走得更順利，但能不能走到最後，靠的是努力；而心中的信念和堅持，則能幫助我們不走錯方向。 引退那天，大家唱著五月天的〈倔強〉，歌詞說：「無論這世界如何變化，始終堅持自己的信仰。」這句話，就像是為他而寫的。",
    "spotlight_answers": [],
