    "strategy_name": "推論策略-從言行推論人物特質",
    "spotlight_raw_text": "閱讀聚光燈\n推論人物特質\n1.如何推論人物特質：我們可以從一個人說的話、做的事來推論人物特質。\n2.閱讀時讀出角色的特質，可以幫助我們理解與預測故事的情節喔！\n806451188085\n「我考上了，是有公費的師範學院，謝謝你，謝謝你。」00\n「我考上了，是有公費的師範學院，謝謝你，謝謝你。」80645425450\n「為了要活下去，我必須要有策略。我打電話給同學時，很誠懇的介紹補習的優點，考慮同學們離家背井的各種需求，有時還幫忙他們找租屋。」00\n「為了要活下去，我必須要有策略。我打電話給同學時，很誠懇的介紹補習的優點，考慮同學們離家背井的各種需求，有時還幫忙他們找租屋。」1.說的話 文章中，主角小花說了兩句話：\n(1)從（第句   □第句），我推論小花是一個   聰明   的人，因為她做事情有方法，介紹同學離鄉補習，會考慮與解決同學的需求。\n(2)從（□第句  第句），我覺得她是一個    懂得感恩      的人，因為她考上公費生，第一時間打電話給妹妹，感謝妹妹的幫助。\n104140358775\n放學後、寒暑假時為了多賺點錢，小花練就了一身俐落的身手。\n小花窮怕了，她跟媽媽爭取，希望再給一次機會，靠著教育翻身。\n在補習班打工時，她用很短的時間成為了業績第一名的工讀生。\n不知道哪裡來的勇氣，她到一家婦產科診所應徵成黑牌護士。\n在大學期間，她除了讀書，也繼續打工、接家教。00\n放學後、寒暑假時為了多賺點錢，小花練就了一身俐落的身手。\n小花窮怕了，她跟媽媽爭取，希望再給一次機會，靠著教育翻身。\n在補習班打工時，她用很短的時間成為了業績第一名的工讀生。\n不知道哪裡來的勇氣，她到一家婦產科診所應徵成黑牌護士。\n在大學期間，她除了讀書，也繼續打工、接家教。2.做的事 文章中，主角小花的行為或反應\n→從 、、 的行為，我覺得小花是一個  努力  的人，因為她花了很多時間打工賺錢，都不休息。\n→從 、　  的行為，我覺得小花是一個  勇敢  的人，因為\n        她不甘於現狀，願意去爭取自己的益                 。\n3.文章最後一段提到：「小花和姊姊都努力過人，但是教育決定了他們人生進路的差異。」請問作者對於「教育」抱持著怎樣的信念或想法？\n教育可以脫離貧窮  □努力是教育的開始 　教育帶來改變的希望。\n71120487680\n請根據文章內容，選出最適合的答案，要讀完每一個選項再作答。00\n請根據文章內容，選出最適合的答案，要讀完每一個選項再作答。27305337\n七",
    "story_text": "小花在鄉下長大，三歲時，爸爸就過世了，家中食指浩繁，她是六個嗷嗷待哺的孩子中的第五個，底下還有一個雙胞胎妹妹。媽媽目不識丁，又沒有一技之長，只能到處打零工。課外讀物、雞鴨魚肉、零食對小花家來說都是奢侈品。小花入小學後，發現同學家裡有兒童繪本、小說、漫畫，而反觀自己的家，家裡出現的文字，除了教科書，就只有日曆和黃曆了。學校遠足時，她眼睜睜的看著同學啃著紅艷的大蘋果，只能撇開目光，嚥下自己的口水。偶爾鄰居給了一顆糖，小花捨不得吃，總要留到睡前，含在嘴裡再慢慢睡去，天真的她認為，這樣才可以吃一整夜，小花長大後成為牙醫的常客，才知道這天真的代價真不小啊。小花家到學校要走半小時，那時學校沒有營養午餐，小朋友要自己帶便當或回家吃午餐，因為家裡窮便當菜色太差，小花選擇回家吃午餐，常吃完午餐，再走半小時的路回學校，肚子又餓了。 家裡這麼窮，大姊、二姊不得不犧牲學業，國小畢業就到成衣廠工作。二姊國小畢業時拿了全校第一名的縣長獎，六年級的老師還特別來家裡，勸媽媽讓二姊繼續讀國中，但父親才剛過世，二姊一心想幫助家庭：「我只希望早一點開始賺錢貼補家用，不然家裡怎麼撐得下去？」其他的孩子也沒能閒著，放學後都要到工廠做童工。小花六歲就開始打工，她回憶道：「第一份工作是在拜拜的金紙上點上金箔，工作環境又熱、粉塵又多；小二就換到一個食品加工廠做包裝工作，工資是按件計酬，為了多賺點錢，我練就了一身俐落的身手，但不管包裝的速度多快，一天的所得還是很有限。」小花還曾在鞋廠，坐在彌漫著有機溶劑味道的生產線旁，用強力膠把一直送到眼前來的涼鞋黏上鞋底，惡劣的工作環境讓小花至今餘悸猶存。她從來就不喜歡放學後的時間，更不愛寒暑假，因為只要醒來，就是做不完的工作。 小花的功課當然因此也沒能太好，大概只能維持中等程度，高中畢業那年，她大學聯考落榜了，媽媽要求她去找個工作幫忙賺錢，但小花窮怕了，她跟媽媽爭取，希望再給自己一次機會，靠著教育翻身。媽媽終於點頭：「好吧，但再來你的學費、生活費都得自己想辦法了。」小花的選擇，讓她面臨新的挑戰──她必須離開鄉下的家，到台中去補習，她必須在短時間內賺到高額的補習費，還有一年的房租、伙食費用。她先到補習班打工，工作內容是打電話找落榜生來補習，她在很短的時間就成了業績第一名的工讀生。她說：「為了要活下去，我必須要有策略。我打電話給同學時，很誠懇的介紹補習的優點，考慮同學們離家背井的各種需求，我有時還幫忙他們找租屋。」補習費賺到了，開學在即，但生活費還沒有著󠇤落。還好，高職畢業先就業的妹妹伸出援手，願意支援一年的生活費。 補習一年後，小花再次參加大學聯考。等待放榜的日子，真是難熬，總不能再向妹妹伸手。她不知哪裡來的勇氣，到一家婦產科診所應徵上了黑牌護士，先是包藥、跟診，工作幾天後，院長就讓她開始替病人打針、為新生兒洗澡，後來甚至要進手術室幫忙。小花還記得，值大夜時，只有她一個人，要用木製的聽診器聽孕婦腹中的胎兒心跳，她是生手，經常聽不到，焦慮緊張到極點，擔心自己會犯錯害了孕婦。 放榜了。小花第一個打電話給妹妹，她的聲音有點激動：「我考上了，是有公費的師範學院，謝謝你，謝謝你。」 小花格外珍惜這得來不易的大學教育機會，讀書之外，她仍然繼續打工，學期間和寒暑假都接了家教，家教的收入比貼金箔、包糖果、黏鞋底好太多了，她開始可以寄錢回去給媽媽。她成績不錯，畢業時被學校留下來當助教，後來又在職念了碩士和博士。 現在小花是國立大學的教授，她的教學和研究表現傑出，拿過多次獎勵。坐在大學研究室裡的她，回頭想到在工地積勞成疾、英年早逝的大姊，一直逐戶為人打掃的二姊，她心裡又抱歉又感謝，兩位姊姊為了庇蔭弟弟妹妹，犧牲了教育的機會，付出一輩子的代價。 心存感激的她，終於靠著教育翻身。她和姊姊們都努力過人，但是，教育，決定了她們人生進路的差異。",
