    "title": "垃圾食物的誘惑與代價",
    "genre": "說明文",
    "authors": "課文 ：林玫伶 學習單：巫怡蓉",
    "strategy_name": "摘要策略-刪除法找重點（刪除舉例",
    "spotlight_raw_text": "閱讀聚光燈\n摘要策略—刪除法找重點\n本課是一個說明文，為了讓讀者更容易理解文章，說明文的作者常會加入許多細節作為補充說明。然而，這可能使重點變得不明顯。因此，我們可以運用刪除法把不重要的訊息刪除，留下文章段落的重點。\n哪些細節可以刪除呢？首先可以刪的，就是「舉例」的文字。\n作者舉例時，經常會用「舉例」、「例如」、「如」、「像」這樣的關鍵詞。\n來看看下面這段文字，我們可以用❶❷❸的步驟，刪除舉例的文字：\n1843764236500臺東有名的風景區，如鹿野高台、池上伯朗大道等，都是遊客們流連忘返的地方。\n❶我們可以刪除「如」後面的文字，因為鹿野高台、池上伯朗大道都是「舉例」說明臺東有哪些風景區。注意，這些補充說明的文字，刪除後，也必須保留原文的意思，不能改變。\n1843773914300臺東有名的風景區，如鹿野高台、池上伯朗大道等，都是遊客們流連忘返的地方。\n❷留下段落重點臺東有名的風景區都是遊客們流連忘返的地方。     \n❸判斷❷留下的重點，它主要的意思是否和原文相同？（打勾）\n是，留下的重點，主要的意思和原文相同。\n□否，留下的重點，主要的意思和原文不同。\n　　你發現了嗎，文章段落經過刪除法後，就可以更快找到重點，接下來就讓我們來練習看看吧！\n\n◎",
    "story_text": "放學後，你是否經常忍不住想來包洋芋片，再喝上一杯冰涼的可樂？與朋友相聚時，你是否喜歡來點金黃酥脆的炸雞薯條，邊聊天邊喝奶茶？當你聞到路邊烤香腸的誘人香味，看到色彩繽紛的糖果時，你是否會迫不及待掏出零用錢，買來大快朵頤？ 如果是，你知道你吃下的正是所謂的「垃圾食物」嗎？別誤會，這裡的「垃圾」並不是指扔在地上不要的廢棄物，而是指高糖、高鹽、高脂肪的食物，例如餅乾、洋芋片、蛋糕、炸物、熱狗和香腸等加工食品，還有奶茶、可樂、汽水或瓶裝果汁等高糖飲料。 然而，垃圾食物卻是這麼好吃，讓人一口接一口停不下來，到底是什麼原因呢？首先，它們的味道都經過精心調配，製造商會找到鹽、糖、油的完美比例，讓食物又香又美味，像外酥內軟的雞塊、酸酸甜甜的糖果、又脆又鹹的洋芋片、香甜濃郁的巧克力……，都讓人著迷，難以抗拒。其次，這些食物裡的脂肪和糖份會快速被身體吸收，促使大腦釋放多巴胺。多巴胺是一種可以帶來快樂的神經傳導物質，因此，在吃垃圾食物時，大量的多巴胺不但會為你帶來滿足快樂，當你焦頭爛額或愁眉不展時，也能降低你的焦慮憂愁。大腦會記住這種快樂無憂的感覺，下次一聞到熟悉的味道，就會忍不住想吃。最後，垃圾食品常和快樂時光連結在一起，例如生日時吃蛋糕、看電影配爆米花、邊逛街邊吃薯條，再加上有些垃圾食物的包裝和廣告令人垂涎欲滴，彷彿有個看不見的小精靈在誘惑我們：「來一口吧，吃了會開心喔！」 但糟糕的是，垃圾食物缺乏足夠的蛋白質和膳食纖維，雖然能帶來美味和快樂，但它們不但有超高的熱量，而且會快速升高你的血糖，這種不正常的血糖動盪來得急去得快，所以你很快就會覺得肚子餓，還想再多吃一點。還吃？你不胖才怪！許多人會把這些垃圾食物看成開心解憂的「戰友」，但它們真實身分其實是「損友」，長時間與其相伴，就可能導致營養失衡，影響發育和成長；久而久之，除了肥胖，蛀牙、高血壓、心臟病，甚至糖尿病也會不請自來！ 青少年的你正處於快速成長期，同時又面臨學業與人際等各種壓力，很容易選擇方便、好吃的垃圾食物作為「加油站」。雖然偶爾吃點無傷大雅，但千萬不要讓這些誘惑主導你的飲食習慣。別忘了，垃圾食物帶來的快樂是短暫的，但帶來的傷害卻會讓你付出長久的代價！",
    "spotlight_answers": [],
    "paragraphs": [
      "放學後，你是否經常忍不住想來包洋芋片，再喝上一杯冰涼的可樂？與朋友相聚時，你是否喜歡來點金黃酥脆的炸雞薯條，邊聊天邊喝奶茶？當你聞到路邊烤香腸的誘人香味，看到色彩繽紛的糖果時，你是否會迫不及待掏出零用錢，買來大快朵頤？ 如果是，你知道你吃下的正是所謂的「垃圾食物」嗎？別誤會，這裡的「垃圾」並不是指扔在地上不要的廢棄物，而是指高糖、高鹽、高脂肪的食物，例如餅乾、洋芋片、蛋糕、炸物、熱狗和香腸等加工食品，還有奶茶、可樂、汽水或瓶裝果汁等高糖飲料。 然而，垃圾食物卻是這麼好吃，讓人一口接一口停不下來，到底是什麼原因呢？首先，它們的味道都經過精心調配，製造商會找到鹽、糖、油的完美比例，讓食物又香又美味，像外酥內軟的雞塊、酸酸甜甜的糖果、又脆又鹹的洋芋片、香甜濃郁的巧克力……，都讓人著迷，難以抗拒。其次，這些食物裡的脂肪和糖份會快速被身體吸收，促使大腦釋放多巴胺。多巴胺是一種可以帶來快樂的神經傳導物質，因此，在吃垃圾食物時，大量的多巴胺不但會為你帶來滿足快樂，當你焦頭爛額或愁眉不展時，也能降低你的焦慮憂愁。大腦會記住這種快樂無憂的感覺，下次一聞到熟悉的味道，就會忍不住想吃。最後，垃圾食品常和快樂時光連結在一起，例如生日時吃蛋糕、看電影配爆米花、邊逛街邊吃薯條，再加上有些垃圾食物的包裝和廣告令人垂涎欲滴，彷彿有個看不見的小精靈在誘惑我們：「來一口吧，吃了會開心喔！」 但糟糕的是，垃圾食物缺乏足夠的蛋白質和膳食纖維，雖然能帶來美味和快樂，但它們不但有超高的熱量，而且會快速升高你的血糖，這種不正常的血糖動盪來得急去得快，所以你很快就會覺得肚子餓，還想再多吃一點。還吃？你不胖才怪！許多人會把這些垃圾食物看成開心解憂的「戰友」，但它們真實身分其實是「損友」，長時間與其相伴，就可能導致營養失衡，影響發育和成長；久而久之，除了肥胖，蛀牙、高血壓、心臟病，甚至糖尿病也會不請自來！ 青少年的你正處於快速成長期，同時又面臨學業與人際等各種壓力，很容易選擇方便、好吃的垃圾食物作為「加油站」。雖然偶爾吃點無傷大雅，但千萬不要讓這些誘惑主導你的飲食習慣。別忘了，垃圾食物帶來的快樂是短暫的，但帶來的傷害卻會讓你付出長久的代價！"
    ],
