    "title": "數字記憶的奧秘",
    "genre": "說明文",
    "authors": "課文 ：曾世杰 學習單：陳虹君",
    "strategy_name": "用表格整理訊息-比較異同",
    "spotlight_raw_text": "閱讀聚光燈\n用表格整理訊息—比較異同\n    這篇說明文介紹了「說漢語」和「說英語」的大學生和幼兒在記憶數字上的不同表現，一整篇文章讀下來，訊息很多，容易讓讀者抓不到重點。底下透過「比較異同」的表格整理策略，幫助我們更清楚的看到文章中訊息的關連喔！       \n　　※比較異同：找出兩個或多個事物之間的「不同點」和「相同點」。\n\n◎",
    "story_text": "在一個安靜的房間裡有一張桌子，桌子兩端各有一人，面對面坐著。其中一人要實施一個測驗，底下稱他為「施測者」；另外一個人則是接受測驗的人，底下稱他為「受試者」。 施測者說：「底下我要每一秒鐘唸一個數字，請你注意聽，等我唸完了，請你依照順序照樣唸一遍。」然後他繼續說了：「5-9-1-7。」 受試者說：「5-9-1-7。」 施測者說：「我再加一個數字，2-7-5-8-6」。 受試者說：「2-7-5-8-6」。 這個好玩的測驗，叫做「數字記憶廣度測驗」，題目通常從3個數字開始，數字會愈來愈長，如果受試者成功通過9個數字，但在10個數字（如，3-2-0-3-0-7-4-9-2-6）時，回憶不出來了。他的記憶廣度得分就是9，表示他可依照順序正確回憶出9個數字。 實驗一 1987年，科學家找了兩組大學生做這個測驗，第一組大學生是說漢語的中國人（以下稱呼他們「老中」），第二組大學生是說英語的美國人（以下稱「老美」），結果指出，老中的平均得分是9，老美的平均卻只有7，老中很明顯的超過老美。 為什麼老中比較厲害呢？這個研究還測量了老中和老美的「數字發音長度」，兩組大學生用自己的母語以最快的速度從1數到10，他們數數的聲音被錄下來，科學家分析後發現，漢語的數字發音長度，比英語短了很多。科學家推論，漢語的數字發音比較短，所以大腦比較容易記憶，英語的數字發音比較長，比較不容易記，這就造成了老中和老美數字記憶廣度的差距。 實驗二 「漢語的數字發音長度比英語短，所以比較容易記」，實驗一這個結論看起來蠻有道理。但馬上就有其他的科學家提出異議：老中的家長喜歡送孩子去補習，從小就有心算、珠算、數學的大量練習，而老美的家長卻喜歡送孩子去踢球、游泳，說不定是從小的訓練，讓老中對數字更熟練，這造成了老中和老美數字記憶廣度的差異，而不是漢語和英語的數字發音長度不同所致。 1988年，另外的科學家重新複製了這個數字記憶廣度研究，但他們這次用的是4、5、6歲的「小老中」和「小老美」，年紀這麼小，不管是「小老中」或「小老美」都還沒有開始補習，所以如果兩組的數字記憶廣度仍然有所差異，就絶對不可能是「補習」造成的。研究結果發現，不管是4歲、5歲，還是6歲，每一個年齡層的「小老中」，數字記憶廣度平均值都明顯的大於「小老美」。而且，他們發現，用母語唸數字，小老中每個數字平均的發音長度，比小老美快了約十分之一秒。也就是說，這個研究再次支持了「數字發音愈短，能記住的數字愈多」的說法。 這兩個實驗講的都是「數字」，但如果是「閱讀」呢？每個人閱讀的速度都不一樣，是不是讀得越快，閱讀理解的能力就越強呢？我們下一課要來談這方面的研究。",
    "spotlight_answers": [],
