    "title": "運動傷害，怎麼辦？",
    "genre": "說明文",
    "authors": "課文 ：吳漢庭 學習單：巫怡蓉",
    "strategy_name": "寫作手法：倒反-從前後文推論隱藏意涵",
    "spotlight_raw_text": "閱讀聚光燈\n寫作手法—倒反\n    倒反法：倒反法又稱為說反話。說話或寫作時，故意用「意思相反」的語詞來強調重點，經常帶來趣味、諷刺的效果。寫成文字時，這些相反詞經常加了引號。請注意：倒反法若使用不當，容易引起人際衝突喔。\n 1.請圈出課文句子中，使用倒反法的語詞。\n課文句子\n實際意思\n(1)\n運動防護員詹老師說：「哈哈，少見少見，你右腿雙喜臨門，不但腳踝扭傷，小腿也抽筋了。\n雙喜臨門本意指的是兩件喜事一起降臨家門。但在此處是一次遇見兩次壞事，「扭傷和抽筋。」\n(2)\n你最後一跳，用盡全力，當下就抽筋了。只是當時剛好又因衝撞跌倒扭傷，這樣的好運，很少見啊。\n好運在此指的是壞運，一次遇上扭傷與抽筋。\n２.",
    "story_text": "「嘿，看球」、「衝！衝！衝！」、「卡位！卡位！」籃球場上充斥著此起彼落的喊叫聲。最後三十秒，皓祥瞥了一眼記分板，一分的差距，他回過頭眼神緊盯著對手，全神貫注想著如何突破缺口，此時防守者貼了上來，皓祥一個背後換手運球，騙過對手後切入上籃，這時對手190公分高的中鋒巨掌封來，皓祥失去平衡落地前，一個拉竿，把球勉力投出，就摔在地板上，「嗶～」哨音響起的同時，球進，比賽結束！場內場外歡聲爆起，滿身是汗的隊友們擁抱在一起歡喜跳躍。 此時只見皓祥眉頭緊皺，痛苦地叫道：「腳脖子扭了，小腿也好痛，沒辦法動了。」「詹老師！快來看，皓祥扭傷了！」畢竟皓祥是隊裡的主力戰將，運動防護員詹老師馬上趕過來評估，他發現皓祥的右小腿肌肉僵硬，說：「哈哈，少見少見，你右腿『雙喜臨門』，不但腳踝扭傷，小腿也抽筋了。」他幫助皓祥站起來，把腿伸直，再抓住他的腳掌往腳背輕輕彎曲。皓祥哀叫了幾聲，但隨著抽筋的小腿慢慢放鬆，他的痛苦逐漸減輕，大家終於鬆了一口氣。 「為什麼會抽筋啊？真是的。」皓祥問道。詹老師笑著說：「比賽時過度流汗，會讓身體的電解質失去平衡，再加上肌肉過度疲勞，就容易抽筋。你最後一跳，用盡全力，當下就抽筋了。只是當時剛好又因衝撞跌倒扭傷，這樣的『好運』，很少見啊。」幾位同學圍過來了，問道：「詹老師，像現在這種情形，我們可以怎麼處理？」 「不管是哪一種運動，做好暖身是最重要的，正確的暖身時間至少要佔整個運動時間的十分之一，主要目的是爲了增加關節的靈活性、提高心肺功能及體溫及促進肌肉收放的效能，這樣才能防止運動傷害，降低訓練時受傷的風險。如果還是不幸發生意外──像皓祥的扭傷，可以記這五個步驟。」詹老師邊幫皓祥包紮，一邊說著：「最基本的處置原則，口訣為PEACE：保護（Protection）、抬高（Elevation）、避免（Avoid）、壓迫（Compression）、教育（Education）。」 一、保護：受傷後1-3天內限制活動及負重。 二、抬高：受傷的部位盡量高於心臟，幫助患部的血液回流至心臟，減少腫脹。 三、避免：盡量避免使用抗發炎藥物。 四、壓迫：適當的彈性繃帶，針對受傷部位給予包紮壓迫，可發揮固定和抑制腫脹的效果。建議這個步驟交給專業的人員比較好。 五、教育：認識傷後恢復的流程，避免過度期待或壓力。 皓祥扶著額頭說：「喔，天啊，這麼多我要怎麼記？」詹老師笑道：「你們能盡量做到前三點就很不錯囉。」皓祥搭著揚安的肩說道：「兄弟，好好學啊，以後我受傷就要靠你了。」圍著的隊友們被皓祥滑稽的動作語言逗得哄堂大笑起來。",
    "spotlight_answers": [],
