    "title": "與小學說再見",
    "genre": "說明文",
    "authors": "課文/學習單：張筱晴",
    "strategy_name": "寫作手法：譬喻-從譬喻推論作者感受",
    "spotlight_raw_text": "閱讀聚光燈\n寫作手法─譬喻\n　　《譬喻：以大家熟悉的事物(A)去說明或凸顯另一件事物(B)的特質 》\n譬喻是一種寫作常見的手法，它和「轉化」與「誇飾」一樣，都是運用聯想、想像力的方式，來連結讀者普遍的經驗，以引起讀者共鳴，讓讀者感同身受。\n例１：「他的笑容像太陽。」→以大家熟悉的「太陽」去凸顯他的笑容帶給人溫暖、耀眼的感受。\n例2：「他的笑容像盛放的花。」→以大家熟悉的「盛放的花」去凸顯他的笑容帶給人美好、燦爛的感受。\n    使用譬喻的手法時，句子常會有「好像」、「像」、「彷彿」、「如（同）」、「一樣」、「A（像）是B」等關鍵字詞，而文章使用譬喻之處，也是作者投入想像和著重感情之處，因此閱讀時我們可以留意譬喻的句子，推論作者主要想傳達的心情或意涵。\n◎",
    "story_text": "最近，有個畫面時常浮現於腦海：禮堂迴盪著大家的歌聲，同學們有的頻頻拭淚，有的泣不成聲，有的放聲歌唱，傾訴濃濃的不捨──那是我小學的畢業典禮。那時的我，默默站在人群中困惑著：明明大部分的人都會在同一個國中碰面，明明可以再回來看老師，為什麼大家那麼難過？而現在的我才知道，那眼淚，或許更是在向即將逝去的童年說再見。 剛上國中，離開待了六年的環境，一方面雀躍的迎接新生活、新朋友，一方面也享受成為小大人的喜悅。對小學的想念只像是遠方的雲，偶爾飄過心頭。而國中課程表上多樣多元的科目、課堂間穿梭改換的老師、教室裡責任繁重的幹部與小老師工作，讓每天都是嶄新的冒險，令人期待將要發生什麼新鮮事。那時的我像顆陀螺，不僅忙得暈頭轉向，在短暫下課中橫衝直撞，也在同學中不斷打轉，想尋找志同道合的伴。 慢慢的，我發現我和每個同學都能相談甚歡，但我不會是他們最要好的朋友，這份格格不入，讓我在走廊遇到小學朋友時總是特別開心，但迎面而來的卻經常是一份陌生的尷尬。又隨著第一次段考逼近，我才驚覺小學的讀書策略不再管用，面對小考卷上密密麻麻的紅字訂正，及格不再唾手可得，反而像斷線的風箏般，遠走高飛。升上國中的新鮮感慢慢退去，孤單和壓力卻如影隨形，無法擺脫也無處可逃。 每當望向操場，我看見的是小學下課大家玩鬼抓人的快樂模樣，而看著新同學、老師，想的卻是他們好像我以前小學認識的誰。那些回憶彷彿一張張散落的照片，在我想念時自動跳到眼前，尤其是畢業典禮的那一幕。而思念是烏雲，日積月累，不斷膨脹，遮住了我的笑容，多希望有時光機帶我回到過去。直到那天，我在走廊上撞見我最好的小學朋友和新同學，看見他們有說有笑時，我才恍然大悟：原來只有我還停留在過去，只有我還緊抓著小學的回憶不放。頓時心中那烏雲密布的天空下了場大雨，雖然失落，但我想是時候該向小學、向那無憂無慮的時光告別，是時候該專注於新的生活，讓陽光照進日子裡。 以前讀懷舊主題的文章，常常感到枯燥乏味，作者所描述的情景我不曾經歷，也沒有興趣。然而，這次親身經歷了這翻天覆地的變化我突然明白了作者的心情，儘管情境大不相同，但那一份捨不得，一份放不下，引起了深深共鳴。所有的字字句句，無非是希望那像珍珠般飽滿耀眼的回憶，能禁得起時間的沖刷，能多留下一些美好。而成長，或許就是在每次失去時練習好好告別，在每次告別時更懂得珍惜眼前、把握當下，在每次韶光流逝後，都能少一些遺憾與眷戀吧。",
    "spotlight_answers": [],
    "paragraphs": [
      "最近，有個畫面時常浮現於腦海：禮堂迴盪著大家的歌聲，同學們有的頻頻拭淚，有的泣不成聲，有的放聲歌唱，傾訴濃濃的不捨──那是我小學的畢業典禮。那時的我，默默站在人群中困惑著：明明大部分的人都會在同一個國中碰面，明明可以再回來看老師，為什麼大家那麼難過？而現在的我才知道，那眼淚，或許更是在向即將逝去的童年說再見。 剛上國中，離開待了六年的環境，一方面雀躍的迎接新生活、新朋友，一方面也享受成為小大人的喜悅。對小學的想念只像是遠方的雲，偶爾飄過心頭。而國中課程表上多樣多元的科目、課堂間穿梭改換的老師、教室裡責任繁重的幹部與小老師工作，讓每天都是嶄新的冒險，令人期待將要發生什麼新鮮事。那時的我像顆陀螺，不僅忙得暈頭轉向，在短暫下課中橫衝直撞，也在同學中不斷打轉，想尋找志同道合的伴。 慢慢的，我發現我和每個同學都能相談甚歡，但我不會是他們最要好的朋友，這份格格不入，讓我在走廊遇到小學朋友時總是特別開心，但迎面而來的卻經常是一份陌生的尷尬。又隨著第一次段考逼近，我才驚覺小學的讀書策略不再管用，面對小考卷上密密麻麻的紅字訂正，及格不再唾手可得，反而像斷線的風箏般，遠走高飛。升上國中的新鮮感慢慢退去，孤單和壓力卻如影隨形，無法擺脫也無處可逃。 每當望向操場，我看見的是小學下課大家玩鬼抓人的快樂模樣，而看著新同學、老師，想的卻是他們好像我以前小學認識的誰。那些回憶彷彿一張張散落的照片，在我想念時自動跳到眼前，尤其是畢業典禮的那一幕。而思念是烏雲，日積月累，不斷膨脹，遮住了我的笑容，多希望有時光機帶我回到過去。直到那天，我在走廊上撞見我最好的小學朋友和新同學，看見他們有說有笑時，我才恍然大悟：原來只有我還停留在過去，只有我還緊抓著小學的回憶不放。頓時心中那烏雲密布的天空下了場大雨，雖然失落，但我想是時候該向小學、向那無憂無慮的時光告別，是時候該專注於新的生活，讓陽光照進日子裡。 以前讀懷舊主題的文章，常常感到枯燥乏味，作者所描述的情景我不曾經歷，也沒有興趣。然而，這次親身經歷了這翻天覆地的變化我突然明白了作者的心情，儘管情境大不相同，但那一份捨不得，一份放不下，引起了深深共鳴。所有的字字句句，無非是希望那像珍珠般飽滿耀眼的回憶，能禁得起時間的沖刷，能多留下一些美好。而成長，或許就是在每次失去時練習好好告別，在每次告別時更懂得珍惜眼前、把握當下，在每次韶光流逝後，都能少一些遺憾與眷戀吧。"
    ],
