    "title": "兩千五百歲的酷老師",
    "genre": "說明文",
    "authors": "課文 ：黃金萍學習單：張明珠",
    "strategy_name": "推論策略-從標題及首尾段推論主旨",
    "spotlight_raw_text": "閱讀聚光燈\n推論主旨\n主旨：作者在寫文章時，想要告訴別人的主要想法或道理。\n推論文章主旨的方法：\n10033097790\n方法100\n方法1從標題及首末段找主旨（方法2在下一課-第5課）\n有時，作者會在標題裡暗示文章的主旨。我們可以先從題目思考作者可能想要傳遞什麼樣的訊息，再從文章第一段跟最後一段找主旨線索。步驟有二：\n1.先猜測標題想要傳達的重點；2.從第一段和最後一段找主旨線索。\n先猜測標題想要傳達的重點。\n課文題目\n\n可能代表意義\n2500歲\n9080521590000●          ●\n職業\n酷\n●          ●\n這個人年紀很大，或流傳已久。\n老師\n●          ●\n很棒的、很特別的\n猜測：這篇可能是在講 　　　一位流傳已久的老師        的故事\n２.從首尾段找主題句：主旨可能在文章中的第一段或最後一段。  \n449580810260\n　　我愛鳥。\n　　從前我常見提籠架鳥的人，清早在街上蹓躂（現在這樣有閒的人少了）。我感覺興味的不是那人的悠閒，卻是那鳥的苦悶。00\n　　我愛鳥。\n　　從前我常見提籠架鳥的人，清早在街上蹓躂（現在這樣有閒的人少了）。我感覺興味的不是那人的悠閒，卻是那鳥的苦悶。主題句在第一段：有些作者會使用「開門見山法」，直接一開始講出文章重點，讀第一段能輕易找出主旨。（範文擷取自梁實秋－我愛鳥）\n\n→從首段推論主旨：這是一篇寫有關作者　　愛鳥　　　的文章。\n\n主題句在最後一段：有些作者會把重要的觀念放在最後一段，再次強調或總結重點，讓人印象深刻。（範文擷取自馮驥才－珍珠鳥）304800655320\n　　有一天，我伏案寫作時，小珍珠鳥居然落到我的肩上。我手中的筆不覺停了，生怕驚跑它。待一會兒，扭頭看，這小傢伙竟扒在我的肩頭睡著了，銀灰色的眼瞼蓋住了眸子，小紅腳剛好給胸脯上長長的絨毛蓋住。我輕輕一抬肩，它沒醒，睡得好熟！還咂咂嘴，難道在做夢？\n我筆尖一動，流瀉下一時的感受：信賴，往往創造出美好的境界。00\n　　有一天，我伏案寫作時，小珍珠鳥居然落到我的肩上。我手中的筆不覺停了，生怕驚跑它。待一會兒，扭頭看，這小傢伙竟扒在我的肩頭睡著了，銀灰色的眼瞼蓋住了眸子，小紅腳剛好給胸脯上長長的絨毛蓋住。我輕輕一抬肩，它沒醒，睡得好熟！還咂咂嘴，難道在做夢？\n我筆尖一動，流瀉下一時的感受：信賴，往往創造出美好的境界。\n→從末段推論主旨：這是一篇寫有關作者想傳遞人與鳥互相　信賴　的文章。\n3.",
    "story_text": "這位酷老師，如果還活著，年紀和阿里山神木一樣老。他愛唱歌、吟詩，喜歡射箭，還是駕車的好手。他當時教過的學生約有三千人，後人尊稱他為「至聖先師」，他就是孔子。 孔子三十歲時，就已經成為學問淵博的人，並且開始招收學生。他提倡「有教無類」，只要喜歡讀書，不分老小、貧富、貴賤或家世，肯用功向學，都可以當他的學生。富可敵國的子貢、家境貧寒的顏回、好勇直率的子路，以及個性謙和的冉有，都是孔子的得意學生。在那個時候，只有貴族才能上學，但是孔子卻開辦了一所平民學校，將教育普及到一般平民百姓，他真是一位名符其實的酷老師。 酷老師的教學很有一套，總能針對每個人的特質，採取「因材施教」的方法。一個夏天的午後，子路問孔子：「老師，聽到該做的事，不要遲疑，立刻去做，對不對？」 「你要先問問長輩的意見才行，不要馬上去做。」子路聽完孔子的回答，滿意的離開。 這時，冉有也來請教同樣的問題，孔子的回答卻是：「你既然有了好主張，就不要遲疑，應該立刻去做！」 在孔子身旁的學生公西華越聽越糊塗，忍不住發問：「老師，他們問同樣的問題，您的答案為什麼不一樣？」 孔子笑著說：「你問得好啊！子路平時就衝動急躁，我希望他能謹慎思考再去做；至於冉有平時猶豫不決，我希望他能更果斷，免得錯失機會。」孔子了解每個學生的個性，給學生建議，就像醫生對症下藥一樣，真是酷哇！ 酷老師對教育充滿熱忱，不喜歡學生偷懶或不用功，要是被他發現，也會毫不客氣的責備。 宰予熟讀經書，說起話來應對如流，孔子很喜歡他。有一回，宰予沒有來上學，孔子擔心他生病，特地前去探望；沒想到，他竟然躺在床上呼呼大睡，好端端的，根本沒有病。孔子眼睛瞪得像銅鈴一般大，盯著鼾聲如雷的宰予，一句話也沒說。 「宰予……」孔子身旁的學生試著叫醒宰予。 「只是睡個午覺嘛！」宰予翻過身，繼續睡。 「宰予……」 「睡個午覺嘛，吵什麼吵！」 「宰予！」孔子大聲喝󠇡斥。 宰予一聽，嚇得跌下床。 「老——老——」 「老——老什麼老？」 孔子氣得火冒三丈，掉頭就走。 「唉！朽木不可雕也！」學生們跟在老師後頭，抿嘴偷笑。) 後來，孔子感慨的對學生們說：「以前我看人，只要聽了這個人的話，就會相信所做的事是真的。但是自從宰予這件事後，讓我學到還要從旁觀察這個人言行是否一致。」 孔子用了將近一輩子的時間當老師，他是非分明，學生表現好，他不吝讚美，學生犯了錯，他嚴加責備。他上課最常使用的方式就是「問與答」，他喜歡學生提出問題，喜歡和學生們對談，甚至學生們和他辯論，一點也不生氣。 學生們把和孔子在生活中的對話，加上平常的作為記錄下來，集結成《論語》，表達了對老師的懷念與敬愛；讓兩千五百年後的我們，也能透過閱讀，了解孔子是個博學有智慧，為理想奉獻一生的酷老師。",
    "spotlight_answers": [],
