    "strategy_name": "摘要策略-從結構找小主題與細節",
    "spotlight_raw_text": "閱讀聚光燈\n摘要策略—主題描述結構\n　　本課是一個說明文，主要是介紹和動物求偶有關的知識。這個文章有清楚的結構，在「動物求偶」的大主題下，介紹幾個小主題，每一個小主題都補充了許多說明的細節，這是說明文很常見的呈現方式。\n　　要讀這類的文章，讀者如果能掌握大主題和小主題之間的關係，非常有助於理解和記憶。\n　　大主題通常是文章名稱，小主題常常可在段落前的小標題找到，而標題下方的段落內容，會是小主題的舉例或重要細節。底下的練習，我們來學習如何找出小主題下方的舉例與重要細節。\n212801325929\n舉例一—細節\n舉例二—細節\n舉例一—細節\n舉例二—細節0\n舉例一—細節\n舉例二—細節\n舉例一—細節\n舉例二—細節本課結構圖\n如何找出「小主題」以及小主題下方的「舉例與重要細節」呢？\n以第二段為例\n1.找出小主題：本課小主題可以直接從段落前的小標題找到。通常小主題會出現在標題或首句。小標題是該段的核心概念，有助於找到段落內的舉例及重要細節。\n第一個小標題是：用歌聲求偶。\n\n2.找出小主題（用歌聲求偶）下方的舉例與重要細節\n3483431542100    潮濕溫暖的夏夜，嘓嘓嘓、嘓嘓嘓，雄蛙奮力的在池塘裡展現歌喉，只為求得雌蛙的青睞，以完成繁衍的天職。雄蛙求偶的鳴叫聲響遍池畔，也引來競爭對手的爭強鬥勝。是否能順利成為心儀對象的「青蛙子」？雄蛙們可要各憑本事才行。\n(1)找出舉例：可以發現整段都在描寫的動物是青蛙，跟動物有關的詞彙有雄蛙、雌蛙和青蛙，這時要選擇哪個最貼近「用歌聲求偶」的小主題呢？是誰用歌聲在求偶呢？【雄蛙  ☐雌蛙】（單選） \n(2)整理細節內容：再來整理與「歌聲求偶」有關的訊息\n嘓嘓嘓、展現歌喉、鳴叫聲發出嘓嘓嘓的鳴叫聲，展現歌喉。\n(3)條列整理訊息：最後把舉例與細節整理如下\n雄蛙  — 發出嘓嘓嘓的鳴叫聲，展現歌喉。\n\n41148036639500換你試試看：第三段\n    春天來臨，住在枯木洞裡的五色鳥，開始粉墨登場，準備在演唱會一展歌喉。牠身穿綠衣裳，頭戴彩色帽，站在茂密枝葉搭起的舞台上，揭開演唱會的序幕。五色鳥發出喀、喀、喀喀喀喀……的求偶叫聲，盡情的歌唱。牠獨特的聲音，吸引愛慕者，為延續下一代而準備。\n1.先找小主題\n  本段的小標題也是： 用歌聲求偶。   \n2.找出舉例和細節\n(1)找出舉例：整段都在描寫的動物是【  五色鳥  】\n(2)整理細節內容：發出【  喀喀喀  】的求偶叫聲\n(3)條列整理訊息\n五色鳥  —      發出喀喀喀的求偶叫聲。             \n3.整理小主題內兩段訊息\n76506347102\n用歌聲求偶0\n用歌聲求偶172489190112 雄  蛙  — 發出嘓嘓嘓的鳴叫聲，展現歌喉。\n838200153307\n小主題0\n小主題1970314283936\n舉例0\n舉例3450771283937\n重點細節0\n重點細節 五色鳥  —  發出喀喀喀的求偶叫聲。          \n挑戰題，請找出第六段的「小主題」及小主題下方的「舉例與重要細節」\n1.先找出小主題：本課小主題可以直接從段落前的小標題找到，小標題是該段的核心概念，有助於找到段落內的舉例及重要細節。\n小標題是：【 以氣味傳達真情意 】\n1295400292100002.找出小主題下方的舉例與重要細節\n    花園裡，田野間，同樣的翩翩飛舞，飛蛾卻沒有蝴蝶那樣的漂亮迷人；牠們生命雖然短暫，總能圓滿完成繁殖後代的重責大任。雌蛾能分泌一種特別的氣味，利用空氣擴散傳布，讓在遠方的雄蛾，感受到她真摯的情意，願意千里迢迢的飛奔前來相會，完成終身大事。\n(1)找出舉例：整段都在描寫的動物是【  雌蛾  】。\n（若動物有多種詞彙，可思考是誰「用歌氣味求偶」呢？）\n(2)整理細節內容：【  分泌特別的氣味，吸引雄蛾       】\n(3)條列整理訊息：\n雌蛾   —     分泌特別的氣味，吸引雄蛾           \n(4)加上小主題，將訊息寫清楚\n  用氣味求偶   —  雌蛾  —    分泌特別的氣味，吸引雄蛾       \n419091052342\n重點細節0\n重點細節260168689807\n舉例0\n舉例1153886100693\n小主題0\n小主題 \n \n \n如果不小心卡關了，可以回到前一頁，仔細閱讀步驟說明，然後再試試看，加油！\n\n  \n\n50242542610\n請根據文章內容，選出最適合的答案，要讀完每一個選項再作答。00\n請根據文章內容，選出最適合的答案，要讀完每一個選項再作答。27305337\n六",
    "story_text": "每一種動物，都需要繁衍後代。但是在大自然遼闊的空間裡，動物有哪些方式可以傳遞出「我在這裡！」「我準備好了！」的訊息，讓愛的伴侶可以「月上柳梢頭，人約黃昏後」呢？ 用歌聲求偶 潮濕溫暖的夏夜，嘓嘓嘓、嘓嘓嘓，雄蛙奮力的在池塘裡展現歌喉，只為求得雌蛙的青睞，以完成繁衍的天職。雄蛙求偶的鳴叫聲響遍池畔，也引來競爭對手的爭強鬥勝。是否能順利成為心儀對象的「青蛙王子」？雄蛙們可要各憑本事才行。 春天來臨，住在枯木洞裡的五色鳥，開始粉墨登場，準備在演唱會一展歌喉。牠身穿綠衣裳，頭戴彩色帽，站在茂密枝葉搭起的舞台上，揭開演唱會的序幕。五色鳥發出喀、喀、喀喀喀喀……的求偶叫聲，盡情的歌唱。牠獨特的聲音，吸引愛慕者，為延續下一代而準備。 用舞姿吸引仰慕者 頭形像馬，長相特殊的海馬是海底世界的嬌客，到了繁殖期，雄海馬以忽明忽暗的體色和已經轉淡的孵卵囊，舞出曼妙的姿勢吸引仰慕者；等到互許終身時，雙雙以腹部相對，上下漂浮、嬉戲於水中；翻滾的海水是結婚進行曲，一對佳偶在浪漫的旋律下，跳著雙人舞進入洞房。 每年的三至九月，鴕鳥有熱鬧非凡、令人耳目一新的招親活動。平常沉默的雄鳥，卻在活動期間大展身手，一方面發出低沉的叫聲，呼喚著雌鳥；一方面將翅膀尖端的白色羽毛，有節奏的開展和收合，圍繞在雌鳥身旁，瘋狂跳起獨特的求偶舞。 以氣味傳達真情意 花園裡，田野間，同樣的翩翩飛舞，飛蛾卻沒有蝴蝶那樣的漂亮迷人；牠們生命雖然短暫，總能圓滿完成繁殖後代的重責大任。雌蛾能分泌一種特別的氣味，利用空氣擴散傳布，讓在遠方的雄蛾，感受到她真摯的情意，願意千里迢迢的飛奔前來相會，完成終身大事。 以武力展示的方式求偶 為了避免敵人的攻擊，也為了防止陽光的烤曬，招潮蟹選擇在地洞裡設置結婚新房。在求偶季節，雄蟹頂著兩根像火柴頭的眼睛，四處尋找母蟹的芳蹤。當你看見牠快速的揮動大螯，雄赳赳，氣昂昂的橫著走路，表示已經覓得如意佳人，正發出求婚訊息，似乎也向心上人宣示：我的螯是保衛家園的最佳利器，我有能力保護妳及我們的下一代，請妳放心的嫁給我吧！ 春暖花開的季節，大部分的蛇結束冬眠，出洞尋覓佳人。母蛇釋放出特殊的氣味，代表牠已成熟，能生兒育女了；眾多公蛇沿著氣味尾隨而至展開追求。母蛇身負香火的傳承，公蛇們得經歷多次的搏鬥，才能脫穎而出，成為幸運的新郎。公蛇的競爭，熱鬧了山林野地；母蛇的香火，則豐富了生命傳承。 動物透過多采多姿的求偶方式，延續物種，達成傳宗接代的目的。除了傳承生命，牠們的求偶方式帶來了美妙的音樂、舞蹈，也豐富了大自然的萬千丰采。",
