    "title": "末日種子庫",
    "genre": "說明文",
    "authors": "課文 ：林玫伶 學習單：陳允捷",
    "strategy_name": "摘要策略-從關鍵句找小主題與細節",
    "spotlight_raw_text": "閱讀聚光燈\n摘要策略—主題描述結構\n    本課是一個說明文，主要是介紹和末日種子庫有關的知識。這個文章有清楚的結構，在「末日種子庫」的大主題下，介紹幾個小主題，每一個小主題都補充了許多說明的細節，這是說明文很常見的呈現方式。如果掌握大主題和小主題之間的關係，就有助於理解和記憶。\n    之前我們曾經在「G5-L12六塊肌六塊雞」學過說明文章結構、「L8動物談情說愛的方式」學習舉例、整理細節內容及條列整理訊息、「L9祝你好眠」學習如何用關鍵句子找小主題。\n    現在我們用本課的文章練習：\n1.找出大主題（可從標題找，只要找一次即可）：   末日種子庫   \n2.找出小主題：\n2679703175000第三段：\n由於全球氣候變遷越來越劇烈，對生物多樣性造成威脅，不僅影響動物的生存，連植物也難以倖免。萬一發生大區域性或全球性的災害時，某些農作物可能從此滅絕，興建種子庫的目的，就是在預防這樣的末日景象，以保護農業作物的多樣性，因此它也被稱為「末日種子庫」\n將關鍵句畫起來，本段的小主題是　興建種子庫的目的  。\n3.找出小主題下方的重要細節\n萬一大規模災害發生時，預防某些種子的基因因此而消失，以保護農業多樣性。\n \n\n◎",
    "story_text": "銀行是存錢的地方，你可知道，現在還有一種銀行，專門儲存來自世界各地的種子喔！ 這個種子銀行的正式名稱叫做斯瓦爾巴全球種子庫，是挪威政府出資興建的非營利儲藏庫，2008年完工開放以來，裡面已儲存了數以萬計的種子包，用來保存全世界的農作物種子。 由於全球氣候變遷越來越劇烈，對生物多樣性造成威脅，不僅影響動物的生存，連植物也難以倖免。萬一發生大區域性或全球性的災害時，某些農作物可能從此滅絕，興建種子庫的目的，就是在預防這樣的末日景象，以保護農業作物的多樣性，因此它也被稱為「末日種子庫」。 低溫乾燥的環境有利於保存種子，這座種子庫因而建造在斯瓦爾巴群島永久凍土區的山脈內部。這裡是挪威最北邊的國土，位於北極地區，冰天雪地，氣候極為寒冷，像一座大型的自然冷凍庫。種子庫的溫度維持在攝氏零下18度，這溫度可降低種子的代謝活動，並維持發芽的活性，是最適合保存種子的溫度。即使停電或製冷機故障，永凍土也能讓內部溫度保持在零下8度左右。這個世界最大的種子銀行，最多可存放450萬種作物的種子，珍貴的種子經過真空包裝，並用三層鋁箔密封，才能上架。 這裡的戒備十分森嚴，如果你有機會進入內部，會先經過大約120公尺的隧道，並通過5扇有密碼裝置的門，才可進入地下的種子儲存庫。整棟建築位在海拔130公尺高的地方，外牆的混凝土厚達1公尺，可承受芮氏規模6.2的地震和核子武器攻擊，即使冰川 融化、海平面上升，也不會威脅種子的安全。 臺灣在2009年首度參與這項保存計畫，為了維繫臺灣原生小米的基因多樣性，2024年臺灣科學團隊特地前往北極，由三位排灣族原住民代表，將象徵繁榮和幸福的小米種子，存放在斯瓦爾巴全球種子庫。小米類穀物可以在惡劣的氣候條件下生存，抗旱又耐病蟲害，被視為極端氣候下解決糧食危機的重要作物。 斯瓦爾巴全球種子庫設置的概念就像銀行，各國存放在裡面的種子，所有權仍是儲存國的，當有需要的時候可以領出來，讓種子從冷凍中甦醒，便可以再播種。2015年，敘利亞發生內戰，烽火漫天，第一大城阿勒坡受到嚴重破壞，城裡的種子庫也被殃及池魚。中東的研究人員於是向斯瓦爾巴全球種子庫提取存放其中的130箱種子，這也是末日種子庫成立以來首次被提取的案例。 科學家未雨綢繆󠇡，運用科技為人類的生存而努力，我們每個人更要保護生態環境，祈禱永遠沒有人需要使用斯瓦爾巴種子庫的種子！",
    "spotlight_answers": [],
