    "fixture_found": false,
    "title": "古代畫家心中的仙境",
    "genre": "說明文",
    "authors": "課文 ：陳韻如 學習單：巫怡蓉",
    "strategy_name": "摘要策略-從關鍵句找小主題與細節",
    "spotlight_raw_text": "閱讀聚光燈\n摘要策略──主題描述結構00\n五",
    "story_text": "從變出玻璃鞋給灰姑娘的神仙教母，到大蚌裡誕生的愛神維納斯，一直到臺灣的雷公、電母、城隍爺，全世界各種不同文化的人們都有一個共同的想像──這世界是有神仙的。中國人也不例外。 在古代中國人的想像裡，神仙不食人間煙火，總是住在遠離凡塵俗世、雲霧飄渺的深山裡。在許多口耳相傳的故事裡，曾有極少數幸運的人「誤入」仙境，看見不可思議的景象。這些傳說中的仙境，通常都藏在深山的洞穴裡。 中國 江蘇的宜興市有個著名的「張公洞」，根據古書記載，此洞穴三面都是高聳的懸崖，只有北面有一個入口，洞內深不見底，潺潺流水穿過其中，岩壁上的鐘乳石宛如精雕細琢的藝術品。千百年來，許多畫家都將其描繪成通往仙境的入口之一，周圍獨特的地景與岩石，更增添了幾分神祕色彩。 從宋朝到明 清時期這五百年間（約西元1100年至1600年），許多畫家都以張公洞為創作題材。仔細觀察這些畫作，會發現它們不只是單純的風景畫，更像是古代版的旅遊指南，生動的展現了當時人們心目中仙境的模樣。畫家們常在畫中安排三種特別的元素：山洞、小橋和小船。山洞意味著通往仙境的神祕門戶，小橋代表跨進另一個世界的通道，小船象徵渡過現實與仙境的交通工具。這些元素彷彿是進入另一個世界的「護照」，標誌著從凡塵俗世到神奇仙境的奇妙轉變。 這些古代畫作有個引人深思的特點──「畫中的人物都非常渺小，周圍的山水風景卻極其宏大」，這與現代人喜歡在自拍照中凸顯出自己的習慣，形成鮮明的對比。古代畫家如此安排有其深意，主要在表達面對浩瀚無垠的大自然時，人類是微不足道的。畫中的小人物彷彿是畫家在向觀畫者細語：「看啊！這個世界是如此遼闊壯美，人，不過是滄海一粟罷了。」 在更早的唐宋時期（西元618年至1279年），仙境畫主要出自皇宮中的專業畫師。到了元明時期（西元1271年至1644年），一個有趣的變化發生了，這類畫作開始在民間普及，越來越多庶民畫家投入創作。這些畫家在簽名時，還喜歡加上「山人」、「道人」等稱號，雖然他們不一定真的隱居山林、苦修尋道，但這些稱號反映出他們遠離塵囂的渴求、對大自然的嚮往，以及對心靈提升的期待。 古代畫家留下這些珍貴的藝術遺產，不但讓我們得以窺見古人的心靈世界，也讓我們在反身檢討後發現，現代人似乎和古人仍有著共同的嚮往。 二十一世紀的我們，好像不再相信山裡的神仙了，但在凝視著博物館櫥窗裡泛黃的仙境水墨畫時，倍受挫折、疲憊不堪的你，不也常常想要遠離塵囂，一葉扁舟，走過小橋，投身如畫的碧綠山林？原來，好的藝術能穿越時空，撥動幾個世紀以後觀畫者心中的那條琴弦，讓它嗡嗡然起了共鳴。誰說世界沒有神仙呢。",
    "spotlight_answers": [],
    "paragraphs": [
      "從變出玻璃鞋給灰姑娘的神仙教母，到大蚌裡誕生的愛神維納斯，一直到臺灣的雷公、電母、城隍爺，全世界各種不同文化的人們都有一個共同的想像──這世界是有神仙的。中國人也不例外。 在古代中國人的想像裡，神仙不食人間煙火，總是住在遠離凡塵俗世、雲霧飄渺的深山裡。在許多口耳相傳的故事裡，曾有極少數幸運的人「誤入」仙境，看見不可思議的景象。這些傳說中的仙境，通常都藏在深山的洞穴裡。 中國 江蘇的宜興市有個著名的「張公洞」，根據古書記載，此洞穴三面都是高聳的懸崖，只有北面有一個入口，洞內深不見底，潺潺流水穿過其中，岩壁上的鐘乳石宛如精雕細琢的藝術品。千百年來，許多畫家都將其描繪成通往仙境的入口之一，周圍獨特的地景與岩石，更增添了幾分神祕色彩。 從宋朝到明 清時期這五百年間（約西元1100年至1600年），許多畫家都以張公洞為創作題材。仔細觀察這些畫作，會發現它們不只是單純的風景畫，更像是古代版的旅遊指南，生動的展現了當時人們心目中仙境的模樣。畫家們常在畫中安排三種特別的元素：山洞、小橋和小船。山洞意味著通往仙境的神祕門戶，小橋代表跨進另一個世界的通道，小船象徵渡過現實與仙境的交通工具。這些元素彷彿是進入另一個世界的「護照」，標誌著從凡塵俗世到神奇仙境的奇妙轉變。 這些古代畫作有個引人深思的特點──「畫中的人物都非常渺小，周圍的山水風景卻極其宏大」，這與現代人喜歡在自拍照中凸顯出自己的習慣，形成鮮明的對比。古代畫家如此安排有其深意，主要在表達面對浩瀚無垠的大自然時，人類是微不足道的。畫中的小人物彷彿是畫家在向觀畫者細語：「看啊！這個世界是如此遼闊壯美，人，不過是滄海一粟罷了。」 在更早的唐宋時期（西元618年至1279年），仙境畫主要出自皇宮中的專業畫師。到了元明時期（西元1271年至1644年），一個有趣的變化發生了，這類畫作開始在民間普及，越來越多庶民畫家投入創作。這些畫家在簽名時，還喜歡加上「山人」、「道人」等稱號，雖然他們不一定真的隱居山林、苦修尋道，但這些稱號反映出他們遠離塵囂的渴求、對大自然的嚮往，以及對心靈提升的期待。 古代畫家留下這些珍貴的藝術遺產，不但讓我們得以窺見古人的心靈世界，也讓我們在反身檢討後發現，現代人似乎和古人仍有著共同的嚮往。 二十一世紀的我們，好像不再相信山裡的神仙了，但在凝視著博物館櫥窗裡泛黃的仙境水墨畫時，倍受挫折、疲憊不堪的你，不也常常想要遠離塵囂，一葉扁舟，走過小橋，投身如畫的碧綠山林？原來，好的藝術能穿越時空，撥動幾個世紀以後觀畫者心中的那條琴弦，讓它嗡嗡然起了共鳴。誰說世界沒有神仙呢。"
    ],
