    "title": "小藍鯨之死",
    "genre": "說明文",
    "authors": "課文 ：林玫伶 學習單：陳允捷",
    "strategy_name": "自我提問-4F思考法自我提問",
    "spotlight_raw_text": "閱讀聚光燈\n自我提問\n\n    看完一篇文章，相信你的心中一定會有一些想法，我們可以將這些想法有組織地整理出來，藉由簡單的自我提問，運用句型，寫出答案，也會幫助你更有邏輯的思考，深入理解文章內容喔。\n※注意：每個人的想法、感受、行動不一定會相同，沒有對錯之分。\n\n事實\n感受\n反思\n行動\n問自己?\n這篇文章／事件什麼地方令我印象深刻？\n對於這個事情，我感受到了什麼情緒？\n我們做了什麼事，才會導致這件事的發生？\n我們未來應該怎麼做？才能避免這種情況發生？\n答案\n（句型）\n我看到了．．．\n這個事件，我到．．．\n（情緒）\n因為．．．，\n才會．．．。\n未來我們可以．．．\n本文\n例子\n我看到了人類為了方便，亂丟漁網到海裡，造成小藍鯨的死亡事件。\n對於小藍鯨的死亡，我感到很震驚又難過。\n因為人類貪圖方便，亂丟垃圾，才會汙染海洋。\n未來我們可以宣導環境保護，不亂丟垃圾，多參與淨灘活動。\n其他例子：\n學習不佳\n我看到這次的數學成績不好。\n我覺得很難過，而且很丟臉。\n因為考試前，我沒有複習功課，還打電動，平時上課也不認真，才會導致我數學不及格。\n未來我可以改掉不好的學習行為，上課認真，不會的再去問師長，電動利用空閒時間再玩。\n\n◎",
    "story_text": "2020年1月25日，正逢農曆大年初一，臺東長濱鄉的民眾發現一頭長達24公尺、寬2.5公尺的巨大鯨魚在海灘擱淺死亡，經科學家們鑑定，證實是頭藍鯨。 藍鯨是世界上體型最大的動物，19世紀初以前曾經維持穩定的族群數量，但在商業利益追逐下，捕鯨者使用大型鯨砲獵殺藍鯨，不到一個世紀便使牠們幾乎滅絕，目前世界自然保育聯盟（IUCN）已將藍鯨列為瀕危物種。臺灣在日治時期曾捕獲過藍鯨，但尚未有海上目擊紀錄，這次難得的藍鯨再現，卻不幸的是擱淺死亡案例，讓國內鯨豚界又震驚又難過。 研究團隊檢驗發現，這隻死亡的藍鯨全身仍有許多軟骨存在，研判是隻不到2歲、還在生長期的幼年藍鯨。牠身形削瘦，專家根據遺體狀況及骨骼判斷，小藍鯨生前被海廢漁具繩索纏繞住頭部，時間可能長達5至6個月，因為小藍鯨時候生長速度快，頭骨兩側被繩索束縛，竟勒出超過10公分深、5公分寬的溝痕，嘴巴也因被勒住無法張嘴進食；解剖發現，小藍鯨近乎空腹，食道和胃裡只有一隻半消化的魚眼睛，體內脂肪幾乎燃燒殆盡，可說牠最終是被活活餓死的，讓人心疼不已，許多人感嘆這是小藍鯨「悲傷的故事」。 為了保留珍稀的藍鯨標本，海洋保育署、成功大學與海洋生物博物館共同合作，隨即進行藍鯨的骨骼重建與研究典藏。目前全球完整的藍鯨骨骼標本僅約 25 件，加上藍鯨骨骼結構複雜，修復不易，更顯得這次的標本製作任務重大。歷經近四年的骨骼修復，屏東海生館終於在2023年底，以「巨鯨之路」為名，完整展示其標本，開放國人參觀。展廳以深藍色的光影投射，巨大的骨骼標本高懸於屋頂，模擬小藍鯨優雅下潛海洋的姿態，想要展現藍鯨生活於海洋應有的動態美感與生命力。 展廳也同步展示造成小藍鯨死亡的「兇器」，也就是當時纏繞在藍鯨嘴上的尼龍繩，藉此提醒大家，漁具纏繞是大型鯨類和海洋生物的威脅。小藍鯨之死突顯人類的自私，隨意扔棄不再使用的漁具，竟變成流竄在海洋中要命的可怕殺手。 如今，小藍鯨已蛻變為博物館永久典藏的標本，它以不同的形式重生，它的生命延續，並有了新的意義和價值。但人們要能反省並行動，共同為保育海洋盡一份心力，還給海洋乾淨的面貌，這才是小藍鯨之死教我們最重要的功課。",
    "spotlight_answers": [],
    "paragraphs": [
      "2020年1月25日，正逢農曆大年初一，臺東長濱鄉的民眾發現一頭長達24公尺、寬2.5公尺的巨大鯨魚在海灘擱淺死亡，經科學家們鑑定，證實是頭藍鯨。 藍鯨是世界上體型最大的動物，19世紀初以前曾經維持穩定的族群數量，但在商業利益追逐下，捕鯨者使用大型鯨砲獵殺藍鯨，不到一個世紀便使牠們幾乎滅絕，目前世界自然保育聯盟（IUCN）已將藍鯨列為瀕危物種。臺灣在日治時期曾捕獲過藍鯨，但尚未有海上目擊紀錄，這次難得的藍鯨再現，卻不幸的是擱淺死亡案例，讓國內鯨豚界又震驚又難過。 研究團隊檢驗發現，這隻死亡的藍鯨全身仍有許多軟骨存在，研判是隻不到2歲、還在生長期的幼年藍鯨。牠身形削瘦，專家根據遺體狀況及骨骼判斷，小藍鯨生前被海廢漁具繩索纏繞住頭部，時間可能長達5至6個月，因為小藍鯨時候生長速度快，頭骨兩側被繩索束縛，竟勒出超過10公分深、5公分寬的溝痕，嘴巴也因被勒住無法張嘴進食；解剖發現，小藍鯨近乎空腹，食道和胃裡只有一隻半消化的魚眼睛，體內脂肪幾乎燃燒殆盡，可說牠最終是被活活餓死的，讓人心疼不已，許多人感嘆這是小藍鯨「悲傷的故事」。 為了保留珍稀的藍鯨標本，海洋保育署、成功大學與海洋生物博物館共同合作，隨即進行藍鯨的骨骼重建與研究典藏。目前全球完整的藍鯨骨骼標本僅約 25 件，加上藍鯨骨骼結構複雜，修復不易，更顯得這次的標本製作任務重大。歷經近四年的骨骼修復，屏東海生館終於在2023年底，以「巨鯨之路」為名，完整展示其標本，開放國人參觀。展廳以深藍色的光影投射，巨大的骨骼標本高懸於屋頂，模擬小藍鯨優雅下潛海洋的姿態，想要展現藍鯨生活於海洋應有的動態美感與生命力。 展廳也同步展示造成小藍鯨死亡的「兇器」，也就是當時纏繞在藍鯨嘴上的尼龍繩，藉此提醒大家，漁具纏繞是大型鯨類和海洋生物的威脅。小藍鯨之死突顯人類的自私，隨意扔棄不再使用的漁具，竟變成流竄在海洋中要命的可怕殺手。 如今，小藍鯨已蛻變為博物館永久典藏的標本，它以不同的形式重生，它的生命延續，並有了新的意義和價值。但人們要能反省並行動，共同為保育海洋盡一份心力，還給海洋乾淨的面貌，這才是小藍鯨之死教我們最重要的功課。"
    ],
