        "text": "1984年12月下旬，北極海翻騰著，有三千多頭白鯨為了追捕魚群，游進了一個狹長的海峽。但牠們運氣不好，遇上極地寒流，凜冽的寒風讓氣溫快速降到零下30度，海水開始結冰，冰層厚達4公尺，整個海峽成為一片白色的冰原，只剩一點點的海面還未結凍。"
