        "text": "可是，新的難題來了。白鯨是野生動物，從來沒有見過這種冒著黑煙、又會發出噪音的大怪獸。怪獸的推動器一響，透過海水的傳音送到白鯨耳中，讓牠們又驚又怕，根本不敢靠近，也不敢順著水道離開。時間一分一秒流逝，白鯨已經受困近兩個月，筋疲力竭，又凍又餓，眼看即將全數葬身海底。"
