    "spotlight_raw_text": "閱讀聚光燈\n摘要策略—問題.解決結構找重點\n\n    這篇故事也是一篇說明文，講「全世界第一張股票」是怎麼誕生的。故事結構裡有明顯的問題、解決、結果。前面兩課我們已經學過怎麼用線索，來找到文章中的「問題、解決、結果」，我們再來複習這個祕訣，請你連連看。\n\n策略\n\n祕訣\n(1)\n問題\n● 　　　 　　 　\n通常出現在文章的後段，常接在「解決」之後，說明行動後，造成了什麼改變，可能出現「結果」、「最後」等關鍵詞。\n\n8001018351500●         ●\n\n(2)\n解決\n    　　  　          ●           ●\n　　　　     　\n通常出現在文章的開頭，描述一個「不好的事或困難」需要解決。\n(3)\n結果\n         　　●         ●\n　     　　　　\n通常出現在文章中段，你可以找找「有人想出辦法或行動」的句子在哪裡。\n\n◎",
    "story_text": "十七世紀初，荷蘭是一個小小的國家，但它有大大的夢想。當時，來自亞洲的香料十分珍貴，一點點胡椒或肉桂就可以賣到很高的價錢。許多歐洲人想要航行到遙遠的亞洲，去買香料再帶回歐洲來賣。\n雖然出海遠航可能帶來很高的利潤，但是，四百多年前，要展開一場長途遠洋探險可不容易：要造船、準備糧食、僱用水手，還得面對風暴、海盜，船員可能生病受傷，每一樣都需要用很多錢，這是一筆任何個人都無法單獨承擔的龐大費用。\n這時，荷蘭人有了一個巧妙的構想——大家一起出錢，讓一家公司來主導這類的遠洋行動。於是，荷蘭東印度公司（Dutch East India Company）成立了，它是全世界第一家發行「股票」的公司，它把經營公司需要用的錢，分成許多小份，每個小份就是一張股票。如果人們認為這家公司會賺錢，就可以出錢認購它的股票，投資這家公司。只要有許多人投資，公司就可以有足夠的經費組成船隊，揚帆啟航。\n「投資？那是有錢人的事吧？」你心裡也許會這樣問。\n股票發明之前，投資幾乎是君王和貴族的專利。但是，股票發明後，連平民百姓都可以參與投資了。例如，荷蘭東印度公司這趟航行需要用1000萬元，就發行了10萬張股票，每張股票100元。瑪莉是個傭人，她用工作多年的積蓄1000元，買了10張股票；達安是個滿手老繭的水手，他用節衣縮食存下的5000元，買了50張股票；奧倫治是貴族，又是大富翁，他大手一揮，掏出5萬元，買了500張股票。\n買了股票後，瑪莉、達安、奧倫治和數以千計的平民百姓都成為公司的「股東」，也就是公司的老闆，所有股東共同擁有荷蘭東印度公司。透過股票，連替人打掃的瑪莉，也可以參與投資了。\n只要公司成功把香料帶回來，賺了錢，股東就可以根據股票的數量，分享公司的獲利，這種獲利稱為「股利」（公司賺錢後按股票數量分發給股東的利潤），通常公司每年發一次。如果今年公司賺了很多錢，股利是18%，每一張股票就可以拿到18元，以瑪莉來說，今年她可依持股比例領取180元的股利。\n看看以下的表格，你會更清楚每位股東的收益：\n瑪莉的投資每年獲利180元，過了10年，已經賺了1800元。文森太羨慕了，於是他問瑪莉：「我用2000元跟你買你的股票好嗎？」如果交易談成了，瑪莉當時用1000元買的股票，現在可以賣2000元。若加上這10年的股利，你算算看，瑪莉一共賺了多少錢？\n股票制度讓全世界的人都看到了集資的力量，只要許多人願意各出一點錢，就可以完成過去難以想像的宏大計畫：造更大的船、開發新的貿易路線，甚至到遙遠的陌生國度，展開新的建設。\n最後，荷蘭東印度公司有了龐大的資金能派遣船隊，於1624年航行了半個地球後，到臺灣來，在臺南建立了熱蘭遮城（今天的安平古堡），統治臺灣長達38年。這支厲害的船隊，原來是股票制度撐起來的呢。",
