    "title": "從〈螞蟻與蟋蟀〉看生命的多樣性",
    "genre": "說明文",
    "authors": "課文 ：林玫伶 學習單：張明珠",
    "strategy_name": "用表格整理訊息-比較異同",
    "spotlight_raw_text": "閱讀聚光燈\n用表格整理訊息\n    之前我們學過可以將文章內容整理成表格。表格的優點有(1)幫助讀者快速看到文章的重點。(2)藉由訊息分類，將文章化繁為簡。(3)讓讀者能發現訊息的共同點或差異處。\n　　在「L3女性太空人登月」，我們已經學過整理表格的步驟：\n(1)確認比較的對象：是什麼和什麼比較？寫在表格第一列。\n(2)找重點：先用鉛筆將每段可能的重點句（行為特徵）畫起來。\n(3)想主題1.2…的名稱：從重點句判斷「主題」。 \n(4)寫表格左欄：將「主題」寫在表格左欄項目中。\n(5)將文章細節填入表格內。\n項目           　　 對象\n對象１\n對象２\n228178317500主題１\n文章細節\n文章細節\n主題２\n文章細節\n文章細節\n　　現在就讓我們利用本課文章來練習看看吧！\n◎",
    "story_text": "我喜歡觀察螞蟻工作的樣子。牠們往往集體出動，排著長長的隊伍，合力搬運食物，展現有紀律、有秩序的行動。螞蟻的嗅覺一流，再細微的甜味都逃不過牠們的好鼻子，只要糖罐蜜瓶之類的沒收好，不久就會引來螞蟻大軍。 螞蟻雖然身軀小，卻有驚人的力氣，能夠扛起比自己體重大上數十倍的食物。牠們是社會性昆蟲，分工嚴密。整個蟻群的核心是蟻后，所有的螞蟻都為了一個共同的目標——協助蟻后繁衍後代。工蟻日夜奔波，冒著生命危險外出覓食，都是為了延續蟻群的生命。 從生物行為的角度來看，螞蟻的合作是為了共同的生存，而蟋蟀則用不同的方式延續族群的生命。 夏秋時節最容易發現蟋蟀的蹤影，草叢灌木間常傳來一聲聲「唧唧」的蟲鳴，此起彼落、忽遠忽近，正是蟋蟀在大自然的舞台放聲高歌。但你知道嗎？這些會發出鳴叫聲的都是雄蟋蟀呢！ 原來，蟋蟀高歌是為了求偶，雄蟋蟀會摩擦前翅發出清脆的鳴聲，就像在演奏情歌，吸引女朋友的注意，或是警告其他雄蟋蟀不要靠近地盤、不要來爭奪女朋友；雌蟋蟀最終會選擇聲音最吸引她的伴侶，進而交配繁殖下一代。 瞭解蟋蟀的生物行為，就會知道牠們的高歌不是娛樂，而是競爭——牠們透過歌聲吸引雌蟋蟀，爭取繁衍的機會。與螞蟻不同的是，每一隻蟋蟀都可以自行繁衍後代，因此雄蟋蟀之間充滿了競爭。 蟋蟀和螞蟻並列，則起源於《伊索寓言》。在寓言故事裡，蟋蟀是一隻鎮日高歌，不知貯糧的天兵，到了冬天只好跟螞蟻伸手乞求，懶惰又沒骨氣。然而，仔細了解後我們會發現，蟋蟀的高歌與螞蟻的存糧一樣，都是生物遵循本能的行動。螞蟻藉由合作，來達成群體繁衍的需求；蟋蟀則透過競爭，延續自己的基因。 生命的多樣性體現在這些不同的生存策略中。我們看待事物時，如果只從自己的角度出發，很容易得出片面的結論。螞蟻可能覺得蟋蟀荒廢正業，蟋蟀則認為螞蟻缺乏情趣，但其實牠們的行為背後都有著共同的目的——延續生命。《伊索寓言》為了教育兒童的需求，把人類認為的美德與惡習強加在小昆蟲身上，真是委屈牠們了。",
    "spotlight_answers": [],
    "paragraphs": [
      "我喜歡觀察螞蟻工作的樣子。牠們往往集體出動，排著長長的隊伍，合力搬運食物，展現有紀律、有秩序的行動。螞蟻的嗅覺一流，再細微的甜味都逃不過牠們的好鼻子，只要糖罐蜜瓶之類的沒收好，不久就會引來螞蟻大軍。 螞蟻雖然身軀小，卻有驚人的力氣，能夠扛起比自己體重大上數十倍的食物。牠們是社會性昆蟲，分工嚴密。整個蟻群的核心是蟻后，所有的螞蟻都為了一個共同的目標——協助蟻后繁衍後代。工蟻日夜奔波，冒著生命危險外出覓食，都是為了延續蟻群的生命。 從生物行為的角度來看，螞蟻的合作是為了共同的生存，而蟋蟀則用不同的方式延續族群的生命。 夏秋時節最容易發現蟋蟀的蹤影，草叢灌木間常傳來一聲聲「唧唧」的蟲鳴，此起彼落、忽遠忽近，正是蟋蟀在大自然的舞台放聲高歌。但你知道嗎？這些會發出鳴叫聲的都是雄蟋蟀呢！ 原來，蟋蟀高歌是為了求偶，雄蟋蟀會摩擦前翅發出清脆的鳴聲，就像在演奏情歌，吸引女朋友的注意，或是警告其他雄蟋蟀不要靠近地盤、不要來爭奪女朋友；雌蟋蟀最終會選擇聲音最吸引她的伴侶，進而交配繁殖下一代。 瞭解蟋蟀的生物行為，就會知道牠們的高歌不是娛樂，而是競爭——牠們透過歌聲吸引雌蟋蟀，爭取繁衍的機會。與螞蟻不同的是，每一隻蟋蟀都可以自行繁衍後代，因此雄蟋蟀之間充滿了競爭。 蟋蟀和螞蟻並列，則起源於《伊索寓言》。在寓言故事裡，蟋蟀是一隻鎮日高歌，不知貯糧的天兵，到了冬天只好跟螞蟻伸手乞求，懶惰又沒骨氣。然而，仔細了解後我們會發現，蟋蟀的高歌與螞蟻的存糧一樣，都是生物遵循本能的行動。螞蟻藉由合作，來達成群體繁衍的需求；蟋蟀則透過競爭，延續自己的基因。 生命的多樣性體現在這些不同的生存策略中。我們看待事物時，如果只從自己的角度出發，很容易得出片面的結論。螞蟻可能覺得蟋蟀荒廢正業，蟋蟀則認為螞蟻缺乏情趣，但其實牠們的行為背後都有著共同的目的——延續生命。《伊索寓言》為了教育兒童的需求，把人類認為的美德與惡習強加在小昆蟲身上，真是委屈牠們了。"
    ],
