    "title": "爺爺奶奶來了以後",
    "genre": "說明文",
    "authors": "課文 ：陳韻如 學習單：陳允捷",
    "strategy_name": "用表格整理訊息-從細節歸納標題列名稱",
    "spotlight_raw_text": "閱讀聚光燈\n用表格整理訊息-1040357785\n五",
    "story_text": "根據內政部統計，2025年，65歲以上人口突破20%，臺灣已成為「超高齡社會」。而且，三代同堂的家庭比例從十年前的31.2%上升到38.7%；也就是説，每10個家庭中，就有將近4個是和爺爺奶奶一起生活的，我家就是一個典型的例子。 爺爺奶奶搬進來那天，我們家就熱鬧了起來。客廳多了兩張他們最愛的藤椅，陽台上擺滿了奶奶精心照料的盆栽，廚房裡也飄起許久未聞的古早味菜香。但要讓三代的新組合可以合「住」無間，全家都需要動員調整和適應。 首先是高齡友善空間，我們敲掉幾個可能讓人絆倒的門檻、在浴室加裝止滑扶手、地板舖上防滑墊、並確保室內的光線充足。這些看似簡單的改變，其實都經過專業設計，目的是為了讓爺爺奶奶住得更安全。 最大的改變發生在餐桌上，以前爸媽忙於工作，家裡的餐點常常是叫外送或用微波食品快速解決，爺爺奶奶住進來後，餐桌成了全家人溫馨團聚的中心。奶奶總是變魔術似的端出一道道好菜，即使要遵照營養師建議的「三高二低」原則──高蛋白、高鈣、高纖維、低油、低鹽，她仍讓每道菜都美味可口。爺爺也會帶著我們「洗手作羮湯」，像上個週末，我們製作了獨門的醃製醬菜—從上市場挑選新鮮白菜、調配鹽水比例，到把握黃金發酵時間，每個步驟都蘊含著祖輩的智慧。整個過程帶來的不只是口福，更是現代超市裡買不到的珍貴記憶。 我們的生活作息也跟著改變了。我是晚睡晚起的夜貓子，夜裡不過十二點不睡，早晨，能賴則賴，絶對沒有「聞雞起舞」的事。不必上學的週末或假日，更一定睡到日上三竿。現在不同了，晚上九點，爺爺奶奶「沒電了」，就寢時間到，我們只能關電視，去廚房倒個水，都要躡手躡腳，像個小偷。早上六點多，就會在睡夢中聽見各種聲音，從窸窸窣窣的拖鞋聲、鏗鏗鏘鏘的鍋盤聲、到喧鬧紛雜的晨間新聞。漸漸地，我竟然早起的日子愈來愈多，開始發現早起的「光明面」：一大早就能吃到熱騰騰的早餐，跟著爺爺奶奶到公園散步，在明亮卻不炎熱的陽光下，呼吸著清新的空氣，整個人都變得神清氣爽。 和老人家的「小衝突」是難免的，畢竟每個世代都有自己熟悉的生活方式和價值觀。音樂的喜好就有很大差異，我愛聽風格強烈的周杰倫，爸爸媽媽喜歡聽動力火車的「忠孝東路走九遍」，爺爺奶奶喜歡的卻是蔡琴的「最後一夜」；我們夏天習慣開26度的冷氣，他們卻披著外套、不但喊冷，還說開冷氣浪費錢。他們只要看到我拿著手搖飲，就開始唸：「你知道那裡面有多少糖嗎？你再吃這種垃圾食物，老了你就知道！」 爺爺奶奶來一段時間以後，我們漸漸琢磨出相處之道。有研究說，和長輩同住的青少年特別容易培養出良好的「情緒智商」，這和我的感受一致。點點滴滴的相處經驗，教會我傾聽不同世代的聲音，並學習設身處地為他人著想。 現在當爺爺奶奶分享「古時候」的事時，我不再覺得是囉嗦或嘮叨了，我開始帶著好奇心去聆聽、理解這些悲歡離合。三代同堂對我來說，只要轉換個觀點，歡喜收獲就會遠大於衝突不適呢。",
