    "title": "你看見時代的灰犀牛了嗎？談人口負成長",
    "genre": "說明文",
    "authors": "課文 ：曾世杰陳淑麗 學習單：張明珠",
    "strategy_name": "圖表繪製與判讀-折線圖",
    "spotlight_raw_text": "閱讀聚光燈\n折線圖\n452628016510000　　你聽過資料視覺化嗎？它是將複雜的資訊以圖表的方式呈現，讓讀者能更容易的理解訊息。本課我們要來學習折線圖，現在就讓我們看看如何將表格的資訊繪製成折線圖：\n表  臺北市113年1~7月平均氣溫變化統計表\n月份(月)\n1\n2\n3\n4\n5\n6\n7\n氣溫(℃)\n16.9\n18.0\n19.3\n24.9\n25.4\n28.5\n30.0\n數據資料來源：CODiS氣候觀測資料查詢服務站(年報表-逐月資料)\n❶選出折線圖的標題：(請打勾，單選)\n3924302794100□臺北市113年1~7月平均氣溫變化統計表\n臺北市113年1~7月平均氣溫變化折線圖\n452374029235100❷選出橫軸表示的統計項目及單位：□氣溫(℃) 月份(月)　　\n105966525230700810260358775\n\n0\n臺北市113年1~7月平均氣溫變化折線圖\n\n00\n\n0\n臺北市113年1~7月平均氣溫變化折線圖\n\n❸選出縱軸表示的統計項目及單位：氣溫(℃) □月份(月)　　\n\n❹省略符號：省略不需要用到的刻度。\n❺用點來表示橫軸和縱軸上的兩組數字，依序用直線把這些點連起來。\n◎考考你：\n(1)從折線圖來看，最高溫會落在【 7 】月，氣溫是【 30　】度。\n(2)從折線圖可看出：從1月到７月的氣溫變化是如何？(請打勾，單選)\n　【越來越高　□越來越低　】。\n(3)承上題，你是怎麼判斷的？因為我看到折線圖的趨勢是\n　【上升　　 □下降　】。\n◎",
    "story_text": "所謂灰犀牛，指的是正在發生、明明可見的負面事件，但因為沒有急迫性，大家卻視而不見。例如，每天都吃高糖飲料和炸雞，日復一日之後，對國中生的健康一定有壞的影響，但壞影響要很久以後才會發生，許多國中生因此完全不在意，這些高熱量飲食就是他們視而不見的灰犀牛了。 這一課要講的主題是每況愈下的「人口負成長」，你看見這頭灰犀牛了嗎？ 當一個國家每年的「出生人口數」少於「死亡人口數」時，我們就說，這個國家出現了「人口負成長」。目前許多國家都面臨人口負成長，其主因是「少子化」。少子化會讓年輕人口比率逐漸降低，老年人口比率逐漸增加。臺灣正是全世界少子化情況最嚴重的國家。 圖1顯示臺灣從1951年（民國40年）以來婦女總生育率逐年下滑的情形。「總生育率」指的是「平均每位婦女一生中所生育之子女數」。從圖1可知，民國40年時，臺灣每位婦女一生生育了7個子女，再來總生育率一路下滑，到了1984年，每位婦女平均只生2.1個子女，2021年，只剩0.975個子女，是全世界各國倒數第一名。新生兒減少，兒童的佔比降低，相對的老年人口的比例會愈來愈高，人口開始老化。 圖1 1951~2024年臺灣婦女總生育率 圖2呈現的是2011年到2022年臺灣出生人數與死亡人數的折線圖，可以看到出生人數（●實線）是逐年下滑，而死亡人數（▲虛線）是逐年上升的。2019年以前，實線高於虛線，也就是出生人數大於死亡人數，人口正成長。但2019年，虛線實線開始交叉，表示出生人數和死亡人數相當。但2020之後，趨勢倒過來了，虛線開始高於實線，人口開始負成長。 圖2 臺灣出生人數與死亡人數在2019年出現死亡交叉 人口負成長對經濟會帶來什麼影響呢？悲觀者認為社會的生產者（即年輕人和壯年人）負擔將會越來越重。2025年，臺灣每100個人中，有68人為生產者，要扶養32名被扶養者（20名老人及12名小孩）。亦即，2名生產者扶養1名被扶養者。但推估到2065年，每100個人中的生產者減少到50人，他們要扶養50名被扶養者（41名老人及9名小孩），也就是說，臺灣每1個生產者要負擔1名被扶養者。樂觀者則認為老年人長年累積財富，他們有積蓄、有房產，他們年紀大了，會需要購買各種貨品及服務，因此會帶動經濟，創造工作機會。也有人認為，人口負成長，對環境是友善的，因為糧食和各種物資的消耗會減少，對地球帶來的負擔、污染，也可能降低，人類長年蹂躪這個水藍色的星球，現在總算開始踩煞車了。 在臺灣，人口負成長已經是一個不可逆的趨勢，它帶來人口結構的改變、讓勞動力人口比率下降，雖然加重了生產者的扶養負擔，但也可能帶動新一波的經濟變革。人口負成長是我們的現在、是我們的未來，認識人口負成長帶來的改變，或許可以讓我們對自己的未來有更清楚的想像。",
    "spotlight_answers": [],
