    "authors": "課文 ：林玫伶 學習單：陳淑麗",
    "strategy_name": "推論策略-找作者觀點和支持理由",
    "spotlight_raw_text": "閱讀聚光燈\n推論策略—找作者觀點與支持理由\n閱讀說明文或議論文時，讀出「作者的觀點」和「支持觀點的理由」，以及推論出隱含的意義，才能完全理解文章。觀點和支持理由間的關係，就像插圖中的桌子一樣，桌子要有腳才站得穩，觀點要有支持理由，才有說服力。\n\n我們用底下❶～❸的步驟來讀出「作者的觀點、支持理由和隱含的意義」。\n   【❶確認觀點】   【❷找支持理由】   【❸推論隱含意義】\n(作者提出什麼主張？)  (用哪些證據支持？)  (隱含什麼深層意義？)\n接下來，我們來運用這個策略，分析〈塑膠，好用不好甩〉這篇文章的內容。\n一、找作者觀點、支持理由與隱含意義\n步驟❶──找作者觀點\n祕訣：觀點常是判斷句；先看標題與開頭段。\n◎",
    "story_text": "1997年，一艘貨輪在英國外海遭遇百年罕見的巨浪，船上四百八十萬個樂高玩具落入海中，從此展開了「塑膠漂流記」。直到今天，海浪還不時把這些積木沖上英國、愛爾蘭甚至荷蘭的沙灘，看似大自然在送免費玩具，但其實，這是一場長時存在的塑膠污染悲歌。樂高的故事讓我們看到一個事實：塑膠一旦進入環境，就很難消失。 塑膠帶來的便利與危害 塑膠幾乎無所不在，從飲料杯、外送餐盒、瓶子、鞋子、衣服、家具，到手機與汽車，處處有塑膠的蹤跡。它不怕水，又輕又便宜，因此被大量生產。1950年以來，全球塑膠產量成長了200多倍。麻煩的是，這些塑膠用品相當「長壽」，因為它們很難在自然界裡完全分解。目前全球每年超過一半的塑膠垃圾，最後流入海洋、河流或被棄置在環境中，它們不會乖乖消失，甚至最後還會回到我們身邊。科學家在世界最深的馬里亞納海溝和最高的聖母峰都發現了塑膠微粒。從深海魚類到高山積雪，塑膠無遠弗屆，不但已經滲入地球最極端的角落，也滲入每個人的身體。 當塑膠垃圾被陽光照射、海浪拍打，就會分解成塑膠微粒。魚、蝦、貝類會把它們當食物吃下去，最後透過食物鏈，再被人類吃進肚子裡。科學家已經在人體血液、肺部，甚至母乳中發現塑膠微粒，雖然科學界還在研究這些物質對健康的影響，但已有證據顯示，它們可能增加癌症、糖尿病與心血管疾病的風險。 回收與減塑難在哪裡？ 1.回收難 臺灣的塑膠回收率大約是世界平均值的四倍，許多人會把寶特瓶、牛奶罐沖洗乾淨再丟回收桶，這些努力當然有幫助，但從全球來看，這點努力只能算是杯水車薪。全球每年的塑膠垃圾高達四億噸，被回收的不到一成，其餘被丟進掩埋場，或進入河流和海洋，成為環境永遠的負擔。回收率這麼低的原因很多，例如民眾環境意識不足、法規及配套措施闕如、執行技術困難等等；就我們生活所見，分類回收桶數量不足且位置不便、塑膠種類繁多（還有複合材包裝），常讓民眾猶豫是否該回收、再加上餐盒與飲料杯的油污與殘渣清潔困難，常只能當一般垃圾丟棄。此外，分類、收運與再製的成本比製作新的塑膠還貴，也影響了廠商的回收意願。 2.減產更難 雖然每一個人都知道塑膠對環境的危害，也都知道從源頭減產是徹底解決問題的辦法，但為什麼塑膠生產仍然有增無減呢？塑膠的原料是石油，對產油國和塑膠製品大國來說，塑膠是一筆賺錢的大生意，如果減產，勢必影響他們的經濟發展與就業機會。所以，雖然2024年聯合國嘗試簽署《全球塑膠公約》，但因產油國反對而功敗垂成，各國至今仍然自行其是。這不是誰對誰錯，而是現實中的兩難。 減塑從你我做起 不過，這並不代表我們什麼都做不了。國際需要時間協商，但個人可以立即行動，因為「需求」會影響「供應」。只要越來越多人選擇減塑，廠商就會開始推出更多環保包裝，市場也會跟著改變。 下次買手搖飲時，能不能自備杯子？網購時，能不能勾選「簡易包裝」，或少用一次性塑膠？外出買東西時，能不能自備環保袋？雖然這些看起來只是小動作，卻能讓「塑膠水龍頭」慢慢關小一點。 更重要的是，當你理解這些問題，就能成為一位環保倡議者，你可以跟同學討論、跟家人分享，讓更多人知道，塑膠真的「好用不好甩」，它會長久留在環境中；但更重要的是，我們也甩不掉，因為將來承受這份麻煩的，就是長大後的我們自己。",
    "spotlight_answers": [],
