    "title": "用科學方法伸張正義的神探",
    "genre": "說明文",
    "authors": "課文 ：曾世杰 學習單：唐儀庭",
    "strategy_name": "解決問題-科學探究法",
    "spotlight_raw_text": "閱讀聚光燈\n解決問題—科學探究法\n從文章中可以發現李昌鈺博士在辦案的過程中，不斷地運用科學方法思考的歷程：發現問題→提出假設→驗證假設→解答。\n發現問題：從現場觀察到的現象、找到的線索，而產生的疑問。\n提出假設：對問題提出一些可能的答案。\n驗證假設：運用方法、蒐集證據驗證假設的答案是否正確。\n提出解答：根據驗證的結果，回答提出的問題。\n只要能熟練這樣的思考模式，你也能成為名偵探喔！\n讓我們回到課文：李博士在辦案過程中，分別產生了三個問題，並且根據問題提出假設，最後驗證了假設。接下來，請你跟著李昌鈺博士一起辦案吧！\n1.推理示範\n175308145327\n死者被刺18刀，為什麼地上沒有血？\n問題\n血跡已經清理過了。\n這裡不是第一現場。\n假設\n檢驗\n解答\n這裡是案發現場，但血跡已經被清理過了。(單選)\n假設一【 成立 / □不成立】；\n假設二【 □成立 / 不成立】。00\n死者被刺18刀，為什麼地上沒有血？\n問題\n血跡已經清理過了。\n這裡不是第一現場。\n假設\n檢驗\n解答\n這裡是案發現場，但血跡已經被清理過了。(單選)\n假設一【 成立 / □不成立】；\n假設二【 □成立 / 不成立】。\n\n418602144083\n用化學藥品看到滿地血跡反應。\n用化學藥品看到滿地血跡反應。\n\n2.",
    "story_text": "科學，是一種系統性解決問題的方法。科學家對自然界的現象好奇，有了「研究問題」後，對問題提出暫時性的答案，稱為「研究假設」，再來是蒐集證據「檢驗假設」是否為真，一直到問題得到合理的解答。其實，警察辦案也是循「問題、假設、檢驗假設、解答」這個程序哦！底下是世界聞名的刑事鑑識專家李昌鈺博士親身經歷的故事。 有位72歲的老太太獨居在美國康乃狄克州的一個城市裡。這天是感恩節，外面大雪紛飛。中午，鄰居的媽媽烘了一個餅，請小孩送到老太太家，希望她在團圓的節日裡，不致於太孤苦伶仃。 孩子拿著餅，按鈴、敲門都沒人應，只好逕自開門走進，一進房，小朋友尖叫一聲，血液都冰凍了。她看見老太太倒在廚房裡，一動也不動，已經死去。 當天晚上十二點，世界聞名的刑事鑑識專家李昌鈺博士從床上爬起來接電話，電話那頭說：「李博士，我們是警局的重案小組，這裡發生了一樁令人髮指的命案，要請您移駕過來看看。」李昌鈺立刻著衣，冒著大雪趕到現場。 李昌鈺到了現場，先問在場辦案的警方人員：「你們來多久了？」 「十小時了。」法醫同時報告：「老太太被刺了18刀，凶刀就是廚房的刀，被丟在洗碗槽裡。」 李昌鈺環顧四周，問：「十八刀？血呢？」地上沒有血。他馬上推論出兩個假設：血跡已經清理過了，或者，這裡不是第一現場。 李昌鈺請同仁在廚房地板上噴化學藥品，這種藥品和血液裡的鐵離子反應後，會放出藍色螢光。一噴完藥，看起來乾淨的地板，在關燈後，赫然出現大片藍色螢光的血跡反應。李昌鈺判斷，清理現場需要一段時間，凶手一定是老太太的熟人，清楚知道她的作息與交往關係，這才敢留在現場清理血跡。此外，凶手踩過血跡之後留下的幾個鞋印，也因為藥品的緣故清楚顯現，經過比對，這是彪馬牌球鞋，從球鞋的大小，可以推斷出凶手的身高。 他立刻下了一個指令，派出200名刑警去翻找附近所有的定置垃圾箱，目標是找到凶手的球鞋。同仁問：「今天是感恩節團聚的日子，不能隔兩天再去找嗎？」李昌鈺回答：「不行，兵貴神速，現在就要動員，今晚不搜，明天垃圾會去哪裡？垃圾場。垃圾場太大、垃圾太多，很難找，即使找到了，也早被汙染了。」 動員令下達25分鐘之後，指揮中心收到回報：找到球鞋了。鑑識人員立刻檢驗這雙鞋，鞋上有血點，而且從鞋子裡的毛髮，可以知道主人是白人，但，到底這個人是誰呢？ 李昌鈺說：「鞋子是不是在購物中心旁邊的垃圾箱找到的？」 同仁答：「是的，你怎麼知道？」 李昌鈺說：「別管我怎麼知道的，快去找那個購物中心的運動用品店或鞋店的老闆。」 老闆三更半夜被電話吵醒，刑警請他回憶，前一天有沒有一個白人來買鞋子？老闆查了店裡的記錄，找到前一天下午，有一個男人用信用卡買了一雙鞋子，警方立刻查出信用卡的主人和地址。 清晨六點。「叮咚！叮咚！」男人睡眼惺忪地開門，門外滿是警察，在詢問後，這位年輕的白人承認昨天殺了老太太。 凶手是老太太的遠親，有吸毒的惡習，老太太偶爾請他到家裡幫忙，工作之後會給他一點錢。昨天感恩節，凶手去找老太太要錢，老太太不給，兩人起了爭執，凶手情緒失控出手打昏了老太太，他害怕老太太醒來會報警，便一不作二不休，拿了廚房的刀殺死了老太太。 案子破了。你能看到李博士「問題、假設、檢驗假設」的辦案過程嗎？一個沒有人看見、沒有人知道、線索有限的凶案，李博士和他的團隊用鑑識科學，替無聲的死者說話，終於讓正義得到伸張。",
    "spotlight_answers": [],
