    "authors": "課文 ：林玫伶 學習單：唐儀庭",
    "strategy_name": "自我提問-詰問作者的步驟",
    "spotlight_raw_text": "閱讀聚光燈\n詰問作者\n    本課讀書會討論的主題是「作者(朱自清)為什麼選擇寫背影?」文中的老師、同學針對這個問題，不斷的深入討論，像這樣對作者的「寫作目的」、「寫作手法」以及「文章內容」提出問題，這個策略就是「詰問作者」。\n　　詰問作者就是向作者提問。不停的向作者提問能讓我們在閱讀文章時，不再只是被動的接收訊息，而是有意識的主動思考，進而幫助我們更加深入的理解文章。\n　　那麼詰問作者該怎麼做呢？可以參考本課讀書會的作法：\n1.仔細閱讀文章：可特別注意文中的人物、情節、背景和文字運用。\n2.提出問題：比如問作者寫作目的或作者的寫作手法，以本課讀書會為例，作者是林玫伶喔。\n(1)作者寫作目的：詢問作者這段文字或文章「這樣子寫的目的或理由是什麼」，像是：\n⚫作者寫「讀書會」這篇文章的目的是什麼？\n(2)作者寫作手法：詢問作者如何安排情節、使用修辭或描寫方式等問題，像是：\n⚫作者詳細寫出學生對話的理由是什麼？\n⚫作者為什麼要對讀書會討論過程做這麼詳細的描寫呢？(描寫方式)\n3.尋找答案：從文章中尋找答案，也可以查詢相關資料，或與他人討論。\n\n◎",
    "story_text": "朱自清的〈背影〉是現代散󠇡文的經典之作，曼屏讀完後產生一個疑問：文中父親對兒子多次表達了關心，但兒子直到看見父親的背影才深受感動，「為什麼從正面看父親時不感動，」曼屏問：「看背影時卻感動到流淚？」 義傑重󠇡新讀了讀文章，發現朱自清前幾次和父親互動時，內心還會暗笑父親的迂，到了父親為他爬月臺買橘子，態度整個大轉變，「會不會是朱自清愛吃橘子？」同學們聽了哄堂大笑，義傑趕忙說：「開玩笑的啦！」 老師認為這是個好問題，決定針對〈背影〉舉辦一場讀書會，討論主題是：為什麼作者選擇描寫父親的「背影」，而非正面或側影？ 老師要大家找出文章中辦完祖母喪事後，父子互動的片段，並根據情節的順序，邀請各組同學上臺演出。 第一組有三位同學，分別扮演父親、兒子和茶房。演的是父親起先囑託茶房陪兒子同去，後來改變主意，決定親自送兒子去浦口車站的情節。演出時，父親對茶房鉅細靡遺的交代，兒子則在一旁抱胸而立，表現出不󠇡置可否的樣子。演完後，老師在黑板上畫出三人互動的示意圖。 第二組演父親在車站與腳夫討價還󠇡價，兒子嫌他話說得不好，不停插嘴。有了老師剛剛的示範，第二組很快畫出三人互動的示意圖。 第三組演出父子進入車廂後的一幕。父親反覆叮嚀兒子，又囑託茶房好好照顧，兒子雖未插嘴，但內心有一大串獨白，認為父親根本多此一舉。同學們運用「定格」的概念，把肢體動作和臉部表情「凝住」，呈現靜止畫面，很有創意，獲得全班熱烈掌聲。 第四組演出父親買橘子的段落。同學將幾張課桌拼成兩邊的月臺，飾演父親的同學在外套裡塞了幾件衣服模仿父親肥胖的身材，又拿五六顆棒球充當橘子。老師提醒，父親當時五十多歲，動作沒有年輕人敏捷，演出時要注意。至於兒子則坐在遠處，看著父親吃力的上下月臺。 隨著一幕幕的展開，黑板上呈現了四幅角色互動示意圖，同學們七嘴八舌的討論後發現：前三幕的父子互動時，總有其他人在場，且面對面時，兒子對父親往往抱著反對、挑剔或輕蔑的態度。曼屏舉手說：「我認為茶房和腳夫的出現，分散了兒子對父親的注意力，他注意力似乎都放在父親囑託他們或講價的細節。當兩人進入車廂後，父親仍然在反覆叮嚀囑託，兒子心裡嘀咕著，滿心不耐煩，卻忽略了父親這一切都是為他做的。」 俊良也提出自己的見解，他認為，朱自清可能覺得老爸把他當媽寶，身為一個成年的知識分子，他對總是過度保護的父親不以為然，甚至心生抗拒。然而，當父親動作不再俐落，卻依然在眾人面前暴露自己的笨拙，只為了給遠行的兒子買橘子，那一刻的背影深深打動了他，改變了他對父親的看法。 老師肯定並整理出同學們的想法：朱自清之所以選擇描寫 父親的「背影」，是因為那一刻周圍無人干擾，他遠遠看著父親笨拙、肥胖的背影，為了幾個橘子在鐵道月臺間翻上翻下，他感受到父親的老邁，和父親對他的愛。這種「看不到的情感」透過背影更能打動人心。 在這次的讀書會上，同學們也分享自己類似的經驗。義傑提到阿公來看他比賽時，他本來有些不情願，覺得阿公過於熱心，但在等候比賽時，看到阿公氣喘吁吁幫忙整理器材的背影，便對自己先前的態度感到內疚。愛玲也分享，每次媽媽碎念要她去讀書時，她聽了就翻白眼，但轉頭看到媽媽在廚房洗碗的背影時，心裡又覺得自己的態度真不應該。 這場讀書會不僅讓大家理解作者為何選擇描寫「背影」的用意，也透過表演與討論，感受到作者情感的轉變。這篇文章之所以感人，正是因為無聲卻又真實的背影，引發了人們內心深處的共鳴。",
    "spotlight_answers": [],
