    "title": "別上「誘餌式標題」的鉤",
    "genre": "說明文",
    "authors": "課文 ：林玫伶 學習單：唐儀庭",
    "strategy_name": "媒體素養與識讀-認識誘餌式新聞標題",
    "spotlight_raw_text": "閱讀聚光燈\n認識誘餌式新聞標題\n　　誘餌式標題充斥在我們的生活中，但你知道嗎？誘餌式標題有固定的模式喔！了解誘餌式標題，可以讓我們更容易發現它，引誘讀者點擊時，常使用的手段有以下幾種：\n1.引發好奇心\n(1)常用的語詞：竟然、甚至、沒想到、反倒、原來、卻……\n(2)常使用的標點符號：！、？、……（不把話說完，引發好奇）\n(3)用模糊不清的訊息：不把話說清楚，引發讀者好奇點擊。\n　　如：肌肉要怎麼練？她釣出一堆網友解答\n2.用誇張的句子\n(1)句子中有強烈的「對比語詞」：標題中會用對比強烈的元素，讓標題更有趣，像是「平價v.s.有錢人」，「素人v.s.美女」。\n　　如：這家平價肉圓店，全臺首富也愛吃！\n(2)「刻意地放大或縮小」對事情的描述，引發讀者興趣。\n　　如：這樣子洗隱形眼鏡，醫生：「可能導致永久失明」\n3.使用充滿「誇大的情緒」的字眼\n標題中加入一些誇大的情緒性的字眼，像是：痛心、心都碎了、爆氣、人神共憤、嗨翻……。如：爸爸給兒子取奇葩名字，百萬網友笑到抽筋\n4.利用熱門的話題或公眾人物\n\n誘餌式標題有時會同時運用好幾種上面的方法喔！\n\n◎",
    "story_text": "寫作文時，文章必須緊扣題目，是每個人都懂的道理，如果文不對題，一定會被老師扣很重的分數。但在日常生活中卻常常看到「題不對文」的現象，尤其是新聞報導—記者完成文章後，下標題時故意添加一些調味料，讓標題變得辛辣、浮誇，也就是閩南語所說的「重鹹」、「重口味」，目的是為了吸引閱聽大眾點擊閱讀或收看，我們稱這種標題為「誘餌式標題」或「釣魚式標題」。 「下週雷雨炸全臺！氣象署急發快訊。」 「某明星慘遭爆打，死前驚吐一句話！」 正在滑手機的你，看到這樣的新聞標題，是不是很想點進去看看怎麼一回事？仔細看完新聞才發現，第一則氣象預報的新聞，其實是局部地區有雷擊和瞬間大雨的發生機率，不是「全臺」，也不到「炸」的程度，氣象署只是例行發布預報，沒有「急發」的意思；至於第二則新聞，寫的是這位明星在即將上映新戲中的情節，根本不是真實的社會事件。這兩則報導的內容都和標題描述有一大段差距，但「語不驚人死不休」的標題卻能輕易博取了人們的眼球。 為什麼媒體要把標題寫得這麼誇張呢？資訊爆炸的數位時代，媒體講究快速，每天透過各大入口網站、社群平台推播給大眾的新聞，多到讓人眼花撩亂、目不暇給󠇡。想要在眾多訊息中「被大家看見」，媒體便把腦筋動到「標題」上頭，用聳動的字眼吸引你的目光。這些誘餌式標題，就像媒體在「網海」中垂釣的一支支魚鉤，鉤著香噴噴的餌，誘餌對著你大喊：「選我！選我！」一旦你上鉤了，就為這則報導增加了點擊率、點閱率，發行新聞的媒體也因此能獲取較多的廣告收益；或是成功的帶風向，影響大眾的認知。此外，有些人懶得看內容，瞄到標題就信以為真，說不定還熱心的轉發推播給朋友，讓越來越多的劣質新聞四處傳播。 誘餌式標題不只出現在新聞報導，也出現在節目製作、廣告宣傳，甚至連書籍雜誌也會出現。面對這些亂象，作為閱聽者的我們該怎麼辦呢？ 第一，對誇張標題保持警戒，不輕易相信。誘餌式標題有一些特徵，除了文字用語聳動以外，也很容易引發讀者強烈的情緒反應。如果遇到這種情形，就該提高警覺。 第二，核對標題與內容的一致性。如果被偏離文章重點的誘餌式標題給引誘了，就當作上了一課，並把來源網站列為你的「閱讀黑名單」，因為這種不負責任、不講究品質的新聞，只會讓社會越來越亂。 第三，比較不同報導，培養獨立思考能力。你可以搜尋其他媒體對同一事件的報導，分析它們的標題，知道什麼是客觀中立的好標題，幫助自己提升鑑賞品味。 數位時代帶來前所未有的便利，但也讓扭曲的訊息四處氾濫。上網時別忘了隨時提醒自己：不上誘餌式標題的鉤，不再讓劣質新聞騙取我們的點擊率！",
    "spotlight_answers": [],
