    "title": "第一篇 雨林裡的奇蹟藥物",
    "genre": "說明文",
    "authors": "課文 ：曾世杰 學習單：陳淑麗",
    "strategy_name": "閱讀策略-跳過卡關，瀏覽全文",
    "spotlight_raw_text": "閱讀聚光燈\n閱讀策略——\n跳過卡關，瀏覽全文\n你剛剛讀過全文，你發現了嗎，第一段出現了許多不容易懂的專有名詞，這時「跳過卡關」的策略就派上用場了——你不必細究，略讀就好，只要繼續往下讀，文章經常比你想像的更容易懂哦。來練習看看。\n\n679451079500〈雨林裡的奇蹟藥物〉\n（段1）亞馬遜雨林的原住民，會用藤蔓中提煉出的「箭毒」製作毒箭。箭毒屬神經肌肉阻斷劑，拮抗乙醯膽鹼受體，它會阻斷神經肌肉傳導，中毒箭的動物會全身肌肉鬆弛，最後因呼吸衰竭而死。如今，現代醫院的外科醫師在手術中，卻把箭毒當作救命的藥物來使用，許多能治療白血病與其他癌症的強效藥物，也同樣來自雨林的植物。這讓科學家在世界各地的雨林中探索，尋找新的「奇蹟」藥物。\n\nStep 0：30秒快速瀏覽（先抓方向）\n1.任務：只抓「第一段大概在講什麼？」（約10–15字）\n→我猜這段在講：  藤蔓中的箭毒可以治病                        \nStep 1：標示卡關點（本課的粗體明示＋原因判斷）\n1.粗體的地方讀起來不容易，你覺得主要原因是什麼？（單選）\n①醫學專有名詞密集，句子又長\n□②事件跳太快，我很難把前後接起來\nStep 2：忽略卡關點再讀一次（不中斷）\n1.再讀一次第一段：看到粗體就先快速讀過，不要細究，直接往下讀。\n2.",
    "story_text": "亞馬遜雨林的原住民，會用藤蔓中提煉出的「箭毒」製作毒箭。箭毒屬神經肌肉阻斷劑，拮抗乙醯膽鹼受體，它會阻斷神經肌肉傳導，中毒箭的動物會全身肌肉鬆弛，最後因呼吸衰竭而死。如今，現代醫院的外科醫師在手術中，卻把箭毒當作救命的藥物來使用，另外還有許多能治療各種癌症的強效藥物，也同樣來自雨林的植物。這讓科學家在世界各地的雨林中探索，尋找新的「奇蹟」藥物。 1987年，一位植物學家在馬來西亞雨林採集到一種樹木樣本。美國 國家癌症研究院的研究結果顯示：從這棵樹提取的萃取物，能強力保護人體細胞免受愛滋病病毒的侵害！ 科學家立刻趕往馬來西亞，想採集更多樹木樣本。然而不幸的是，在那片孕育出可以對抗愛滋病藥物的雨林，早已被清除，改作農地，他們只找到一根根枯死的樹樁。 這些樹樁提醒人們：珍貴的治療方法或藥物，真的可能在一夜間消失。每一年，被破壞的雨林面積相當於四分之三個臺灣那麼大。全球雨林持續遭到破壞，已導致成千上萬種動植物滅絕。",
    "spotlight_answers": [],
    "paragraphs": [
      "亞馬遜雨林的原住民，會用藤蔓中提煉出的「箭毒」製作毒箭。箭毒屬神經肌肉阻斷劑，拮抗乙醯膽鹼受體，它會阻斷神經肌肉傳導，中毒箭的動物會全身肌肉鬆弛，最後因呼吸衰竭而死。如今，現代醫院的外科醫師在手術中，卻把箭毒當作救命的藥物來使用，另外還有許多能治療各種癌症的強效藥物，也同樣來自雨林的植物。這讓科學家在世界各地的雨林中探索，尋找新的「奇蹟」藥物。 1987年，一位植物學家在馬來西亞雨林採集到一種樹木樣本。美國 國家癌症研究院的研究結果顯示：從這棵樹提取的萃取物，能強力保護人體細胞免受愛滋病病毒的侵害！ 科學家立刻趕往馬來西亞，想採集更多樹木樣本。然而不幸的是，在那片孕育出可以對抗愛滋病藥物的雨林，早已被清除，改作農地，他們只找到一根根枯死的樹樁。 這些樹樁提醒人們：珍貴的治療方法或藥物，真的可能在一夜間消失。每一年，被破壞的雨林面積相當於四分之三個臺灣那麼大。全球雨林持續遭到破壞，已導致成千上萬種動植物滅絕。"
    ],
