    "title": "未來的農夫",
    "genre": "說明文",
    "authors": "課文 ：曾世杰 學習單：陳淑麗",
    "strategy_name": "閱讀策略-跳過卡關，瀏覽全文",
    "spotlight_raw_text": "閱讀聚光燈\n閱讀策略──\n跳過卡關，瀏覽全文\n上一課我們已經學過：文章出現很多專有名詞，可以先跳過，先往下讀。\n〈未來農夫〉這一課也有不少專有名詞，請你再用上一課學到學到的策略閱讀。這一課我們用第4段和第5段做練習。\n-3683016065500\n〈未來農夫〉\n（段4）帶她的大仁哥，是工程師兼「科技農夫」，一邊走，一邊指著牆邊的控制箱與感測器解說：「這裡的水耕蔬菜不是用土種出來的，而是用營養液。輸送營養液的管路都有流量、溫度、酸鹼值、肥料濃度跟電導度的監測；溫度、濕度、空氣流動，甚至二氧化碳濃度，也都會一起控制。」他說，這種全環境控制的系統，才能把溫度與濕度穩穩地維持在最適合蔬菜生長的範圍。以萵苣類作物為例，溫度常被控制在約18–25°C、濕度65–75%；營養液的酸鹼值大約維持在5.5–6.5；為了加速光合作用，室內二氧化碳濃度也控制在1000–1500ppm之間。\n（段5）「你的任務之一，」他把平板遞給她，「就是每天巡檢數據：看哪一區的酸鹼值或肥料配方偏離了、哪一層的溫溼度曲線不正常。問題能自己排除就儘快排除，必要時回報，讓值班同事去校正或調整配方。」宇晴盯著平板看，螢幕上跳動的數字像心電圖，她緊張的心情，忽然有了一種奇妙的踏實感：原來讀圖表、看趨勢、抓異常也是在種菜。\n\nStep0：30秒快速瀏覽（先抓方向）\n1.任務：只抓「第4～5段大概在講什麼？」（約10–15字）\n→我猜第4～5段在講：  用高科技方式管理種菜             \nStep 1：標示卡點＋先往下讀\n1.請在框框中把你覺得讀不懂、會卡住的地方圈起來或畫線。\n2.再讀一次第4～5段：看到你圈的地方先略過，直接往下讀，不要停。\n3.",
    "story_text": "「你畢業後要做什麼？」上了高職二年級以後，同學們常互相追問這個問題。宇晴的答案始終如一：「我要當農夫。」 高三上學期，宇晴被安排到桃園一座垂直農場實習，這座農場種植總面積達12,000平方公尺，相當於28.6個籃球場。領了識別證，推開門，廠房沒有泥土味，宇晴聞到的是淡淡的消毒酒精味。她換上髮網、口罩、鞋套，外加一件防塵外套；走進廠區前，還得穿過一段用強風吹除外套灰塵的廊道，強風把衣角吹得啪啪作響，像在提醒：這裡不是觀光溫室，這裡是「高科技無塵室」。 門一推開，宇晴愣住了：「這是農場嗎？」長長的走道兩側，是一層又一層的栽培架往上堆疊，LED燈板在頭頂亮成一片，帶著紫粉色的冷冽感，讓整個空間像科幻片的太空站。每一層水耕槽裡，舒展著鬱鬱蔥蔥的嫩綠葉片，看起來生機勃勃，而且整齊得彷彿用尺量過一樣。 帶她的大仁哥，是工程師兼「科技農夫」，一邊走，一邊指著牆邊的控制箱與感測器解說：「這裡的水耕蔬菜不是用土種出來的，而是用營養液。輸送營養液的管路都有流量、溫度、酸鹼值、肥料濃度跟電導度的監測；溫度、濕度、空氣流動，甚至二氧化碳濃度，也都會一起控制。」他說，這種全環境控制的系統，才能把溫度與濕度穩穩地維持在最適合蔬菜生長的範圍。以萵苣類作物為例，溫度常被控制在約18–25°C、濕度65–75%；營養液的酸鹼值大約維持在5.5–6.5；為了加速光合作用，室內二氧化碳濃度也控制在1000–1500ppm之間。 「你的任務之一，」他把平板遞給她，「就是每天巡檢數據：看哪一區的酸鹼值或肥料配方偏離了、哪一層的溫溼度曲線不正常。問題能自己排除就儘快排除，必要時回報，讓值班同事去校󠇡正或調整配方。」宇晴盯著平板看，螢幕上跳動的數字像心電圖，她緊張的心情，忽然有了一種奇妙的踏實感：原來讀圖表、看趨勢、抓異常也是在種菜。 「可是這樣的垂直農場所費不貲，公司會賺錢嗎？」宇晴皺起眉頭，一臉狐疑。大仁哥笑著說：「好問題。一開始的投資真的很大，但我們不用煩惱雜草、蟲害、土壤病菌、雨災、日照、溫度這些問題。而且，蔬菜長得比在田園裡快，例如，小白菜30到35天就可以收成，在菜園種的至少要45到50天。」他繼續說：「此外，我們的菜不但沒有農藥，而且特別乾淨漂亮，你不會在晚餐的炒青菜裡看到令人作嘔的『加菜』。」他做著鬼臉，一邊橫著食指一伸一縮，模擬那個「加菜」。他最後下結論：「同樣是理髮，家庭理髮和髮廊設計師的價錢當然會有天壤之別囉。」 在回家的公車上，宇晴突然想起，媽媽小時候要幫祖母在菜園裡種菜，用鋤頭、鐮刀、畚箕等農具徒手施作，還要收集大小便當肥料……。宇晴瞇著眼，鼻子皺了起來，雞皮疙瘩掉了一地。 但那是以前的生活。重要的是，宇晴今天最重要的收穫是——未來的農夫，不再是戴斗笠拿鋤頭的形象，工作更像是工程師！",
    "spotlight_answers": [],
