    "fixture_found": false,
    "title": "當全世界都在笑你，你可以怎麼做？",
    "genre": "說明文",
    "authors": "課文 ：曾世杰 學習單：陳淑麗",
    "strategy_name": "摘要策略-問題解決結構找重點",
    "spotlight_raw_text": "閱讀聚光燈\n摘要策略——\n問題-解決結構找重點\n你以前學過用「問題—解決—結果」抓文章重點。這篇文章也有相同結構，只是換了比較貼近生活的名稱：\n困擾=問題；策略=解決；改變=結果\n閱讀時，只要掌握這個結構，就可以快速抓到文章的重點，並進一步推論出主旨或作者意圖喔。\n請你先試著連連看，把左邊「元素」和右邊「關鍵概念」連起來。\n\n元素\n\n關鍵概念或提示\n(1)\n困擾\n● 　　　 　　 　\n9041113450400●         ●\n作者建議你怎麼做？\n（可能出現第一、第二、最後等關鍵詞）\n(2)\n策略\n    　　  　          ●           ●\n　　　　     　\n遇到什麼困擾？（常在開頭段）\n(3)\n改變\n        　　●         ●\n　     　　　　\n做了之後會出現什麼改變？\n（常在最後段）\n\n一、找重點：困擾→策略→改變\n表：本課的結構：困擾→策略→改變\n元素\n根據課文內容，請填寫答案（答案合理即可）\n❶困擾\n❶作者說生活中，你可能會遇到什麼困擾？\n   網路霸凌                   \n❷策略\n(段6~8）\n❷遇到這個困擾，你可以怎麼做？（根據課文寫下具體的作法）\n1. 不要一個人扛，可以向信任的大人求助                         \n2.冷處理，不要急著以牙還牙，截圖留下證據                      \n3.照顧好自己的情緒，找到方法紓壓，需要時找專業的人陪伴                                            \n❸改變\n❸做了之後，會出現什麼改變？\n   只要願意好好活著、慢慢走下去，終有撥雲見日的一天                       \n\n二、推論主旨與作者意圖\n  1.根據你找到的重點，這篇文章的主旨是什麼（本文在說什麼）？（單選）\n□①安海瑟薇得獎後被討厭，所以名人都很辛苦。\n②網路霸凌會擴散放大並傷人，作者教你自保並走向復原。\n□③遇到霸凌時，只要退出群組就能立刻解決問題。\n□④網路世界太可怕，所以最好完全不上網。\n  2.本文作者意圖（作者想影響你什麼？）（4選2）\n①讓你知道「求助不是示弱」，遇到霸凌不要獨自硬撐。\n□②鼓勵你立刻回嗆到底，才不會被看扁。\n③提醒你先停損、冷處理並蒐證，避免衝突升溫。\n□④要你學會模仿明星受訪的表情管理，避免被剪短片。\n※區分主旨和作者意圖（很重要）\n主旨：這篇「在說什麼重點」。\n意圖：作者「希望你怎麼想、怎麼做」。\n\n◎",
    "story_text": "想像一下：你只是照自己的步調做事，卻在群組裡被起綽號、被截圖轉傳；有人故意已讀不回，有人在背後冷嘲熱諷，說「大家都說你是討厭鬼」。網路霸凌最傷人的，往往不是一句話，而是那句話被一傳十、十傳百，再被添油加醋，弄到你開始自我懷疑：是不是我真的哪裡不對？ 美國演員安海瑟薇（Anne Hathaway）就曾在這樣的漩渦裡，成了眾矢之的。2013年她以《悲慘世界》拿下奧斯卡後，網路上卻冒出「討厭安海瑟薇」的風潮，成千上萬的酸民跟風起鬨，用各種標籤嘲弄她。很多攻擊並不是就事論事，她認真的態度被罵「做作」，太客氣被罵「假掰」，連受訪時笑一下、停頓一下，都可能被剪成短片嘲笑。她後來形容，那些惡意像把她心裡最脆弱的地方放大播放，彷彿全世界都在指指點點。 雪上加霜的是，有些負面聲量你根本躲不掉。她曾提到，自己只是上網搜尋資料，卻突然看到「為什麼全世界都討厭安海瑟薇」的標題，心裡一沉，像被當眾羞辱一樣難堪。那段時間她為角色減重、剪髮，本就身心俱疲；偏偏嘲笑又連續發酵，讓人不堪其擾。你可以想像那種狀態：每天醒來都怕手機一亮又有新嘲諷，整個人如坐針氈，連呼吸都不自在。 她後來坦白，那些年她有幾次得獎，但她總猶豫著要不要站上舞台領獎。在那種場合，她必須強顏歡笑，卻又擔心被說成「又在裝了」。於是她進退維谷：笑，被說假掰；不笑，被說冷漠。怎麼做都錯，這讓她心灰意冷，想把自己躲起來。 網路上的風向，還帶來真實的後果。她說，曾有一陣子影視公司擔心她的「有毒的」形象，因此不敢找她合作——這真是無妄之災。還好，有位導演在她低潮時雪中送炭，請她演出《星際效應》，她才能慢慢重整旗鼓。她告訴自己：羞辱很可怕，但我決定不讓它困住，我要把自我價值從留言區找回來，因此開始受訪談論自己被霸凌的經驗。她特別同理有相似經驗的青少年：「這不是無病呻吟，你的痛感是真實的。」 根據她的經驗，如果你正在經歷網路或關係霸凌，第一步是「不要一個人扛」，求助不是示弱，逞強硬撐只會使自己孤立無援。這不是玻璃心，是你在被傷害。把你的委屈說給信任的大人聽——導師、家長、輔導老師都可以。你願意開口，就是在黑暗裡點一盞燈，有人能陪你一起解決問題，終有撥雲見日的一天。 第二是「冷處理，不要急著以牙還牙」。瘋狗在咆哮撕咬時，你愈用棒子打，牠咬得愈凶。你在網路上的反擊往往得不償失，還可能被對方抓到把柄再反咬一口。你可以簡短表明立場後離開霸凌現場，也可以藉著調整隱私、封鎖、檢舉，讓對方看不到你。先停損，才不必讓自己陷入無休止的口水戰；記得把留言、私訊、群組對話截圖，記下時間與帳號，後續處理時才能有憑有據。 最後，請把照顧自己的情緒當成大事。霸凌的語言雖然可能很刺耳，但那不能定義你是誰；真正該被停止的是傷害，而不是你的存在。你可以用運動、寫日記、和支持你的朋友聊天等方式來紓壓，暫時遠離讓你焦慮的念頭；如果你開始失眠、害怕上學、一直想哭或情緒崩潰，就更要尋求協助，讓專業的人陪你走一段。 連好萊塢的大明星都會遭到網路霸凌，可見這問題無所不在。如果你正在被霸凌，安海瑟薇的故事要告訴你，我們不必為迎合網路的意見而活著，只要你自己願意好好活著、慢慢走下去，這段可怕的記憶終會變小、消失，你終有撥雲見日的一天。",
    "spotlight_answers": [],
