    "strategy_name": "解題策略-帶著問題讀",
    "spotlight_raw_text": "閱讀聚光燈\n解題策略—帶著問題讀378206035533\nLevel 7・說明文00\nLevel 7・說明文3937000478763\n-24765-12827000第27課  帶著「血拼清單」閱讀  \n課文  ：曾世杰 \n學習單：陳淑麗\n\nㄧ\n\n二\n三\n\n四\n\n五\n六\n\n七\n\n八\n\n上街買東西，英文叫shopping，它戲謔的譯名叫「血拼」。有「萬頭鑽動，一群人流『血』流汗，『拼』死搶貨」的意思，譯名和原文的發音相近、意象鮮明。但這篇課文重點其實不是血拼，而是藉著血拼策略，來講一個重要的閱讀策略——帶著問題讀。\n血拼有兩種，一種稱為「逛街」，另一種稱為「採買」。\n如果你上街的目的是殺時間，並沒有什麼特別想買的東西。你走到哪裡，看到哪裡，這邊翻一翻換季服飾，那邊看一看手機配件。逛一個下午，也許滿載而歸，也許一樣都沒買，這就是「逛街」了。\n「採買」就不同了，它有清楚的目的性。上街前你會先列一張血拼清單，拿筆寫下每一項需要的東西，例如，要去超市買雞蛋、牛奶、紅豆麵包，再去郵局買郵票。採買回來，你清清楚楚知道，清單上的項目是否買齊了。\n閱讀也有兩種，一種稱為「篇章瀏覽」，另一種稱為「帶著問題讀」。\n大多數人早上打開手機，點進常用的社群媒體時，只是在「逛街」，這裡讀一點偶像新聞，那裡看一下職棒賽況，這樣的閱讀沒有特定的目的，只是走馬看花的「篇章瀏覽」。\n但，如果你是為了週末要去平溪放天燈而上網的，你上網前，心中就會有清楚的待答問題，天氣如何？怎麼搭車？幾點要到？附近有什麼著名小吃？……這樣的閱讀就是「帶著問題讀」。\n對國中生特別重要的是，「帶著問題讀」可以幫助你在國文",
