    "strategy_name": "閱讀策略-跳過卡關，瀏覽全文",
    "spotlight_raw_text": "閱讀聚光燈\n閱讀策略——\n跳過卡關，瀏覽全文\n我們再用〈最後一隻旅人鴿〉做練習。這一次仍然請你快速閱讀一遍，標出讀不懂或讀不順的地方，再練習一次「跳過卡關、瀏覽全文」策略。",
    "story_text": "早期的美國拓荒者曾目睹一幕驚人的景象——成群結隊、鋪天蓋地的旅人鴿。牠們體態修長，羽色灰藍，身長約41公分。旅人鴿屬鳩形目，具群聚性與高度社會性；採集性覓食，有典型長距遷徙行為，並在密集繁殖殖群中同步築巢。牠們遷徙路線從加拿大一路向南，穿越俄亥俄州、肯塔基州，到達阿肯色州與德州。科學家曾估計：牠們的數量不可勝數，單一群旅人鴿就可能超過十億隻，飛過天空往往持續好幾個小時，讓日光失色。 然而，到了1878年，旅人鴿的群體開始減少。原因不明，但有兩幾種主流的說法：一是大自然的疾病；另一是人類的開墾，破壞了棲地，並開始了大量獵殺。旅人鴿性情出奇溫馴，常棲息在樹的低枝上，獵人或為了食物，或為了娛樂，很容易就能把牠們一隻隻打下來。 最後一隻野生的旅人鴿，在1904年被射殺。當時有些旅人鴿已被送進動物園，但那時人們對如何繁殖復育野生動物所知甚少。世界上最後一隻旅人鴿一直活在辛辛那提動物園，直到1914年老死。一整個物種，就此從地球上消失。",
    "spotlight_answers": [],
