    "title": "《構樹：南島祖先「出台灣說」的植物證據》",
    "genre": "說明文",
    "authors": "課文 ：曾世杰 學習單：陳淑麗",
    "strategy_name": "解決問題-科學探究法",
    "spotlight_raw_text": "閱讀聚光燈\n解決問題—科學探究法\n有些說明文，就像一則「科學偵探故事」。作者會提出他關切的問題，但不會一開始就給你答案，而是帶你走過一段推理歷程，最後得到結論：\n❶先提出一個研究問題（這問題太重要或太有趣了，是怎麼回事？）\n❷再提出一個假設／假說（我推測答案可能是..）\n❸接著收集證據驗證假說（怎麼查？查到什麼？結果符不符合推測？）\n❹最後得到結論（證據有沒有支持❷的假設？）\n讀這類文章時，重點是看懂：「證據是否能支持（或推翻）假設。」\n「構樹」這篇文章，正是一段帶領讀者進行科學推理的過程。作者以「南島祖先可能從臺灣出發（出臺灣說）」為假說，透過植物──構樹的 DNA證據，一步步檢驗這個想法是否站得住腳。\n我們要練習用底下的4個步驟，看懂一個科學假說是如何被驗證的。\n【❶找問題】【❷找假說】【❸找驗證】【❹下結論】\n\n表：本課的科學討論四步驟：問題→假說→驗證→結論\n步驟\n關鍵判斷或提示\n根據判斷，勾選最符合的一項\n❶\n問題\n文章主要在追問哪一個問題？\n①南島語族如果有共同的源頭，這個「共同的故鄉」可能在哪裡？\n□②南島語族分布在不同島嶼，它們在地球上分布的範圍有多廣？\n❷\n假說\n推測性的答案、暫時性的答案\n(關鍵詞：可能、推論、會不會)\n□①南島語族可能最早是從菲律賓出發的\n②南島語族可能最早是從臺灣出發的\n□③南島語族可能最早是從印尼出發的\n❸\n驗證\n怎麼查？查到什麼？結果符不符合推測？\nA.方法：怎麼查？\n①研究者從多國蒐集早期的構樹文物，抽取DNA來追蹤構樹的「家族旅程」\nB.理由：為何這樣查？\n□①使用早期構樹文物，因為保存時間較久，外觀與形態更完整\n②不用今日各島活著的構樹，因為它們可能是近代才被帶去，會造成誤判\nC.預測：若假說正確，應該看到什麼？\n①若構樹由臺灣擴散，臺灣的基因型態的多樣性應該最高\n□②若構樹由臺灣擴散，臺灣的基因型態的多樣性應該最低\nD.結果：實際上，科學家查到什麼？\n①臺灣的構樹基因多樣性最高；菲印較低；太平洋群島更低\n□②臺灣的構樹基因多樣性最低；菲印較高；太平洋群島更高\nE.預測和結果「對得起來」嗎？\n□①對不起來：結果與預測方向相反\n②對得起來：結果符合「出臺灣說」的預測\n❹\n結論\n收集的證據是否支持「出臺灣說」？\n①構樹 DNA多樣性的研究結果支持「出臺灣說」\n□②構樹 DNA多樣性的研究結果不支持「出臺灣說」\n\n◎",
    "story_text": "南島語族分布在太平洋與印度洋的眾多島嶼，活動範圍廣闊無垠，如地圖中由虛線框起的區域：從最北的台灣到最南的紐西蘭，相距約9000公里；從最東的復活節島到最西的馬達加斯加，更達18,000公里。島嶼雖然天各一方，他們的語言卻保留不少相近詞彙，文化裡也常見類似的航海技術、織布方式與祭儀結構。於是科學家推論：南島語族可能來自共同源頭，兩三千年前憑藉精湛的航海能力展開逐島移民，經過綿延千年的遷徙後，才形成今日星羅棋布的南島世界。 圖1 南島語族分布在太平洋與印度洋的眾多島嶼 如果真有共同的源頭，那麼這個「共同的故鄉」在哪裡？語言學、考古學與人類學長年合作，提出多種假說，其中最具代表性的是「出臺灣說」——南島語族可能最早是從臺灣出發的。過去支持這個假說的證據多來自語言與文化的相似性，但近年又出現一項意 想不到的「植物證據」：線索來自臺灣路邊隨處可見的構樹。 構樹葉片像手掌，果實橘紅，樹皮纖維可拉成長絲。在許多臺灣原住民族文化中，構樹樹皮布是重要的衣物與儀式材料，木材可製作工具，枝葉也可能在祭典中扮演要角。更耐人尋味的是，人類學者發現：不論走到哪個南島語族社群，幾乎都能看到構樹的身影——有人做樹皮布，有人用來綁繩、包覆器具，而且構樹製品在祭儀中往往舉足輕重。這讓研究者追問：若南島語族真是從臺灣出發，各島上的構樹會不會也是祖先一路帶出去的？ 為了追查這個可能性，人類學家找來植物學家合作，展開一項像「科學偵探」的研究：從多國蒐集南島語族早期的構樹文物，如博物館裡數百年前的樹皮布、繩索與工藝品纖維，抽取DNA來追蹤構樹的「家族旅程」。他們特別使用古老文物，是因為今日各島活著的構樹可能是近代才隨船隻或飛機被帶去的，若直接拿來當證據，可能造成誤判。 研究背後的推理很簡單：若構樹由臺灣向外擴散，臺灣的「基因型態」種類應該最多。第一批祖先帶著構樹從臺灣航向A島時，只能帶出少數的基因型態；在A島生活一段時間後，又有人移居到B島，所帶走的構樹基因型態更少。換句話說，基因多樣性會呈現「源頭最多、往外逐層遞減」的現象。這就像笑話從A傳給B，再傳給C、D：A的笑話版本一定最完整，傳到Ｄ時，往往就掛一漏萬、支離破碎了。生物遷移時，基因多樣性也會出現類似現象——源頭基因多樣性最高，越末端基因多樣性就會越單純。 植物學家分析臺灣、東南亞與多個太平洋島嶼的六百多件構樹文物樣本後，結果一目了然：臺灣的構樹基因多樣性最高；菲律賓、印尼較低；太平洋群島更低。這種由「多」到「少」的分布，正好與「從臺灣出發、向南向東遷徙」的路徑不謀而合。更重要的是，它也和語言學、考古學的結論彼此呼應：語言學家指出最接近「祖語」的語言群集中在臺灣；考古學也發現某些典型陶器與農作技術最早出現在臺灣，之後才向外擴散。如今構樹DNA加入拼圖，讓「出臺灣說」得到更充足的科學支撐。 原來，我們路邊司空見慣的構樹，不只是一棵普通植物。它可能曾陪著航海者跨越海洋，也在不知不覺間記錄了南島語族的遷移故事。構樹的DNA像一封來自千年前的訊息，提醒我們：臺灣，或許正是那場偉大航海故事的起點。",
    "spotlight_answers": [],
