    "title": "科學辦案：破解蝴蝶蘭的花期密碼",
    "genre": "說明文",
    "authors": "課文 ：曾世杰 學習單：陳淑麗",
    "strategy_name": "解決問題-科學探究法",
    "spotlight_raw_text": "閱讀聚光燈\n解決問題—科學探究法\n上一課《構樹》告訴我們：有些說明文像科學偵探故事。作者先提出「問題」，再提出「假設」，接著用證據「驗證假設」，最後下「結論」；閱讀時要看懂「證據是否能支持（或推翻）假設」。\n這課我們要學一樣的策略，用4個步驟把「解決科學問題的過程」整理清楚。你還記得這些步驟的關鍵概念或提示嗎？請連連看。\n\n步驟\n\n關鍵概念或提示\n❶\n找問題\n● 　　　 　　 　\n推測原因可能是…；或暫時性的答案\n可能出現「可能」、「推測」等關鍵詞。\n\n16383018986500●         ●\n\n❷\n找假說\n95972-23311900    　　  　          ●           ●\n　　　　     　\n文章主要想解決（或追問）什麼問題？ \n❸\n找驗證\n         　　●         ●\n　     　　　　\n證據最後支持哪個假說？\n❹\n下結論\n\n●         ●\n用什麼方法、看到什麼結果？結果符不符合推測？\n\n一、找問題→找假說→找驗證→下結論\n表：本課的科學解決四步驟：找問題→找假說→找驗證→下結論\n步驟\n根據課文內容，請勾選或填寫答案（答案合理即可）\n❶\n問題\n1.花期落差\n  蝴蝶蘭盛開在（ 3-4 ）月；市場需求卻在（1-2）月\n2.文章要解決什麼問題？\n   如何讓蝴蝶蘭提早開花，以配合市場需求？                   \n❷\n假說⭣\n❸\n驗證\n\n❷假說\n❸驗證\n\n影響因素可能是\n用什麼方法\n結果/\n是否支持假說？\n\n1.肥料\n1.施肥\n1.花更大更美，但沒提早開花  / □是  否 □部分支持\n\n2白晝長度\n2.用黑塑膠網遮光     \n2.遮光可催花但僅提早5–7天     \n / □是  □否 部分支持\n\n3.低溫    \n3.實驗組放冷氣房、對照組留原來花房\n3.實驗組一個多月後，抽出花梗       ；對照組則無      / 是  □否  □部分支持\n❹\n結論\n低溫，溫度26度以下，持續30-40天，就能成功催花             \n\n二、應用（把結論帶回現場：問題→解決→結果）\n前面我們用科學步驟找出「低溫能催花」。再來是把結論應用到現場。但農民遇到了新的問題，請根據課文寫出他們如何解決問題。\n1.問題：    花房面積大，冷氣電費成本太高        \n2.解決：\n①把平地蘭花送到高海拔蘭園降溫 \n②   在高海拔地方設置蘭園          \n③   用深層海水降溫         \n3.結果：用大自然降溫，降低電費負擔，也能順利催花。     \n◎",
    "story_text": "臺灣農業技術在世界上首屈一指，那是因為農業界在解決問題時，運用了「問題⭢假設⭢驗證⭢結論⭢應用」的科學步驟；蝴蝶蘭的花期調整，就是一個絕佳的例證。 臺灣消費者喜愛蝴蝶蘭，尤其在農曆新年，家家戶戶都喜歡擺幾盆花團錦簇、奼紫嫣紅的蘭花。但是，蝴蝶蘭盛開的月份是三、四月，花農要怎樣把開花的時機提早到一、二月，好配合農曆年的商機呢？ 要解決這個問題，花農必須先找到幾個可能催促開花的因素，以科學方法確認真正能催花的因素後，再想方設法降低成本，在農園實踐出來。 第一個被想到的因素是肥料。施用磷、鉀比重較高的肥料，是花農催花的常見手段。像校園常見的矮牽牛、日日春、長春花、非洲菫，高磷鉀肥可促進花芽的形成。但，農業專家在實驗後發現，施肥只能讓花朵更大更美，卻無法提早促成蝴蝶蘭開花。 另一個促成開花的可能因素是「白晝的長度」。以火龍果為例，專家發現白晝長度超過12小時40分後，火龍果就會開花。現在你二月去屏東，發現火龍果園夜裡燈火通明，那可不是農民連夜趕工，也不是想讓植物光合作用，而是想在日落後用電燈連照4小時，讓火龍果錯以為「白天變長」了，它們就會努力伸出花芽來。相反地，蝴蝶蘭是白晝變短的時候開花，於是農業專家用黑塑膠網遮光，讓花錯以為「白天變短」了，實驗結果顯示，這招的確能催花，但只能提早5到7天，對農民沒有太大幫助。 因為蝴蝶蘭都是在秋末時開始萌生花芽的，另一個可能的促花因素會不會是「低溫」呢？ 許多在小型花房進行的實驗開始了，這些實驗的作法大致如下：先用無菌試管培育了幾百株完全相同的蘭苗，直到夏天到來，蘭苗長大準備開花時，實驗開始了——蘭花被分成實驗組和對照組，實驗組被移到有冷氣的房間，對照組仍然留在原來的花房。結果，實驗組在冷房過了一個多月，紛紛抽出花梗，準備大放異彩時，對照組還沒有動靜呢。結論是，白天的溫度若能降到26度以下，持續30到40天，就可以成功催花。 新的問題來了，實驗室的密閉花房空間小，開冷氣降溫，冷氣和電費都有政府補助，但花農的花房空間是開放的，即使願意投資把花房密封、裝設冷氣，動輒上萬平方公尺的花房，冷氣、電費的成本，會讓花農入不敷出。 匠心獨具的花農，總是能想出巧妙的因應方法。臺南的一個蘭園，在夏天把平地的蝴蝶蘭送到50分鐘遠、海拔1,100公尺高的另一個蘭園。因為海拔每上升100公尺，氣溫就會降0.6度，平地32度時，這個蘭園只有25度。搬家後一個多月，每株蘭花整整齊齊的冒出花梗，花朵完全盛開時，正好趕上過年的旺季。台糖公司甚至就直接在海拔700公尺埔里設置了蘭園，這樣還省下了上山下山的運輸費用。還有一個別出心裁的嘗試，花蓮有一個蘭園設在太平洋畔，園主抽取只有9～11℃的冰冷深層海水，這個冷源經機器轉化後送出冷風，可在暑氣蒸人的夏天使花房的溫度降了10度。而這麼做比傳統冷氣的催花方式節省了將近70%的電費。 農業專家提出肥料、光照、低溫等不同假設，再以實驗一一驗證，找到催花因素後，再用種種巧思把這個結論在現場實踐，一盆盆準時含苞待放的蝴蝶蘭，臺灣被稱為「蝴蝶蘭王國」，一點也不意外，你看出其中的道理了嗎？",
    "spotlight_answers": [],
