    "title": "我能不能選擇告別方式?",
    "genre": "說明文",
    "authors": "課文 ：曾世杰 學習單：陳淑麗",
    "strategy_name": "比較多元觀點",
    "spotlight_raw_text": "閱讀聚光燈\n比較多元觀點\n本文主要談一個人生重要的議題：能不能選擇告別方式。這種議題文章，就像一場「辯論」，你會看見多元的觀點的討論。讀這類文章，重點是：「找到個別的觀點，再比較不同觀點的差異在哪裡？」最後再推論文章想要說什麼（主旨）。\n\n一、確定議題\n1.這篇文章在談「哪個議題／爭議」\n   對安樂死或協助自殺的看法                                         \n二、找觀點\n    議題文章是在「說服」讀者：每一方會先表明立場與主張，再用理由說服。接著請你整理這個議題有哪些立場？每個立場的主張和理由是什麼？\n立場\n觀點要素\n請根據課文內容填答或勾選(單選)\n贊成   \n主張\n在法律監督下開放讓病人選擇如何結束己的生命               \n\n主要\n理由\n①病人意願清楚且堅定時，應尊重其自主與尊嚴，讓他有選擇權。\n□②病人意願清楚且堅定時，應先把照護資源做足再討論\n\n條件\n①應有多位醫師評估、冷靜期、完整紀錄等程序，避免草率決定。\n□②先把疼痛控制與長照資源做足，再談是否開放。\n反對    \n主張\n不開放安樂死／協助自殺\n\n主要\n理由\n□①一旦開放且程序夠嚴格，就能避免界線擴大與被迫選擇。\n②一旦開放，適用範圍可能擴大；弱勢病患也可能承受壓力而被迫選擇。\n保留   \n主張\n先落實臨終照顧：                                         \n讓疼痛控制、心理支持、長照與照顧者喘息服務更普及         \n\n主要\n理由\n①很多「想走」可能只是太痛太孤單，資源到位選項就不會只有極端選項。\n□②很多「想走」可能因程序不夠嚴格；所以應先補強審查監督，再討論是否開放。\n\n三、比較觀點差異（用「價值／風險」兩個角度）\n我們先用「主張＋理由」掌握每一方在說什麼；再追問理由在強調什麼──重視的價值與擔心的風險。用這兩個角度看，就能清楚比較觀點差異。\n立場\n重視的價值（單選）\n擔心的風險（單選）\n贊成\n①自主與尊嚴　\n□②保護弱勢、避免被迫\n①草率決定、意願不清　\n□②界線擴大、範圍越放越寬\n反對\n□①自主與尊嚴　\n②保護弱勢、避免被迫\n□①草率決定、意願不清　\n②弱勢受壓、被迫選擇死亡\n保留\n①先把照護做到位　□②盡快立法開放選擇\n①照護不足，逼人只剩極端選項\n□②界線擴大，導致濫用難以收回\n＊歸納觀點差異：\n贊成者重視    自主與尊嚴     ；反對者最擔心   弱勢受壓、被迫選擇   ；保留者強調先    把照護做到位     。\n\n四、推論主旨（從「觀點差異」推論整篇重點）\n根據你整理的觀點差異（自主尊嚴／弱勢被迫／先補照護），下列哪一項最能概括本文主旨？（單選）\n □①說明末期病人的自主選擇，並提醒制度應降低風險、補足照護資源\n ②透過多元觀點對照，凸顯此議題在權利、風險與照護之間的兩難\n\n◎",
    "story_text": "你有沒有想過：如果一個人每天都痛到睡不著，連呼吸都像被刀割，他還能怎麼活下去？傅達仁，叱吒風雲的籃球國手、家喻戶曉的體育主播，曾主播七屆奧運。2016年確診胰臟癌後，他經歷多次手術、化療，高大帥氣的他變得瘦骨嶙峋、形容枯槁。劇痛像刀子般持續的戳刺割扯，讓他白天痛苦難當、夜裡無法成眠，只能靠強力止痛藥，度過毫無品質的每一天。他想要了結這沒有盡頭的折磨，但沒有合法的管道可以達成。2016年底，他寫信給蔡總統，希望能推動安樂死立法並願做首例；總統府回函表示重視，也請相關單位處理。但這個議題爭議性高，各界難有共識，他一等再等，等不下去了。2018年他在家人陪伴下前往瑞士，6月7日依當地制度以「協助自殺」方式離世。 傅達仁的案例，把沉重的問題推到大家眼前：當生命只剩疼痛，誰可以幫病人做一個決定，幫助他結束自己的生命？ 「安樂死/協助自殺」大致可以分成三種。第一種是「撤除維生醫療」，例如對病情已不可逆轉的病人不再插管、移除呼吸器、停止營養灌食等無效醫療，讓生命自然走到終點。第二種是一般說的「安樂死」，由他人主動用藥，直接讓無法自我決定的病人死亡。第三種則是「協助自殺」，就是傅達仁 瑞士行的目的，由病人在意識清楚、意願堅定時，經過嚴謹的評估與確認，在醫療人員的協助下，自己按下注射藥劑的開關，完成最後一步。臺灣目前已有安寧緩和醫療與《病人自主權利法》，保障第一種幫助人結束生命的方式，政府鼓勵民眾預先做好最後關頭的醫療決定，這讓醫療人員可以依臨終病人的意願，停止無效醫療，但第二、第三種在臺灣仍不合法。 臺灣對安樂死或協助自殺的看法，有三種主流的聲音。支持者最重視「自主」與「尊嚴」，認為末期病人若反覆表達意願，社會應設計嚴格程序，讓病人在法律監督下做選擇。有人主張要有多位醫師評估、冷靜期與完整紀錄，避免草率決定。 反對者則擔心，一旦開放，適用的範圍會不會越來越大？更重要的是，弱勢病患可能承受看不見的壓力——他們會擔心醫療費用及照護人力會拖垮家人。病人難免會想「如果我不選擇死亡，我就會給家人帶來麻煩」，壓力不言而喻。也有人從宗教與倫理出發，認為只有上帝或老天才能決定生死，自己、家人及醫師都不該決定病人是否可以一死了之。 還有人採取保留態度，主張先落實臨終照顧：把疼痛控制、心理支持、長照與照顧者喘息服務做得更普及。因為很多「想走」可能只是「太痛、太孤單」。如果資源到位，如果社會能設身處地理解病人與家屬的需求，末期的病人就不會只剩非黑即白的極端選項。 這道難解的問題同時牽涉人權、信仰、風險與制度設計。支持者想把生命的抉擇權交給個人；反對者怕界線一開就覆水難收；保留者提醒照護缺口迫在眉睫。再加上臺灣文化常避談死亡，許多家庭到最後才匆忙決定，「自願」與「被迫」更難分辨。若要開放，如何設計審查、申訴與監督？若不開放，又如何確保病人不被疼痛吞沒？當眾說紛紜、莫衷一是時，這議題就只能原地踏步了。 傅達仁的故事像一面鏡子：它照見痛苦，也照見我們對自由、家庭與社會責任的拉扯。如果有一天，躺在病床上的是你，或站在病床邊的人是你——你希望自己被允許做什麼選擇呢？",
    "spotlight_answers": [],
