    "title": "石虎保育：遷移與否的兩難",
    "genre": "說明文",
    "authors": "課文 ：曾世杰 學習單：陳淑麗",
    "strategy_name": "比較多元觀點",
    "spotlight_raw_text": "閱讀聚光燈\n比較多元觀點\n上篇文章我們已經學過「比較多元觀點」的閱讀策略。這篇文章，我們要再學一次。讀議題類文章，重點是：「找到個別的觀點，再比較不同觀點的差異或相同在哪裡？」最後再推論文章想要說什麼（主旨）。\n一、確定議題\n  這篇文章在談「哪個議題／爭議」（提示：可能出現「爭議」、「該不該」、「是否」等關鍵詞）\n   是否應把石虎「遷移」到較安全的地方                                 \n二、找觀點\n  議題文章像在辯論：每一方都有自己的立場或觀點，並提出有說服力的理由與作法。底下請你整理對這個議題的不同立場／觀點，每個觀點的核心想法與理由、作法是什麼？\n立場\n觀點要素\n請根據課文內容填答或勾選(單選)\n反對   \n遷移   \n主張\n  遷移可能造成新風險，先讓原棲地變安全             \n\n理由\n□①遷移花費高、而且把動物搬走治標不治本，無法改善人與自然的衝突。\n②遷移到新地區，可能會有新的風險（食物不足、地形植被不合、其他掠食者/競爭者、疾病、人為風險）。\n\n主要作法\n①讓原地變得安全：建廊道、車輛減速、犬隻管理、補償與雞舍防護等。\n□②加強石虎野放前的訓練與追蹤監測，讓牠更會避開危險、提高存活率。\n支持   \n遷移    \n主張\n   先把死亡風險降到最低       （先救命、爭取時間）\n\n理由\n(複選)\n①棲地已被切割成孤島，石虎移動有危險。\n②危險來自人類活動，人類有責任先把風險降到最低。\n□③遷移後就能一勞永逸，石虎不必再面對任何威脅。\n\n主要作法\n□①先在原棲地加強巡護與宣導，降低人為干擾，讓石虎自然擴散就好。\n②把石虎移到較安全、人為干擾較少、管制更嚴格的區域。\n三、比較觀點差異（用優先順序／介入焦點／判準原則」三個角度）\n  上表我們已經掌握每一方在說什麼；接著請做兩方觀點的比較。\n比較角度\n反對遷移\n支持遷移\n相異\n優先順序\n（單選）\n□①先移到安全處　\n②先讓原棲地變安全\n①先移到安全處　\n□②先讓原棲地變安全\n\n介入焦點\n（單選）\n□①動物搬家\n②原地環境改善\n①動物搬家\n□②原地環境改善\n\n判斷準則\n（單選）\n①怕做錯更危險　\n□②怕不做來不及\n□①怕做錯更危險　\n②怕不做來不及\n相同\n兩派都想降低死亡風險、讓族群更穩定                     \n\n＊歸納觀點差異：\n兩派都看重石虎的安全，但是反對派先做          原地環境改善     ；支持派先做       移動到安全處     。\n\n四、推論主旨（從「觀點差異」推論整篇重點）\n根據你整理的「共同點＋差異」，下列何者最能概括本文主旨？（單選）\n□①介紹石虎的生活習性與野放過程，證明野放一定會失敗\n②比較遷移與不遷移兩派觀點，凸顯保育決策的兩難與取捨\n□③呼籲政府立刻把所有石虎移到保護區，避免再發生路殺犬殺\n\n◎",
    "story_text": "2025年6月底，農業部 生物多樣性研究所（生多所）宣布：「傳奇石虎」豆棗死於犬隻攻擊。豆棗倒臥在雜林中，身上滿布犬咬傷痕，獸醫還在牠體內發現殘留多時的鉛彈，顯示牠曾遭盜獵射擊。2021年4月，命運坎坷的這隻母石虎被送到生多所救援時，只是一星期大的幼貓，身上滿是跳蚤。經過一年照護與訓練，豆棗於2022年4月繫上發報器、成功野放。同年9月，自動相機紀錄到豆棗和兩隻小石虎的身影。但接下來的第二、三胎，因遇到草堆火警和溪水上漲，皆以失敗告終。豆棗的故事，正好反映出瀕危物種保育的困境——要怎麼做，才能讓像石虎這樣的野生動物能避開絕種的命運呢？ 石虎需要連續的棲地，才能覓食、躲避危險、繁衍後代。可是牠們最主要的棲地已經因道路開闢、聚落擴張、農業與工程活動而破碎化。牠們經常慘遭疾駛的汽車路殺、因闖入雞舍而被捕殺、因農人毒鼠而被間接毒殺，更常被遊蕩犬追逐殺害。雖然有少數石虎在保育單位的照護下繁殖，但嘗試野放回到原棲地後，也因前述種種威脅出現很高的死亡率，豆棗就是一例。 於是，一個爭議的問題浮上台面：如果石虎在原棲息地裡越來越難存活，我們該不該「幫牠換個地方」呢？保育界對這個「物種遷移」的議題有非常不一樣的想法。 反對遷移的學者認為，把野生動物「搬家」，看似積極，卻可能引發難以預料的新風險，因此主張先把原棲地變得更安全。他們的理由不只是不捨「干預自然」，也包括法規、倫理與生態後果。首先，「生命自有出口」，野生動物有自主、自生的韌性，能自行克服障礙找到出路。此地不適合生存，石虎自然會尋找別處；相反地，硬把牠們遷至「我們覺得安全」的區域，食物可能不足、地形與植被不符合狩獵需求、新地有其他掠食者與競爭者，甚至讓牠們遭遇新的疾病及人為風險。這一派提出的解方是：與其花大錢移走石虎，不如把資源用在「讓原地變得安全」，例如把破碎棲地用動物廊道重新連接、設減速設施、犬隻管理、改良雞舍、友善農法與補償機制。因為真正要解決的，是人與自然的相處方式，而不是把動物送到看不見的地方。 支持遷移的人則認為應該先把石虎的死亡風險降到最低，他們常用一句話形容自己的立場：「先救命，再談理想。」主要原因是，當棲地已經被切割成孤島，石虎每一次移動都像在走鋼索，單靠「生命自有出口」的信念，可能緩不濟急。再者，他們指出這些威脅多來自人類活動，因此人類就有責任先降低這些風險。他們提出的作法是：先把石虎移到較安全、人為干擾較少、管制更嚴格的區域（例如限制開發的臺北 翡翠水庫保護區），這裡沒有路殺、犬殺，也沒有高衝突的雞舍。但他們也強調，遷移不是放棄原棲地，而是爭取時間：當原棲地修復、廊道建置、社區友善措施逐步到位，僅存的石虎才會有機會擴散、建立更穩定的族群。 讀到這裡，你可能會發現：兩派都不是「不在乎石虎」，差別在於他們對風險的排序不同——一派怕「做錯後難以收拾」，另一派怕「不做就來不及了」。原來，石虎的未來，不只是一個生物學問題，也是一個社會選擇：為了這種可愛的動物，我們願意付出怎樣的改變？你的看法是什麼？",
    "spotlight_answers": [],
