    "title": "盡信書不如無書：從一件殺人案談起",
    "genre": "說明文",
    "authors": "課文 ：曾志朗 學習單：張明珠",
    "strategy_name": "媒體素養與識讀-辨識假新聞",
    "spotlight_raw_text": "閱讀聚光燈\n辨識假新聞\n    數位化時代能讓讀者快速取得資訊，但是也造成了假新聞當道的亂象。如果沒有深入的思考以及查核真相，就很容易做出錯誤的結論，讓我們繼續來當一個聰明的閱聽人，辨別真假訊息吧！。\nＱ1：人為什麼需要新聞？\nＱ2：寫新聞的人是誰？\n一個人不可能同時得知世界大小事，藉由新聞可得知各地發生的訊息。\n這是個言論自由的時代，「每個人」都能在社群媒體發表新聞。\nＱ3：假新聞是什麼？\nＱ4：假新聞背後的目的?\n假新聞是指根據特定目的發表假訊息，引起大眾注意，來達成混淆視聽的目的。\n(1)政治：透過媒體洗腦民眾，來達成特定政黨的目的。\n(2)利益：用假消息創造商機，例如商家說衛生紙要漲價，造成搶購。\nＱ5：我們該怎麼辨識假新聞？\n(1)多查看：檢查消息來源是否可信。\n(2)多思考：新聞的背後目的？新聞服務了誰？誰可能是最大利益者？\n(3)多討論：保持開放的心胸，多和立場不同的人討論。\n(4)多閱聽：平時多看多聽，腦袋裡要有各式各樣的知識。\n(5)多冷靜：看到特別聳動的新聞時，須保持冷靜，謹慎辨別。\n總結：\n真相是根據事實來判定的，每個人都要培養批判性思考的能力。\n\n◎",
    "story_text": "一九六四年，紐約皇后區發生了一件令人髮指的謀殺案，凶手在路燈通明的街道上公然殺人，死者是位叫凱蒂的女人。 《紐約時報》一位記者在凶殺案發生後的兩個星期仔細報導了這個事件，在頭版劈頭就下了個非常煽情的標題：「三十八人目擊謀殺卻未報警，女性被殺事件反映社會的冷漠無情，震驚警界！」報導中的敘述令人毛骨悚然：「有將近半個小時，住在皇后區的38位平日奉公守法的市民，隔窗觀看一名年輕女子在街上被三次追殺，他們的說話聲和開燈的亮光把凶手給嚇跑了，但凶手很快又跑回來追上那名女子，再次舉刀殺人。凶手一再動手的期間，沒有一位市民打電話報警，直到女子被殺死後，才有一個人以電話報警。」亦即，當時這38位目擊者，沒有報警，沒有出聲阻止，當然更沒有人跑出去英雄救美，大家眼睜睜的看著街頭上演了這一場謀殺劇。 心理學家因此提出了「旁觀者效應」的理論，來解釋這個現象。 「旁觀者效應」指的是，若發生緊急情況，旁觀者數量越多，他們當中任何一人出手進行援助之機會越低。例如，老太太騎著車，在你眼前摔倒了，如果附近只有你一個人，你很可能會衝上前幫忙。但是，如果同時有二十個人看見這個意外，你就會有很高的可能袖手旁觀，而不去幫忙。 一九七○年之後，旁觀者效應變成社會心理學界最負盛名的議題，而凱蒂謀殺案和那38位冷漠目擊者的故事，就出現在每一本普通心理學的大學教科書上。教科書總是先頗為詳盡的介紹凱蒂案，再以匪夷所思的形容詞去描繪那38位目擊者的冷漠行徑，最後再以旁觀者效應的理論說明人性的脆弱。四十年如一日，沒有例外。我教普通心理學數十年，每次都要和學生一再討論凱蒂案帶來的啟示，和旁觀者效應的意義。 真的沒有想到，凱蒂案發生43年後，也就是2007年，有三位不信邪的研究者，抽絲剝繭的去對照凱蒂案的警方記錄，發現整個故事根本是《紐約時報》記者杜撰出來的「作品」。首先，根本就沒有那38位目擊者，而且只有兩次追殺，而不是三次。這兩次追殺行兇的地點，都在黑暗而不太能看得清楚的街角，也沒有那麼多有燈光的房間可以數得出一共有38位站在窗前的目擊者；此外，並非無人報警，是有人打了電話到警察局，但接電話的警員不以為意，「吃案」了。 更令人吃驚的是，《紐約時報》報導後，有位律師認為，紐約人再壞，也不可能如此冷血無情。他翻遍警察偵察過程中的各項筆錄，發現記者所說的故事，很多不是事實，充斥著無中生有的情節，他把這些發現寫成一份報告。嚴重的是，這一份報告並不難找，為什麼1970年以來的心理學研究者會對之視若無睹？是因為凱蒂案讓當時的心理學研究者開啟了一扇非常迷人的想像空間，因此才產生如此離譜的選擇性忽略？而隨後數十年的心理學者完全不加質疑，只在講堂上根據教科書的記載，一再敘述一個根本不是事實的故事，也是令人匪夷所思的遺憾。 原來科學家也是會犯錯的，說穿了，犯錯的機率也很高。盡信書不如無書，傳講了幾十年的科學發現或理論，要有一代又一代的年輕人不怕權威，始終抱著「這是真的嗎？」的精神去質疑、去檢驗，才能確保我們能一步一步的逼近真相。這種精神，在假訊息鋪天蓋地的網路世代，更是每一位公民保護自己、保護社會的重要途徑。",
    "spotlight_answers": [],
