    "title": "帝國家書：一個普通家庭的生與死",
    "genre": "說明文",
    "authors": "課文 ：二大爺 學習單：唐儀庭",
    "strategy_name": "分辨事實與判斷",
    "spotlight_raw_text": "閱讀聚光燈\n分辨事實與判斷\n    本篇文章是作者讀完兩封來自秦朝時期的家書後，做了一些推論，最後一段再加上自己的感想後寫成的。\n　　也就是說，文章中的訊息主要有兩大類，第一類是「兩兄弟的處境（以下稱事實）」，第二類是「作者對兩兄弟處境的推論（以下稱判斷）」。閱讀這樣的文章，如果能分辨哪些是客觀的事實，哪些是作者的判斷，就能幫助自己有比較好的理解。\n    那麼什麼是事實？什麼又是判斷呢？\n事實：可以被驗證真假的訊息。例如，第四段提到黑夫的家書寫著「請母親寄衣物或錢」，這是家書中直接呈現且可以從信中驗證的，因此是「事實」。\n判斷：作者基於文章中的事實，結合自己的知識和經驗後所做的推測。例如，從黑夫「請母親寄衣物或錢」這個事實，作者推論秦國服役沒有兵餉，國家只提供武器和口糧，因此屬於「作者判斷」。\n接下來讓我們來練習分辨「事實」與「判斷」吧。\n\n1.基礎題：根據這篇文章，以下的文句是事實的請寫上F，是作者判斷的請寫上J。\n★事實的英文為Fact，判斷的英文為Judgment。\n(1)【 F 】(第三段)文中的家庭有兄弟三人。\n(2)【 F 】(第四段)兄弟倆困在淮陽，缺乏夏衣。\n(3)【 J 】(第八段)黑夫和驚的母親沒有寄錢給他們。\n(4)【 J 】(第十三段)黑夫和驚最終都戰死沙場。\n(5)【 J 】(第十三段)大哥失去兩個弟弟後，深感悲傷和歉疚。\n2.進階題：連連看，將「文章中的事實」與「作者判斷」配對。\n文章事實(第幾段)\n\n作者判斷(第幾段)\n(1)\n驚的家書中再次催促母親寄錢和布料，並提到兄弟倆借錢過活。(7)\n12700028575000●             ●\n秦朝的服役早而重。(5)\n(2)\n黑夫的家書中詢問了軍功是否換來爵位。(4)\n●             ●\n底層民眾將希望寄託在軍功和爵位上。(5)\n(3)\n驚和黑夫都剛成年，而且家裡有三個兄弟，兩個要上戰場。(3)\n●             ●\n黑夫和驚的家庭雖然不算貧困，但仍無法提供足夠的錢給前線的兄弟。(11)\n(4)\n黑夫的家書中請求寄送夏衣或錢財。(4)\n●             ●\n秦兵的裝備和生活用品需要自備。(5)\n\n3.挑戰題：文中作者認為秦國將戰爭的成本轉嫁給底層民眾。下列哪些文中「事實」能支持這個判斷，請將能支持的句子畫O，不能的畫X。\n(1)【 O 】士兵的衣物等必需品需要自備。\n(2)【 O 】許多年輕的男子被徵召入伍。\n(3)【 X 】根據出土文物，秦國一件夏衣的價值是五十五錢。\n(4)【 O 】即使是有一定社會地位的家庭，也無法提供足夠的錢財給在前線的親人。\n(5)【 X 】家書寫在竹簡上，並隨大哥衷下葬。\n\n-46519543\n七",
    "story_text": "西元前225年，秦國拉開滅楚戰爭的大幕。大將李信帶領20萬秦軍攻入楚國，遭遇楚人激烈的抵抗，在淮陽陷入苦戰。秦軍中有兩個小兵，他們是親兄弟，先後給自己的大哥寫了一封家書，當時還沒發明紙，這兩封家書寫在竹簡上。\n戰火中價值萬金的家書不僅安然抵達了八百里外的故鄉——秦國 安陸，而且最終還被收信人帶進了自己的墳墓。1975年，這批竹簡出土，使得我們今天有幸窺見那個龐大帝國底層民眾的血淚和悲哀。\n從信中可以得知，這個家庭有兄弟三人，大哥衷在家贍養母親，二弟驚20歲，剛新婚不久，三弟黑夫17歲，兩個弟弟均在前線征戰。兩份家書字跡相同，顯然是兩兄弟託軍中書吏寫的。這是他們各自的第一封家書，也是最後一封。\n第一封家書是三弟黑夫寫給大哥的。他在信中問候了母親、家人及親友，他說，兄弟倆現在因為戰況困在淮陽，生死難料。因為缺乏夏衣，請母親要嘛做衣服寄來，要嘛直接寄錢；他特別叮嚀母親，千萬不要寄少了。另外，黑夫還關心一件事——他在戰場上搏命，累積了戰功，這些戰功到底有沒有轉換成實質的獎勵？官府如果落實了獎勵，一定要告訴他。\n這封信告訴我們很多殘酷的事實：秦人服役早而重，三個兒子的家庭，兩個得󠇢上戰場，而且都是剛成年的年輕人；更誇張的是，服役顯然完全是義務，不但沒有兵餉，連基本的衣物都要自己準備！很可能國家只提供武器和口糧。我們看慣了課本中兵馬俑英姿颯爽、盔甲整齊的造型，沒想到黑夫寫的才是歷史的事實。秦王的統一大業，底層的民眾不只要出命，還要出錢，這等於是把戰爭的成本轉嫁在底層民眾的身上。民眾唯一的希望就是前方的子弟搏命換軍功，用「爵位」讓家庭得到相應的賞賜和地位。\n那麼家裡的母親和大哥到底有沒有寄錢給兩兄弟呢？\n第二封家書是二弟驚寫給大哥的，這封信口氣就急促多了，信中驚因為沒有收到錢物，再次催促母親給錢。而且明確要錢「五、六百」，布料「二丈五尺」。 他以絕筆的口氣在信中說，兄弟倆現在是借錢過活，如果再不還󠇡錢就要死了。信裡連用了三個「急急」，情況似乎變得極為嚴峻。另外他也很擔心自己的新媳婦，叮嚀大哥不要讓她去離家太遠的地方撿柴火。\n從第二封信中，我們可以肯定，家裡在收到第一封信後，沒能寄錢給他們。他們要求的「五、六百」錢很多嗎？\n根據當時出土的其他文件，秦國一件夏天穿的衣服，值錢五十五，冬天穿的衣服，值錢一百一十。兄弟兩人跟家裡要的「五、六百」，也就是十件夏衣的錢，金額不大，按理一般家庭都能承受，何況他們是立過軍功、有爵位賞賜的家庭。\n親兒子、親兄弟在前線生死未卜，家裡如果拿得出這點錢，會猶豫嗎？會吝嗇嗎？顯然不會。家裡沒有寄錢的唯一原因只可能是，確實沒錢！\n由此我們可以看出，秦國年年征戰，對底層民眾帶來的層層剝削󠇡，帶來多麼嚴酷的影響。大哥的墓地和官吏的墓地挨在一起，陪葬器物中還有文房四寶，這說明他知書識字，在那個年代絕不會是最底層的人家。但就連這樣的人家，居然也拿不出十件夏衣的救命錢！\n那麼黑夫和驚這兩個為大秦拋頭顱灑熱血的年輕人，他們最終結局怎麼樣呢？\n毫無疑問，戰死了。因為如果他們安然返鄉的話，大哥衷完全沒有必要在死後還要把這兩封書信當作陪葬品。一般人都是選最值錢或最珍惜的東西陪葬，只有在兄弟都戰死的情況下，大哥才會把這兩封在當時並不值錢、但對個人是最珍貴的家書帶入地下長眠。這其中，我們真切的感受到身為大哥，失去兩個弟弟之後的悲傷和歉疚。\n電視劇《大秦賦》中的秦帝國無比驕傲、軍容壯盛。但你在仔細讀完這兩封家書後，還會想要成為秦國的子民嗎？也許你沒有回答的勇氣。",
