    "title": "國高中數學課當然可以使用計算機！",
    "genre": "說明文",
    "authors": "課文 ：曾世杰 學習單：高芳瑄",
    "strategy_name": "議論文結構-支持論點的論據",
    "spotlight_raw_text": "閱讀聚光燈\n支持論點的論據\n17780495612\n議論文通常包含四個要素：論點、支持理由、論據和結論。在議論文中，「論點」是作者的觀點，「支持理由」則是作者支持此觀點的原因，「論據」是作者舉出的客觀事實，用來增加支持理由的說服力，最後下一個「結論」。綜合這些要素，整篇文章就形成了完整的結構，讓讀者能夠清楚地了解作者的立場。\n底下只聚焦在支持理由和論據的練習。00\n議論文通常包含四個要素：論點、支持理由、論據和結論。在議論文中，「論點」是作者的觀點，「支持理由」則是作者支持此觀點的原因，「論據」是作者舉出的客觀事實，用來增加支持理由的說服力，最後下一個「結論」。綜合這些要素，整篇文章就形成了完整的結構，讓讀者能夠清楚地了解作者的立場。\n底下只聚焦在支持理由和論據的練習。\n以下為本課整理：\n論點\n學數學可以用計算機。\n支持理由\n因為透過工具外化能降低認知負荷，並有助於達成目標。\n論據\n紙筆\n計算機\n工具\n語言\n文字\n圖書館\n網路\n\n論據檢核：論據要能證明支持理由是對的\n論據舉例\n檢核提問：\n是否降低認知負荷？\n檢核結果：\n是否適合作為論據？\n例一\n利用紙筆記錄數字\n是   □否\n是   □否\n例二\n計算機幫助計算\n是   □否\n是   □否\n◎",
    "story_text": "在國小階段，我贊成林院士的說法。基礎計算能力的自動化當然是數學教育的重中之重，如果7+6還要數手指，8X7還要從「8X1=8、8X2=16……」背起，基礎計算會耗盡所有的大腦資源，大大影響了數學的學習。但是，進了國、高中，「透過計算來深化數學的理解」，這個說法就有待商榷，我認為這個階段的學生若有計算機做為「大腦工具」，可望大幅增加學習的效能。 先舉例說明什麼是「大腦工具」。文字及紙筆就是大腦工具中的一種，一般人無法心算二位數的加減乘除（如65X23=?），但這只是大腦容量不足，無法同時負載這麼多的數字，並不表示計算能力闕如。只要紙筆在手，把腦袋裡的數字「外化」成白紙上的黑字，大腦負荷超載的問題立刻迎刃而解，每一個人都能輕易解題。在這個例子裡，同一個人在「無紙筆」和「有紙筆」狀況下的表現，會有小老鼠與大象的差別。同樣的，計算機是功能更強大的大腦工具，我主張把複雜的計算「外化」給計算機完成後，學生的數學學習才可能更精進、更有效率，小老鼠可以躍升為大象。 例如，國中數學課，老師請同學們測量出教室裡各種長方形的寛邊（a）、長邊（b）和對角線（c）長度，如學生書桌、講桌、窗戶等，再把數據帶入畢氏定理的公式（a2+b2＝c2），以檢驗畢氏定理是否放諸四海皆準，適用於每一個不同的直角三角形。請問：以上的教學活動中，哪一個步驟是國中生數學學習的重點？我想應該不會有人說是乘除計算的正確性與速度。 「透過計算來深化數學理解」的說法，在這裡顯然是不適用的。學生測量得到的三個長度，可能都不是整數，計算起來容易出錯，這時候使用計算機，會幫助學生節省心力，更專注於數學概念的理解。把繁複的計算交給計算機後，學生的大腦可以騰出空間來做更重要的理解、推理和問題解決，才更可能享受數學的實用與美麗。 其實，人類的文明發展，就是一部把能力、經驗與知識「外化」的歷史。當人類祖先執起長竿打落樹上的果實，或撿起石子丟向獵物時，他異於禽獸之處，在於把自身的力量外化到長竿和石子上了；當最早使用語言的祖先，大喊：「有蛇！」以警告旁人時，他異於禽獸之處，在於把感官經驗外化成語言，將攸關生命的警報分享給同伴。六千年前，語言被外化成書面文字，知識得以有系統的被保存，讓今人仍然可知二千五百年前孔子講了什麼，人類的溝通因此得以跨越時空。二十世紀的圖書資訊專業，將數千年來累積的知識從書籍外化到圖書館；而二十一世紀電腦、網路及行動裝置的興起，又讓圖書館被外化到網路上。 也就是說，當前的世界已經把大量極為複雜的知識及計算外化，我們國家的數學教育當然也要有前瞻性，讓國、高中生學習時部分的心智歷程外化，使用計算機讓數學學習更有效能，此時的我們還規定國、高中數學課不能使用計算機，那實在太不可思議了些。",
    "spotlight_answers": [],
