    "title": "靈異與科學",
    "genre": "說明文",
    "authors": "課文 ：吳漢庭 學習單：巫怡蓉",
    "strategy_name": "解決問題-科學探究法",
    "spotlight_raw_text": "閱讀聚光燈\n解決問題－科學探究法\n    科學是以系統的方法解決問題的學問。若能善用科學方法，除了可以培養明辨是非的能力，也可以解決生活中的問題喔。\n解決科學問題的步驟：\n我們看到一個現象，可以利用「為什麼」或「是什麼」的問題，一層一層的提問，找出問題的解答。\n(1)提出問題（發現問題與定義問題）：對所見現象抱持好奇心，發現尚未解決的問題，確認「問題」是什麼？\n注意：要提出清楚、可回答的問題。\n(2)提出假設：從既有的知識基礎上，提出問題的可能答案。\n注意：假設應該根據基於「客觀的事實」，避免只有主觀的意見。（客觀指的是每一個人看到的都一樣；主觀指的是大家對同樣的事情有不同的意見。）\n(3)檢驗假設：蒐集資料，小心求證，檢驗假設是否正確。\n總結：學習好奇的事物問「為什麼」，是科學訓練的起點。\n\n16567154762500\n\n◎",
    "story_text": "「中國人怕鬼、西洋人也怕鬼，全世界的人都怕鬼。恐怖喔！恐怖到了極點喔！」這是已故的鬼故事大師──司馬中原的名言。人類對於死後世界的恐懼，跨越世代與文化。傳說中的鬼魂、幽靈，以及各種不可思議的超自然事件，一直都是引人入勝的故事題材。然而，在這些看似神祕的故事背後，科學家有沒有合理的解釋呢？ 現象一：鬼火 鬼火通常出現在炎熱的夏天，夜裡趕路的行人經過墳場時，就可能看見黑暗中閃爍飄動的淡藍色或淡綠色的火焰，讓人毛骨悚然。人類是唯一會想像死後世界的動物，夜裡在墳場黑暗中乍見搖曳浮盪的藍光，人們難免聯想死去的生命──鬼魂，說不害怕還真不可能。新聞節目說，曾經有盜墓賊在烏漆墨黑的墳場被鬼火嚇跑，甚至被活活嚇死。 科學界對鬼火現象提出一個解釋—人類及動物的遺骸腐化後，產生了「磷化氫」，這種氣體很輕，燃點很低，從地底浮到地面後，在常溫下就會自燃。但，這個說法最啟人疑竇之處：鬼火是藍色的，但磷化氫燃燒起來是明亮的黃光。後來一名英國地理學家提出了修正的解釋──冷焰。屍體腐壞後散發出的磷化氫和濕地的沼氣及空氣混合，形成燃點很低的可燃氣體，攝氏30度左右就可以燃燒，但它的燃燒不劇烈，必須在非常暗的地方才可看見，而且顏色多為藍色或淡紫色，所以被稱為「冷焰」。如果這個說法正確，就可以解釋為什麼最常見到鬼火的時間是夏天，地點是墳場了。 現象二：鬼壓床 你也許有過這樣的經驗：在入睡或剛醒來時，感覺自己被一股力量重重的壓著，想逃，動彈不得；想喊，喑啞無聲；想起身醒來，卻陷在噩夢裡醒不過來，這種難受的感覺被稱為「鬼壓床」。不同文化的人們，普遍把這個現象和鬼神靈巫聯結起來，認為是有幽冥世界的鬼魂壓制了睡眠者、企圖傷害睡眠者，或想要傳遞警告的訊息。但科學家怎麼解釋鬼壓床呢？ 科學家發現人類每晚大概有四到六次的睡眠週期，每次約90分鐘，每個週期又有「淺睡期」、「中睡期」、「深睡期」及「快速眼動期」四個階段。快速眼動期時，眼球在眼皮下快速的移動著，沈睡的大腦又活躍起來，腦波看來很熱鬧，和白天醒著時差不多，但是，睡眠者此時卻無法控制全身的肌肉、癱軟無力。如果你在此時推一推睡眠者說：「欵，起來啦。」睡眼惺忪的他，有八九成的機會告訴你，他正在作夢。 醫學上把鬼壓床稱作「睡眠癱瘓症」，它就發生在快速眼動期。患者此時正在作噩夢，卻覺得自己醒著，能睜開雙眼、能看到周圍事物、能聽到聲音，然而卻發現自己無法自主移動，也無法發出聲音。其實，睡眠者此時動彈不得才是對自己最好的保護。想想看，如果作夢時手腳身體是能動的，你正夢見被窮凶極惡的匪徒追殺，你為了防衛自己，回身給他一記詠春拳、一腳迴旋踢。糟了，你可能一拳打破了旁邊的玻璃，一腳踢在水泥牆上，把趾甲踢斷了，那才慘呢。 睡眠癱瘓症是睡眠障礙的一種，這種情況通常是暫時性的，大多數人偶爾會有這樣的經驗。但如果睡眠癱瘓症出現頻繁，並對生活產生影響，就建議就醫，進行進一步的評估和治療。 鬼火和鬼壓床雖然被許多人解釋為靈異現象，但理性的科學方法，讓我們對這些現象有了客觀的認識。另外，你有沒有發現，對同樣的現象，鬼魂說和科學說，分別帶給你驚悚可怕和有趣好奇的情緒呢？有一位社會學家說，現代文明的特色之一就是「除魅」，把鬼魅從我們的世界裡驅除了，你認為呢？",
    "spotlight_answers": [],
