        "question": "1. 達爾文在收到大彗星蘭標本時，最令他驚訝的是什麼？ A.花朵帶有約30公分長的花距 B.蘭花的花朵潔白芳香，形狀如星 C.蘭花屬於達爾文未見過的新品種 D.蘭花裡藏著一隻巨型飛蛾",
