    "title": "臺灣的太空之眼",
    "genre": "說明文",
    "authors": "課文 ：林玫伶 學習單：陳淑麗",
    "strategy_name": "摘要策略-小標題的作用：找細節",
    "spotlight_raw_text": "閱讀聚光燈\n摘要策略──\n小標題的作用：找細節\n　　本課是一篇說明文，文章用小標題分段，分別說明文章主題的不同面向。閱讀這類文章，你只要抓住三件事就能掌握重點：\n一、大主題是什麼？\n二、每個小標題在說明哪個面向？\n三、每個面向最重要關鍵的細節是什麼？\n接下來，我們就來做這三件事：確認大主題與小主題、找重要細節。\n一、確認大主題\n說明文的「大主題」通常就是文章標題。大主題要精簡，也要抓到本文最核心的概念。\n1473261421800下列哪一個名稱，也可做為本文的大主題？（單選）                    \n □①齊柏林號：升空的第一步   ②福衛八號：守望臺灣的衛星星系\n二、小主題定位＋找重要細節（扣住小主題，挑出最關鍵的句子）\n本文每段資訊都很多，請用小主題抓住這段的重點，並挑出最能支持小主題的「重要細節」句子。\n（一）第3~4段〈宇宙中的巡邏隊〉\n  1.小主題-這段重點最接近哪個標題：(單選)\n①星系接力觀測：間隔變短、看得更清楚\n□②衛星速度驚人：太空中的高速飛行\n2.找重要細節：哪些句子最能直接支持你選的小主題？(4選2)\n□①福衛八號從2025起逐年發射，到2031全部就位。\n□②衛星在約561公里的太陽同步軌道運行，輪流拍攝。\n③星系完成後，觀測間隔將大幅縮短，能更快取得影像。\n④解析度比以往更高，能看清災區地形、道路、建築、農田。\n3.精簡成一句話(3選1)\n①星系完成後觀測更頻繁、影像更清楚，能更快掌握災情。\n□②衛星在太陽同步軌道運行，所以速度很快、很壯觀。\n□③福衛八號會逐年發射到2031，形成一套完整的觀測系統。\n（二）第５～６段〈沒有「重來」的按鈕〉\n  1.小主題-這段重點最接近哪個標題：(單選)    \n□①太空環境嚴酷：溫差、輻射與隕石　\n②失誤難挽回：發射前要反覆測試\n2.找重要細節：哪些句子最能說明小主題的重點?(4選３)\n①在地球上壞了可以修，但在太空失誤往往覆水難收。\n②太空環境嚴酷，有溫度變化、輻射和微小隕石撞擊。\n③因此發射前必須在地面經歷無數次的模擬測試。\n□④衛星只有冰箱大小，但內部塞滿精密相機和推進系統。\n3.精簡成一句話(3選1)\n①太空危險多、失誤很難補救，所以發射前必須反覆模擬測試。\n□②太空環境很嚴酷，所以衛星要縮小到冰箱大小，較不易故障。\n□③人造衛星設備太精密了，所以發射成功主要靠運氣。\n（三）第7段〈星光背後的二十年〉\n1.小主題-這段重點最接近哪個標題：(單選)\n①二十年太空里程：從仰賴他國到自主製造\n□②二十年太空厲害：解析度更高、看得更清楚\n2.找重要細節：哪些句子最能說明小主題的重點？(4選2)\n□①臺灣位處地震帶與颱風路徑上，需要更快掌握災情。\n②福衛八號有許多關鍵零件，由臺灣本土團隊研發製造。\n③自1999年福衛一號起，二十多年累積，從仰賴他國走到自主製造。\n□④就像運動員磨練成國手，象徵每一步都在挑戰極限。\n3.精簡成一句話(2選1)\n①臺灣累積二十多年太空經驗，逐步從仰賴走向自主製造。\n□②臺灣關鍵零件自己研發，因此衛星資料一定最準也最完整\n（四）第8段〈「齊柏林」守望臺灣〉\n找重要細節：請寫出最能支持「「齊柏林」守望臺灣」的句子。\n透過衛星影像，我們能更快速的掌握災情、守護國土。             \n（五）第9段〈守護家園，也有你一份〉\n請先找出最能支持「守護家園與，也有你一份」的細節，並精簡為一句話。（答案合理即可）\n衛星為我們守望家園，你可以成為那個看見臺灣、珍惜臺灣的人。   \n\n◎",
    "story_text": "2025年11月29日凌晨，當整座城市萬籟俱寂、沉入夢鄉時，位於新竹的國家太空中心（TASA）卻是一片緊張氣氛。工程師們緊盯螢幕上的數據，現場安靜得連心跳聲都聽得到。 凌晨2點44分，美國 加州傳來振奮的消息：SpaceX 的獵鷹9號火箭拖著長長的尾焰，載著「福衛八號」計畫的首顆衛星——「齊柏林」號，呼嘯著劃破天際。臺灣時間的清晨5點34分，當螢幕跳出它從外太空傳回的訊號時，現場情緒潰堤、掌聲如雷。 宇宙中的巡邏隊 福衛八號是一支由8顆光學遙測衛星組成的「衛星星系」，從2025年起逐年發射，到2031年全部就位，形成一套縝密周延的觀測系統。這些衛星會在地球上空約561公里的太陽同步軌道運行，彼此分工合作、相互接力，就像一支日夜不休的巡邏隊，輪流飛過臺灣和周邊地區的上空拍攝。 它們的速度比子彈快，一秒鐘可以跑7.5公里，快過方程式賽車300倍，即使如此，仍需90到100分鐘才能繞過臺灣上空一次，只有一顆衛星時，如果發生重大災難（如2025年花蓮 光復堰塞湖潰決），必須隔好一段時間才能拍到同一個地點；星系完成後，觀測間隔將大幅縮短，能更快取得影像。不僅如此，它們的「視力」也大幅提升，拍攝影像的解析度比以往的衛星更高，可以清楚看見災區地形、道路、建築、農田等地表細節，簡直就是千里眼。 沒有「重來」的按鈕 送衛星上天，是一場艱鉅的挑戰。在地球上，機器壞了可以修；但在距離地面561公里的軌道上，一旦失誤，往往覆水難收，沒有第二次機會。 太空環境非常嚴酷，衛星必須承受劇烈的溫度變化、強大的輻射、微小隕石的撞擊。因此，衛星在發射前，必須在地面經歷無數次的模擬測試。福衛八號雖然只有冰箱大小，但麻雀雖小，五臟俱全，內部塞滿了精密的相機和推進系統。每一個零件、每一道程序，都必須層層檢驗，才能把它送上太空。也正因為沒有重來的機會，每一次成功都需要長期累積。 星光背後的二十年 最令人自豪的是，福衛八號有許多關鍵零件，是由臺灣本土團隊研發製造的，這代表我們不再需要仰人鼻息。臺灣的太空之路，絕非一蹴可幾󠇡，自1999年發射「福衛一號」開始，從仰賴他國到臺灣自製，從單顆衛星到衛星星系，二十多年的累積，每一步都在挑戰極限，就像一名運動員從實習生磨練成國手，最終在星空中刻下屬於臺灣的名字。臺灣位處地震帶與颱風路徑上，多少科學家在水滴石穿的努力之後，我們終於有了能夠守望家園、未雨綢繆󠇡的太空科技。 「齊柏林」守望臺灣 福衛八號首顆衛星的名字，是為了紀念已故的紀錄片導演齊柏林。齊導演生前透過空拍鏡頭，拍下了《看見台灣》。他讓我們看見阿里山的壯闊，也讓我們看見河流被染紅、山林被濫墾的傷痕。他曾說：「當你看見這片土地的美麗與哀愁，才能真正祝福她。」現在，齊導演雖然不在了，但這顆衛星繼承了他的眼睛，透過衛星影像，我們能更快速的掌握災情、守護國土，也讓齊導演的精神在500多公里的高空延續，守望這片我們熱愛的土地。 守護家園，也有你一份 或許你會覺得外太空遙不可及，但請記得，這不是課本裡的冷冰冰的知識，而是與你我生活休戚與共的真實故事。當這八顆衛星全部就位，敏銳的「太空之眼」就會日夜在五百多公里的高空，為我們守望家園。你不一定要會設計衛星，但你可以成為那個「看見臺灣、珍惜臺灣」的人。",
    "spotlight_answers": [],
