    "title": "不量田",
    "genre": "文言文",
    "authors": "學習單： 王淑瑱",
    "strategy_name": "判讀主語",
    "spotlight_raw_text": "文言聚光燈：判讀主語\n文言文類型\n記敘人物\t\n\n-27940-18224500第3課　不量田  \n學習單：\n王淑瑱\n古文今譯\n某位商人，來到直隸省的邊界附近，忽然下起大冰雹，他連忙躲到田間。突然，他聽到空中有聲音說：「這是張不量的田，不要傷了他的莊稼。」商人心想：這張氏既然叫「不良」，為何反而受上天庇佑？等冰雹停止，商人進入村子，向人打聽那個人，並且詢問那人叫這名字的意思。\n原來張氏素來富有，積蓄的穀物很多。每到春天，窮人就來找他借貸穀物，償還時，不管還了多少也不計較，全都收下，不曾拿工具測量，要人還到足夠的數量，所以才叫他「不量」，並非「不良」啊！後來眾人趕到田中，只見麥子被冰雹砸得像亂麻一樣，只有張氏的田一點事也沒有。\n　　　　　　　　　　　　\n清朝・蒲松齡\n  \n賈人.某，至.直隸1界，忽.大雨󠇡2雹，伏.禾中。聞.空中.云：「此.張不量󠇡田，勿傷.其稼。」賈.私意.張氏既云「不良」，何反.佑護？雹止，入村，訪問.其人，且問.取名之義。\n蓋.張素豐，積粟.甚富。每春間.貧民就貸，償時.多寡不較，悉納之，未嘗.執概3取盈4，故名.「不量󠇡」，非.不良也。眾趨.田中，見稞穗.摧折如麻，獨.張氏諸田.無恙5。\n\n487643185345注釋\n1.直隸：清代的直隸省，現在中國的河北省。\n2.大雨雹：雨，當動詞，表示落下的意思。「大雨雹」的意思是下了很大的冰雹。\n3 \t概：用來刮平「米斗」的工具。米斗，交易時用來測量米量的容器。\n4 \t盈：有「滿」的意思，課文是指足夠的數量。\n5 \t恙：疾病或異樣。「無恙」的意思是沒有病痛、憂慮，課文是指沒事。\ncenter145938\n1. 請用計時器，朗讀原文，並將讀完的時間記錄在表格中。如果你計時3次後，對自己還不滿意，可以自己多練幾次喔。最後一次，找一位同學，請他來計時、記錄並簽名！\n2. 文章中的「.」是表示斷詞的地方，朗讀時，不要把「同組的詞」分開。00\n1. 請用計時器，朗讀原文，並將讀完的時間記錄在表格中。如果你計時3次後，對自己還不滿意，可以自己多練幾次喔。最後一次，找一位同學，請他來計時、記錄並簽名！\n2. 文章中的「.」是表示斷詞的地方，朗讀時，不要把「同組的詞」分開。\n\n第1次計時\n第2次計時\n第3次計時\n裁判計時\n秒\n秒\n秒\n秒\n\n裁判簽名:                \n\n◎",
