    "strategy_name": "一字多義「少」",
    "spotlight_raw_text": "文言聚光燈：一字多義：「少」\n文言文類型\n記敘人物\t\n\n-27940-18224500第8課  愛讀書的顧寧人  \n學習單：\n王淑瑱\n古文今譯\n崑山有一位顧寧人先生，生長在世代做官的家族，年少時就擁有超越其他人的資質，他專注於研究古代的學問，儒家的書及各種史書，差不多都能背誦。\n他的精力超越一般人，沒有其他嗜好，從小到老，從來沒有一天不讀書。出門時，車上一定要帶上幾箱的書隨行，到旅店稍微休息後，就翻找書箱拿書出來讀，從不曾表現出疲倦的樣子來。\n清朝・潘耒\n  \n崑山.顧寧人.先生，生長󠇡.世族，少󠇡負.絕異之資，潛心古學，九經.諸史，略能.背誦。\n精力.絕人，無他.嗜好󠇡，自少󠇡.至老，未嘗.一󠇡日.廢書。出.必載書.數簏1.自隨，旅店少休，披尋.搜討，曾無.倦色。\n487643185345注釋\n1.\t簏：竹子編成的箱子。\n-46930163830\n1. 請用計時器，朗讀原文，並將讀完的時間記錄在表格中。如果你計時3次後，對自己還不滿意，可以自己多練幾次喔。最後一次，找一位同學，請他來計時、記錄並簽名！\n2. 文章中的「.」是表示斷詞的地方，朗讀時，不要把「同組的詞」分開。00\n1. 請用計時器，朗讀原文，並將讀完的時間記錄在表格中。如果你計時3次後，對自己還不滿意，可以自己多練幾次喔。最後一次，找一位同學，請他來計時、記錄並簽名！\n2. 文章中的「.」是表示斷詞的地方，朗讀時，不要把「同組的詞」分開。\n\n第1次計時\n第2次計時\n第3次計時\n裁判計時\n秒\n秒\n秒\n秒\n\n裁判簽名:                \n\n◎",
