    "title": "荒野救亡記",
    "genre": "文言文",
    "authors": "學學習單：王淑瑱",
    "strategy_name": "固定句式：以--為.",
    "spotlight_raw_text": "文言聚光燈：固定句式\n文言文類型\n.\t\n\n-27940-18224500第10 課  荒野救亡記\n學學習單：王淑瑱\n\n古文今譯\n魏國的鮑子都某天傍晚走在荒野，碰巧見到一名書生突然心絞痛。鮑子都立刻下馬，為他按摩心臟。不久，書生還是死了。鮑子都看書生的袋子裡有一冊兵書和十個金餅，就賣了一個金餅，把賣的錢全用來安葬書生，剩下的九個金餅就墊在書生的頭下，兵書也放在書生的肚子邊。\n幾年後，子都在路上，一位騎著駿馬的人追趕他。等到那人追上以後，把子都當作強盜，還一再追問鮑子都他兒子的屍身在哪裡。鮑子都就把當時的情況全說了，然後那個人跟隨鮑子都來到書生的墓前。\n那人挖開墳墓，取出兒子的屍身要帶回去，果然看到九個金餅墊在兒子的頭下，兵書也在身旁。書生全家都非常感謝鮑子都的恩德與義舉。從此鮑子都的名字與事蹟被眾人口耳相傳，一下子就有名起來了。\n\n唐朝・李亢\n\n魏　鮑子都󠇡，暮行於野，見一󠇢書生卒󠇡1心痛。子都󠇡下馬，為󠇡摩其心。有頃2，書生卒。子都󠇡視其囊中，有《素書》3一󠇡卷，金十餅。乃賣一󠇢餅，具葬書生，其餘枕󠇡之頭下，置素書於腹旁。\n後數年，子都󠇡於道上，有乘驄馬者逐之。既及，以子都󠇡為盜，固問兒屍所在。子都󠇡具言，於是相󠇡隨往。\n開墓，取兒屍歸，見金九餅在頭下，素書在腹旁。舉家感子都󠇡之德義。由是聲名大振。\n487643185345注釋\n卒：ㄘㄨˋ，通「猝」。急促、突然。\n有頃：不久、一會兒。\n卒：死亡。\n素書：兵書。\n枕：ㄓㄣˋ，當動詞，用什麼東西墊頭。\n\ncenter45720\n1. 請用計時器，朗讀原文，並將讀完的時間記錄在表格中。如果你計時3次後，對自己還不滿意，可以自己多練幾次喔。最後一次，找一位同學，請他來計時、記錄並簽名！\n2. 文章中的「.」是表示斷詞的地方，朗讀時，不要把「同組的詞」分開。00\n1. 請用計時器，朗讀原文，並將讀完的時間記錄在表格中。如果你計時3次後，對自己還不滿意，可以自己多練幾次喔。最後一次，找一位同學，請他來計時、記錄並簽名！\n2. 文章中的「.」是表示斷詞的地方，朗讀時，不要把「同組的詞」分開。\n\n第1次計時\n第2次計時\n第3次計時\n裁判計時\n秒\n秒\n秒\n秒\n\n裁判簽名:                \n\n◎",
    "story_text": "魏國的鮑子都某天傍晚走在荒野，碰巧見到一名書生突然心絞痛。鮑子都立刻下馬，為他按摩心臟。不久，書生還是死了。鮑子都看書生的袋子裡有一冊兵書和十個金餅，就賣了一個金餅，把賣的錢全用來安葬書生，剩下的九個金餅就墊在書生的頭下，兵書也放在書生的肚子邊。\n幾年後，子都在路上，一位騎著駿馬的人追趕他。等到那人追上以後，把子都當作強盜，還一再追問鮑子都他兒子的屍身在哪裡。鮑子都就把當時的情況全說了，然後那個人跟隨鮑子都來到書生的墓前。\n那人挖開墳墓，取出兒子的屍身要帶回去，果然看到九個金餅墊在兒子的頭下，兵書也在身旁。書生全家都非常感謝鮑子都的恩德與義舉。從此鮑子都的名字與事蹟被眾人口耳相傳，一下子就有名起來了。",
